def check_docx_keywords__8c8e551c645c8d069577024a9d0bf137(result, expected, **options):
    """Check if document contains expected keywords and meets structure requirements.

    Args:
        result: Dict from getter with 'paragraphs', 'word_count', 'paragraph_count', 'full_text'
        expected: Dict with 'required_keywords', 'excluded_keywords', 'min_word_count',
                  'min_paragraph_count', 'expected_sections'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or 'error' in result:
        return 0.0
    full_text = result.get('full_text', '')
    full_text_lower = full_text.lower()
    word_count = result.get('word_count', 0)
    paragraph_count = result.get('paragraph_count', 0)
    paragraphs = result.get('paragraphs', [])
    required_keywords = expected.get('required_keywords', [])
    excluded_keywords = expected.get('excluded_keywords', [])
    min_word_count = expected.get('min_word_count', 0)
    min_paragraph_count = expected.get('min_paragraph_count', 0)
    expected_sections = expected.get('expected_sections', [])
    score = 0.0
    if word_count >= min_word_count:
        score += 0.2
    if paragraph_count >= min_paragraph_count:
        score += 0.15
    if required_keywords:
        keywords_found = sum((1 for kw in required_keywords if kw.lower() in full_text_lower))
        keyword_ratio = keywords_found / len(required_keywords)
        score += 0.35 * keyword_ratio
    if excluded_keywords:
        excluded_found = any((kw.lower() in full_text_lower for kw in excluded_keywords))
        if not excluded_found:
            score += 0.2
    if expected_sections:
        sections_found = sum((1 for section in expected_sections if any((section.lower() in p.lower() for p in paragraphs))))
        section_ratio = sections_found / len(expected_sections)
        score += 0.1 * section_ratio
    return min(score, 1.0)

def check_page_number_colors__a345b827(pptx_file, rules):
    """
    Check if the slide page numbers have been changed to the expected color.

    Args:
        pptx_file: Path to the PPTX file
        rules: Dict with 'color' key (e.g., 'blue', 'red', 'green', 'black')

    Returns:
        float: 1.0 if color matches, 0.0 otherwise
    """
    color = rules['color']

    def is_red(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[0:2], 16), int(rgb_str[2:4], 16), int(rgb_str[4:6], 16))
        return r > g + threshold and r > b + threshold

    def is_blue(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[0:2], 16), int(rgb_str[2:4], 16), int(rgb_str[4:6], 16))
        return b > g + threshold and b > r + threshold

    def is_green(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[0:2], 16), int(rgb_str[2:4], 16), int(rgb_str[4:6], 16))
        return g > r + threshold and g > b + threshold

    def is_black(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[0:2], 16), int(rgb_str[2:4], 16), int(rgb_str[4:6], 16))
        return r < threshold and g < threshold and (b < threshold)
    with zipfile.ZipFile(pptx_file, 'r') as zip_ref:
        namespaces = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main', 'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}
        try:
            with zip_ref.open('ppt/presentation.xml') as pres_file:
                pres_tree = ET.parse(pres_file)
                pres_root = pres_tree.getroot()
                slide_ids = pres_root.findall('.//p:sldId', namespaces)
                if not slide_ids:
                    return 0.0
        except:
            pass
        slide_master_files = [f for f in zip_ref.namelist() if f.startswith('ppt/slideMasters/slideMaster') and f.endswith('.xml')]
        page_number_color = None
        for slide_master_name in slide_master_files:
            try:
                with zip_ref.open(slide_master_name) as slide_master_file:
                    tree = ET.parse(slide_master_file)
                    root = tree.getroot()
                    placeholders = root.findall('.//p:sp', namespaces)
                    for placeholder in placeholders:
                        ph_elem = placeholder.find('.//p:nvSpPr/p:nvPr/p:ph', namespaces)
                        if ph_elem is not None:
                            ph_type = ph_elem.get('type')
                            if ph_type == 'sldNum' or ph_type == 'ftr':
                                color_elem = placeholder.find('.//a:solidFill/a:srgbClr', namespaces)
                                if color_elem is not None:
                                    page_number_color = color_elem.get('val')
                                    break
                                scheme_color_elem = placeholder.find('.//a:solidFill/a:schemeClr', namespaces)
                                if scheme_color_elem is not None:
                                    color_elem = placeholder.find('.//a:srgbClr', namespaces)
                                    if color_elem is not None:
                                        page_number_color = color_elem.get('val')
                                        break
                    if page_number_color:
                        break
            except:
                continue
        if page_number_color is None:
            for slide_master_name in slide_master_files:
                try:
                    with zip_ref.open(slide_master_name) as slide_master_file:
                        tree = ET.parse(slide_master_file)
                        root = tree.getroot()
                        shapes = root.findall('.//p:sp', namespaces)
                        for shape in shapes:
                            text_elems = shape.findall('.//a:t', namespaces)
                            for text_elem in text_elems:
                                if text_elem.text and '<#>' in text_elem.text:
                                    color_elem = shape.find('.//a:solidFill/a:srgbClr', namespaces)
                                    if color_elem is not None:
                                        page_number_color = color_elem.get('val')
                                        break
                            if page_number_color:
                                break
                    if page_number_color:
                        break
                except:
                    continue
    if page_number_color is None:
        return 0.0
    if color == 'red' and (not is_red(page_number_color)):
        return 0.0
    elif color == 'blue' and (not is_blue(page_number_color)):
        return 0.0
    elif color == 'green' and (not is_green(page_number_color)):
        return 0.0
    elif color == 'black' and (not is_black(page_number_color)):
        return 0.0
    return 1.0

def check_docx_title_italic__a82a48957dc18e1ea9d6a72eb5b5cab9(result_state: Dict[str, Any], expected_state: Dict[str, Any], **options) -> float:
    """
    Check if the document title has italic formatting as expected.

    Args:
        result_state: Result from getter (dict with "is_italic" key)
        expected_state: Expected state from task config (dict with "is_italic" key)
        **options: Additional options

    Returns:
        float: 1.0 if italic formatting matches expected, 0.0 otherwise
    """
    try:
        result_italic = result_state.get('is_italic', False)
        expected_italic = expected_state.get('is_italic', False)
        logger.info(f'Checking italic formatting - Result: {result_italic}, Expected: {expected_italic}')
        if result_italic == expected_italic:
            logger.info('✅ Italic formatting matches expected state')
            return 1.0
        else:
            logger.info('❌ Italic formatting does not match expected state')
            return 0.0
    except Exception as e:
        logger.error(f'Error checking docx title italic: {e}')
        return 0.0

def check_writer_font_size__55ccef6016ddd62f70d2e0ecf1a283d1(result, expected, **options):
    """Check if the LibreOffice Writer default font size matches the expected value.

    Args:
        result: The actual font size (int or None)
        expected: Dict with 'font_size' key containing expected size
        **options: Additional options (not used)

    Returns:
        float: 1.0 if match, 0.0 otherwise
    """
    expected_size = expected.get('font_size')
    if result is None:
        logger.error('Result is None - font size not found')
        return 0.0
    if expected_size is None:
        logger.error('Expected font size not specified')
        return 0.0
    if result == expected_size:
        logger.info(f'Font size matches: {result} == {expected_size}')
        return 1.0
    else:
        logger.info(f'Font size mismatch: {result} != {expected_size}')
        return 0.0

def check_font_size__fc8c3e93(result, expected, **options):
    """
    Check if Chrome's default font size is at least the expected minimum.
    This metric checks for a minimum font size of 19px.
    
    Args:
        result: Font size data from getter (dict with 'default_font_size' key)
        expected: Expected font size range (dict with 'min' and 'max' keys)
        **options: Additional options (not used)
    
    Returns:
        float: 1.0 if font size is within range, 0.0 otherwise
    """
    if not result:
        logger.error('No font size data provided')
        return 0.0
    if not isinstance(result, dict):
        logger.error(f'Invalid result format: {type(result)}, expected dict')
        return 0.0
    default_font_size = result.get('default_font_size', 16)
    min_value = expected.get('min', 19)
    max_value = expected.get('max', 99999)
    logger.info(f'Expected font size range: [{min_value}, {max_value}]px')
    logger.info(f'Actual font size: {default_font_size}px')
    if min_value <= default_font_size <= max_value:
        logger.info('Font size is within expected range')
        return 1.0
    else:
        logger.info(f'Font size out of range: expected [{min_value}, {max_value}], got {default_font_size}')
        return 0.0

def check_odt_word_replaced__7b317ae0(result, expected, **options):
    """Check if word replacement was successful.

    Args:
        result: Count of the replacement word from getter
        expected: Dict with 'min_count' key for minimum expected occurrences
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, int):
        return 0.0
    min_count = expected.get('min_count', 1)
    if result >= min_count:
        return 1.0
    else:
        return result / min_count if min_count > 0 else 0.0

def check_docx_bullet_para_count__2fbb6272(result: int, expected: Any, **options) -> float:
    """Check if the number of bulleted paragraphs matches expected.

    Args:
        result: Number of bulleted paragraphs from getter
        expected: Expected count (from rules dict)
        **options: Additional options

    Returns:
        float: 1.0 if matches, 0.0 otherwise
    """
    expected_count = expected.get('count', 0)
    if result == expected_count:
        return 1.0
    else:
        return 0.0

def check_writer_text_list__592c042e86aba9b7d5a9be8008d4a4f0(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if Writer document contains expected text items.

    Args:
        result: Dict from getter with text content
        expected: Dict with expected items and count
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if 'error' in result:
        return 0.0
    score = 0.0
    if 'expected_paragraph_count' in expected:
        expected_count = expected['expected_paragraph_count']
        actual_count = result.get('paragraph_count', 0)
        if actual_count == expected_count:
            score += 0.4
    if 'expected_items' in expected:
        expected_items = expected['expected_items']
        paragraphs = result.get('paragraphs', [])
        all_text = ' '.join(paragraphs)
        for table in result.get('tables', []):
            for row in table:
                all_text += ' ' + ' '.join(row)
        found_count = 0
        for item in expected_items:
            if str(item) in all_text:
                found_count += 1
        if len(expected_items) > 0:
            item_score = found_count / len(expected_items)
            score += 0.6 * item_score
    return min(score, 1.0)

def check_writer_paragraph_spacing__53c369c9a6a37ed3fba6c72140256820(result, expected, **options):
    """Check if the LibreOffice Writer paragraph spacing matches the expected values.

    Args:
        result: The actual paragraph spacing (dict or None)
        expected: Dict with expected 'above' and/or 'below' spacing in mm
        **options: Additional options (not used)

    Returns:
        float: 1.0 if all spacing matches, partial credit for some matches, 0.0 if none match
    """
    if result is None:
        logger.error('Result is None - paragraph spacing not found')
        return 0.0
    if not isinstance(result, dict) or not isinstance(expected, dict):
        logger.error('Invalid result or expected format')
        return 0.0
    total_checks = 0
    matches = 0
    if 'above' in expected:
        total_checks += 1
        expected_above = expected['above']
        actual_above = result.get('above', 0)
        if actual_above == expected_above:
            matches += 1
            logger.info(f'Spacing above matches: {actual_above} == {expected_above}')
        else:
            logger.info(f'Spacing above mismatch: {actual_above} != {expected_above}')
    if 'below' in expected:
        total_checks += 1
        expected_below = expected['below']
        actual_below = result.get('below', 0)
        if actual_below == expected_below:
            matches += 1
            logger.info(f'Spacing below matches: {actual_below} == {expected_below}')
        else:
            logger.info(f'Spacing below mismatch: {actual_below} != {expected_below}')
    if total_checks == 0:
        logger.warning('No spacing values to check')
        return 0.0
    score = matches / total_checks
    logger.info(f'Paragraph spacing check score: {matches}/{total_checks} = {score}')
    return score

