def check_docx_highlight__d90cc05f(result, expected, **options):
    """
    Check if specific words are highlighted in the document.

    Args:
        result: File bytes from vm_file getter
        expected: Dict with 'rules' containing:
            - target_words: List of words to check for highlighting
            - case_insensitive: Whether search is case-insensitive
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        target_words = expected.get('target_words', [])
        case_insensitive = expected.get('case_insensitive', True)
        doc = Document(io.BytesIO(result))
        total_occurrences = 0
        highlighted_occurrences = 0
        for para in doc.paragraphs:
            for run in para.runs:
                text = run.text
                search_text = text.lower() if case_insensitive else text
                for target_word in target_words:
                    search_target = target_word.lower() if case_insensitive else target_word
                    if search_target in search_text:
                        count = search_text.count(search_target)
                        total_occurrences += count
                        if run.font.highlight_color is not None:
                            highlighted_occurrences += count
        for table in doc.tables:
            for row in table.rows:
                for cell in row.cells:
                    for para in cell.paragraphs:
                        for run in para.runs:
                            text = run.text
                            search_text = text.lower() if case_insensitive else text
                            for target_word in target_words:
                                search_target = target_word.lower() if case_insensitive else target_word
                                if search_target in search_text:
                                    count = search_text.count(search_target)
                                    total_occurrences += count
                                    if run.font.highlight_color is not None:
                                        highlighted_occurrences += count
        if total_occurrences == 0:
            return 0.0
        ratio = highlighted_occurrences / total_occurrences
        if ratio >= 0.7:
            return 1.0
        else:
            return ratio / 0.7
    except Exception as e:
        print(f'Error in check_docx_highlight__d90cc05f: {e}')
        return 0.0

def check_min_font_size__03b68be0b364e7ac1421db0dce73b670(font_size_info, expected):
    """
    Check if the minimum font size is as expected.

    Args:
        font_size_info: Dictionary containing minimum_font_size value
        expected: Expected rules dict with type and value/range specifications

    Returns:
        float: 1.0 if matches, 0.0 otherwise
    """
    minimum_font_size = font_size_info.get('minimum_font_size', 0)
    if expected['type'] == 'value':
        return 1.0 if minimum_font_size == expected['value'] else 0.0
    elif expected['type'] == 'range':
        return 1.0 if expected['min'] <= minimum_font_size <= expected['max'] else 0.0
    else:
        logger.error(f"Unknown type: {expected['type']}")
        return 0.0

def check_heading_font__86ec10fff549da3f2e44c228becf4684(config_file_path, rules):
    """Check the Heading 1 font settings in LibreOffice Writer configuration.

    This function checks the Heading 1 paragraph style configuration in registrymodifications.xcu.

    IMPORTANT: When a user configures the Heading 1 style in LibreOffice Writer (via Format > Styles
    or Tools > Options), the configuration is stored in registrymodifications.xcu. The exact XML
    paths can vary, but typically include:

    1. PRIMARY: Paragraph style family modifications - When modifying Heading 1 via Format > Styles,
       LibreOffice stores the configuration under paths containing "StylePool" or "ParagraphStyles",
       with the style name encoded in the path (e.g., "Heading%201" or "Heading 1").

    2. SECONDARY: Default heading font settings - The path /org.openoffice.Office.Writer/DefaultFont
       with properties 'Heading' and 'HeadingHeight' controls application-level defaults for ALL
       heading styles. While this affects Heading 1, it's less specific than direct style overrides.

    3. TERTIARY: Character formatting properties - Individual font properties may be stored as
       CharFontName, CharHeight, CharWeight, etc. under the Heading 1 style definition.

    This implementation searches all three locations to ensure comprehensive coverage, prioritizing
    more specific Heading 1 configurations over generic defaults.

    Args:
        config_file_path: Path to registrymodifications.xcu file
        rules: Dictionary with font_name (str), font_size_pt (int), and font_weight (str) keys

    Returns:
        float: Score 0.0-1.0 with partial credit (0.33 for font, 0.33 for size, 0.34 for weight)
    """
    expected_font = rules['font_name']
    expected_size = rules['font_size_pt']
    expected_weight = rules.get('font_weight', 'Bold')
    if not config_file_path:
        return 0.0
    score = 0.0
    found_font = None
    found_size = None
    found_weight = None
    found_location = None
    try:
        tree = ET.parse(config_file_path)
        root = tree.getroot()
        namespace = {'oor': 'http://openoffice.org/2001/registry'}
        for elem in root.findall('.//item', namespace):
            path_attr = elem.get('{http://openoffice.org/2001/registry}path', '')
            heading1_indicators = ['Heading 1', 'Heading%201', 'Heading.20.1', 'Heading_1', 'Heading1']
            is_heading1_path = any((indicator in path_attr for indicator in heading1_indicators))
            is_style_path = any((keyword in path_attr for keyword in ['Style', 'ParagraphStyle', 'StylePool', 'StyleFamilies']))
            if is_heading1_path and is_style_path:
                for prop in elem.findall('.//prop', namespace):
                    prop_name = prop.get('{http://openoffice.org/2001/registry}name', '')
                    if prop_name in ['CharFontName', 'FontName']:
                        for value in prop.findall('value', namespace):
                            if value.text and (not found_font):
                                found_font = value.text.replace(' Bold', '').replace(' Italic', '').replace(' Regular', '').strip()
                                found_location = f'Heading 1 Style Path: {path_attr}'
                                if 'Bold' in value.text or 'bold' in value.text:
                                    found_weight = 'Bold'
                    elif prop_name in ['CharHeight', 'FontHeight', 'CharHeightAsian', 'CharHeightComplex']:
                        for value in prop.findall('value', namespace):
                            if value.text and (not found_size):
                                found_size = int(float(value.text))
                    elif prop_name in ['CharWeight', 'CharWeightAsian', 'CharWeightComplex']:
                        for value in prop.findall('value', namespace):
                            if value.text and (not found_weight):
                                weight_value = float(value.text)
                                if weight_value >= 150:
                                    found_weight = 'Bold'
        if not found_font or not found_size or (not found_weight):
            for elem in root.findall('.//item[@oor:path="/org.openoffice.Office.Writer/DefaultFont"]', namespace):
                if not found_font:
                    for prop in elem.findall('.//prop[@oor:name="Heading"]', namespace):
                        for value in prop.findall('value', namespace):
                            if value.text:
                                found_font = value.text.replace(' Bold', '').replace(' Italic', '').replace(' Regular', '').strip()
                                if not found_location:
                                    found_location = 'DefaultFont/Heading (applies to all headings)'
                                if not found_weight and ('Bold' in value.text or 'bold' in value.text):
                                    found_weight = 'Bold'
                if not found_size:
                    for prop in elem.findall('.//prop[@oor:name="HeadingHeight"]', namespace):
                        for value in prop.findall('value', namespace):
                            if value.text:
                                found_size = int(value.text)
        if not found_font or not found_size or (not found_weight):
            for elem in root.findall('.//item', namespace):
                path_attr = elem.get('{http://openoffice.org/2001/registry}path', '')
                if 'Heading' in path_attr or 'heading' in path_attr:
                    for prop in elem.findall('.//prop', namespace):
                        prop_name = prop.get('{http://openoffice.org/2001/registry}name', '')
                        if not found_font and any((name in prop_name for name in ['CharFontName', 'FontName', 'Font'])):
                            for value in prop.findall('value', namespace):
                                if value.text:
                                    found_font = value.text.replace(' Bold', '').replace(' Italic', '').replace(' Regular', '').strip()
                                    if not found_location:
                                        found_location = f'Generic Heading Path: {path_attr}'
                                    if not found_weight and ('Bold' in value.text or 'bold' in value.text):
                                        found_weight = 'Bold'
                        if not found_size and any((name in prop_name for name in ['CharHeight', 'FontHeight', 'Height'])):
                            for value in prop.findall('value', namespace):
                                if value.text:
                                    found_size = int(float(value.text))
                        if not found_weight and 'Weight' in prop_name:
                            for value in prop.findall('value', namespace):
                                if value.text:
                                    weight_value = float(value.text)
                                    if weight_value >= 150:
                                        found_weight = 'Bold'
        if found_location:
            logger.info(f'Heading 1 configuration found at: {found_location}')
        else:
            logger.warning('No Heading 1 configuration found in registrymodifications.xcu')
        if found_font and found_font == expected_font:
            score += 0.33
            logger.info(f'Font match: {found_font} == {expected_font}')
        else:
            logger.info(f'Font mismatch: {found_font} != {expected_font}')
        if found_size and found_size == expected_size:
            score += 0.33
            logger.info(f'Size match: {found_size} == {expected_size}')
        else:
            logger.info(f'Size mismatch: {found_size} != {expected_size}')
        if found_weight and found_weight == expected_weight:
            score += 0.34
            logger.info(f'Weight match: {found_weight} == {expected_weight}')
        else:
            logger.info(f'Weight mismatch: {found_weight} != {expected_weight}')
        logger.info(f'Final score: {score} (Font: {found_font}, Size: {found_size}, Weight: {found_weight})')
    except Exception as e:
        logger.error(f'Error parsing config file: {e}')
        return 0.0
    return score

def check_italic_applied__3b03efdc409765dfc8747c41555b4710(result: List[bool], expected: Dict[str, Any], **options) -> float:
    """Check if italic formatting was applied to specified paragraphs.

    Args:
        result: List of boolean values indicating italic status
        expected: Dict with 'num_italic' key indicating how many should be italic
        **options: Additional options

    Returns:
        float: Score from 0.0 to 1.0 based on how many paragraphs are italic
    """
    num_italic_expected = expected.get('num_italic', 5)
    if not result:
        return 0.0
    num_italic_actual = sum((1 for is_italic in result if is_italic))
    if num_italic_actual >= num_italic_expected:
        return 1.0
    else:
        return num_italic_actual / num_italic_expected if num_italic_expected > 0 else 0.0

