def check_italic_status__b3517b42(result: List[bool], expected: Dict[str, Any], **options) -> float:
    """Check if italic status matches expected values.

    Args:
        result: List of italic status booleans from getter
        expected: Dict with 'italic_status' key containing list of expected booleans
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    expected_status = expected.get('italic_status', [])
    if len(result) != len(expected_status):
        return 0.0
    score = 0.0
