def check_alignment_last_paragraph__b49e1f16(result, expected, **options):
    """Check if the last paragraph has specified alignment.

    Args:
        result: Path to the docx file
        expected: Dictionary with 'rules' containing 'alignment' (e.g., 'center', 'right', 'justify')
        **options: Additional options

    Returns:
        float: 1.0 if last paragraph has target alignment, 0.0 otherwise
    """
    if not result:
        return 0.0
    try:
        document = Document(result)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    if len(document.paragraphs) == 0:
        return 0.0
    last_paragraph = document.paragraphs[-1]
    if not last_paragraph.text.strip():
        return 0.0
    target_alignment_str = expected.get('alignment', 'center') if isinstance(expected, dict) else 'center'
    alignment_map = {'center': WD_ALIGN_PARAGRAPH.CENTER, 'right': WD_ALIGN_PARAGRAPH.RIGHT, 'left': WD_ALIGN_PARAGRAPH.LEFT, 'justify': WD_ALIGN_PARAGRAPH.JUSTIFY}
    target_alignment = alignment_map.get(target_alignment_str.lower(), WD_ALIGN_PARAGRAPH.CENTER)
    if last_paragraph.alignment == target_alignment:
        return 1.0
    return 0.0

