def check_reference_count__96398c95(result: dict, expected: dict, **options) -> float:
    """Check if reference count matches expected value and if the expected reference text is present.

    Args:
        result: Dict with 'count', 'last_reference', 'all_references' from the document
        expected: Dict with 'count' and 'text' fields
        **options: Additional options

    Returns:
        float: 1.0 if count matches and text is found, 0.0 otherwise
    """
    expected_count = expected.get('count', 0)
    expected_text = expected.get('text', '')
    result_count = result.get('count', 0)
    if result_count != expected_count:
        return 0.0
    if not expected_text:
        return 1.0
    last_reference = result.get('last_reference', '')

    def normalize_text(text):
        return ' '.join(text.split()).lower()
    normalized_expected = normalize_text(expected_text)
    normalized_last = normalize_text(last_reference)
    similarity = SequenceMatcher(None, normalized_expected, normalized_last).ratio()
    is_substring = normalized_expected in normalized_last
    if similarity > 0.85 or is_substring:
        return 1.0
    return 0.0

def check_words_with_e_italic__d89e455c(file_path1, file_path2, **kwargs):
    """
    Check if all words containing the letter 'e' are italicized.

    Args:
        file_path1: Path to result file
        file_path2: Path to expected file (unused)
        **kwargs: Additional options

    Returns:
        float: 1.0 if all words with 'e' are italicized, 0.0 otherwise
    """
    if not file_path1:
        return 0.0
    try:
        document = Document(file_path1)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    for table in document.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    for run in paragraph.runs:
                        word = run.text.strip()
                        if word:
                            has_e = 'e' in word.lower() or 'E' in word
                            if has_e:
                                if not run.font.italic:
                                    logger.info(f"Word with 'e': '{word}' is not italicized")
                                    return 0.0
                            elif run.font.italic:
                                logger.info(f"Word without 'e': '{word}' should not be italicized")
                                return 0.0
    return 1.0

def check_docx_contains_letters__49cf2765(result: str, expected: dict, **options) -> float:
    """
    Check if the answer text contains all the expected letters.

    Args:
        result: Concatenated answer string
        expected: Dict with 'rules' containing 'required_letters' key
        **options: Additional options (e.g., ignore_case)

    Returns:
        Score based on how many required letter groups are present
    """
    required_letters = expected.get('required_letters', [])
    ignore_case = options.get('ignore_case', True)
    actual = result.strip()
    if ignore_case:
        actual = actual.lower()
    score = 0.0
    count = 0
    for letter_group in required_letters:
        check_val = letter_group.lower() if ignore_case else letter_group
        if check_val in actual:
            count += 1
    if required_letters:
        score = count / len(required_letters)
    return score

