def check_docx_fontname__c9559f3a(result_file, expected, **options):
    """Check if all text in docx file has specified font name.

    Args:
        result_file: Path to the result docx file
        expected: Expected value dict with rules containing 'font_name'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result_file:
        return 0.0
    try:
        doc = Document(result_file)
        target_font = expected.get('font_name', 'Arial')
        total_runs_with_text = 0
        correct_font_runs = 0
        for para in doc.paragraphs:
            for run in para.runs:
                if run.text.strip():
                    total_runs_with_text += 1
                    if run.font.name:
                        if run.font.name.lower() == target_font.lower():
                            correct_font_runs += 1
        if total_runs_with_text == 0:
            return 0.0
        percentage = correct_font_runs / total_runs_with_text
        if percentage >= 0.95:
            return 1.0
        else:
            return percentage
    except Exception as e:
        print(f'Error checking font name: {e}')
        return 0.0

def check_docx_text_formatting__8fc2460fb618385c7c2a941f2d3b720d(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if text content matches expected responses and formatting is correct.
    
    Args:
        result: Dictionary from getter with paragraphs data
        expected: Expected rules (num_responses, target_word, etc.)
        **options: Additional options
        
    Returns:
        Score between 0.0 and 1.0
    """
    paragraphs = result.get('paragraphs', [])
    expected_num_responses = expected.get('num_responses', 6)
    target_word = expected.get('target_word', 'epic')
    non_empty_paragraphs = [p for p in paragraphs if p.get('text', '').strip()]
    if len(non_empty_paragraphs) != expected_num_responses:
        return 0.0
    para_indices = []
    for (i, p) in enumerate(paragraphs):
        if p.get('text', '').strip():
            para_indices.append(i)
    if len(para_indices) > 1:
        for i in range(len(para_indices) - 1):
            current_idx = para_indices[i]
            next_idx = para_indices[i + 1]
            if next_idx - current_idx < 2:
                return 0.0
    score = 0.0
    total_target_words = 0
    correctly_formatted = 0
    for para in non_empty_paragraphs:
        runs = para.get('runs', [])
        for run_info in runs:
            run_text = run_info.get('text', '')
            if target_word in run_text:
                total_target_words += run_text.count(target_word)
                target_count_in_run = run_text.count(target_word)
                highlight = run_info.get('highlight', None)
                if highlight is not None and 'YELLOW' in str(highlight).upper():
                    correctly_formatted += target_count_in_run
    expected_target_word_count = expected.get('target_word_count', 7)
    if total_target_words != expected_target_word_count:
        return 0.0
    if total_target_words == 0:
        return 0.0
    score = correctly_formatted / total_target_words if total_target_words > 0 else 0.0
    return score

def check_paragraph_formatting__947f2120(result, expected, **options):
    """
    Compare paragraph bold/italic formatting in a docx file against expected values.

    Args:
        result: Path to the result docx file
        expected: Dictionary with paragraph_formatting mapping
                 Each entry: paragraph_index -> {"bold": bool, "italic": bool}
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not expected:
        return 0.0
    paragraph_formatting = expected.get('paragraph_formatting', {})
    if not paragraph_formatting:
        return 0.0
    try:
        doc = Document(result)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    score = 0.0
    total_checks = len(paragraph_formatting)
    for (para_idx_str, format_rules) in paragraph_formatting.items():
        para_idx = int(para_idx_str)
        if para_idx >= len(doc.paragraphs):
            continue
        para = doc.paragraphs[para_idx]
        if not para.runs or not any((run.text.strip() for run in para.runs)):
            continue
        expected_bold = format_rules.get('bold', False)
        expected_italic = format_rules.get('italic', False)
        matching_runs = 0
        total_text_runs = 0
        for run in para.runs:
            if run.text.strip():
                total_text_runs += 1
                actual_bold = run.font.bold if run.font.bold is not None else False
                actual_italic = run.font.italic if run.font.italic is not None else False
                if actual_bold == expected_bold and actual_italic == expected_italic:
                    matching_runs += 1
        if total_text_runs > 0 and matching_runs / total_text_runs >= 0.8:
            score += 1.0 / total_checks
    return score

