def check_font_name__9f8c1afd5c9682b0f7d0cb3d082452fd(docx_file, expected, **options):
    """Check if all text in the document has the expected font name.

    Args:
        docx_file: BytesIO or path to the .docx file
        expected: Dict with 'font_name' key (e.g., 'Arial', 'Calibri')
        **options: Additional options

    Returns:
        float: 1.0 if all text has the expected font, 0.0 otherwise
    """
    if not docx_file:
        logger.error('No docx file provided')
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    expected_font = expected.get('font_name')
    if expected_font is None:
        logger.error('No font_name specified in expected')
        return 0.0
    for paragraph in doc.paragraphs:
        for run in paragraph.runs:
            if run.text.strip():
                font_name = run.font.name
