def check_concatenated_with_headers__618fd61c(result_state: str, expected_state: Dict[str, Any], **options) -> float:
    """
    Check if the concatenated file has the correct structure with chapter headers.

    This metric verifies:
    1. The file exists and has substantial content
    2. The file contains chapter headers (=== Chapter N ===)
    3. The file has the expected number of chapters
    4. The file has sufficient content (indicating all chapters were concatenated)

    Args:
        result_state: Path to the concatenated file
        expected_state: Dict containing rules:
            - chapter_count: Expected number of chapters (int)
            - has_headers: Whether headers should be present (bool)
        **options: Additional options

    Returns:
        float: Score (1.0 if all checks pass, 0.0 otherwise)
    """
    if result_state is None:
        logger.warning('Result file path is None')
        return 0.0
    if not os.path.exists(result_state):
        logger.warning(f'Result file does not exist: {result_state}')
        return 0.0
    try:
        with open(result_state, 'r', encoding='utf-8') as f:
            content = f.read()
    except Exception as e:
        logger.error(f'Error reading file {result_state}: {e}')
        return 0.0
    if len(content) < 1000:
        logger.info(f'File content too short: {len(content)} chars (expected >1000)')
        return 0.0
    chapter_count = expected_state.get('chapter_count', 5)
    has_headers = expected_state.get('has_headers', True)
    if has_headers:
        header_patterns = ['===\\s*Chapter\\s+\\d+\\s*===', '---\\s*Chapter\\s+\\d+\\s*---', 'Chapter\\s+\\d+']
        found_headers = False
        header_count = 0
        for pattern in header_patterns:
            matches = re.findall(pattern, content, re.IGNORECASE)
            if matches:
                found_headers = True
                header_count = len(matches)
                logger.info(f'Found {header_count} headers matching pattern: {pattern}')
                break
        if not found_headers:
            logger.info('No chapter headers found in file')
            return 0.0
        if header_count < chapter_count:
            logger.info(f'Found {header_count} chapter headers, expected {chapter_count}')
            return 0.0
    lines = content.splitlines()
    line_count = len(lines)
    if line_count < 2000:
        logger.info(f'File has {line_count} lines, expected >=2000')
        return 0.0
    logger.info(f'File passed all checks: {len(content)} chars, {line_count} lines, headers present')
    return 1.0

