def check_docx_references_italic__1da1f6bf(result, expected, **options):
    """
    Check if all reference paragraphs are formatted in italic.

    Args:
        result: Path to the DOCX file
        expected: Dict with keys:
            - references_start_para: int - first reference paragraph index
            - expected_reference_count: int - expected number of reference entries
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        doc = Document(result)
        start_para = expected.get('references_start_para', 20)
        expected_count = expected.get('expected_reference_count', 13)
        italic_count = 0
        total_count = 0
        for i in range(start_para, len(doc.paragraphs)):
            para = doc.paragraphs[i]
            if not para.text.strip():
                continue
            total_count += 1
            total_text_length = 0
            italic_text_length = 0
            for run in para.runs:
                run_text = run.text
                run_length = len(run_text)
                total_text_length += run_length
                if run.italic:
                    italic_text_length += run_length
            if total_text_length > 0 and italic_text_length / total_text_length >= 0.95:
                italic_count += 1
        if total_count != expected_count:
            print(f'Warning: Found {total_count} reference entries, expected {expected_count}')
            return 0.0
        if italic_count == expected_count:
            return 1.0
        else:
            print(f'Only {italic_count}/{expected_count} entries are italic. Task requires ALL entries to be italic.')
            return 0.0
    except Exception as e:
        print(f'Error checking italic formatting: {e}')
        return 0.0

