def check_docx_font_color__1df7be4ccd1b1ba68ca616ee1ecc65bd(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if font color matches expected value.

    Args:
        result: Dict from getter with 'has_color' and 'color' keys
        expected: Dict with 'has_color' and 'color' expected values
        **options: Additional options (tolerance for color comparison)

    Returns:
        1.0 if color matches expected (within tolerance), 0.0 otherwise
    """
    result_has_color = result.get('has_color', False)
    expected_has_color = expected.get('has_color', False)
    result_color = result.get('color')
    expected_color = expected.get('color')
    tolerance = options.get('color_tolerance', 10)
    logger.info(f'Color check - Result: {result_color}, Expected: {expected_color}')
    if not expected_has_color and (not result_has_color):
        return 1.0
    if expected_has_color != result_has_color:
        return 0.0
    if result_color is None or expected_color is None:
        return 0.0
    if not isinstance(result_color, (tuple, list)):
        return 0.0
    if not isinstance(expected_color, (tuple, list)):
        return 0.0
    if len(result_color) != 3 or len(expected_color) != 3:
        return 0.0
    for (r_val, e_val) in zip(result_color, expected_color):
        if abs(r_val - e_val) > tolerance:
            return 0.0
    return 1.0

