    try:
        subtitle_font_size = '0'
        for line in config_file.split('\n'):
            if line.startswith('#') or not line.strip():
                continue
            if 'freetype-rel-fontsize=' in line:
                subtitle_font_size = line.split('=')[-1].strip()
                break
        if subtitle_font_size == expected_size:
            return 1.0
        else:
            logger.warning(f'Subtitle font size mismatch - Expected: {expected_size}, Found: {subtitle_font_size}')
            return 0.0
    except FileNotFoundError:
        logger.error('VLC configuration file not found.')
        return 0.0
    except Exception as e:
        logger.error(f'An error occurred: {e}')
        return 0.0

