def check_docx_title_font_size__255872bc(result, expected, **options):
    """
    Check if the title has a specific font size.

    Args:
        result: Path to the docx file
        expected: Expected rules dict with 'paragraph_index' and 'font_size' keys
        **options: Additional options

    Returns:
        float: 1.0 if font size matches, 0.0 otherwise
    """
    if not result:
        return 0.0
    try:
        doc = Document(result)
        paragraph_index = expected.get('paragraph_index', 0)
        expected_font_size = expected.get('font_size', 14)
        if len(doc.paragraphs) <= paragraph_index:
            return 0.0
        paragraph = doc.paragraphs[paragraph_index]
        total_chars = 0
        matching_chars = 0
        for run in paragraph.runs:
            if run.text.strip():
                chars = len(run.text)
                total_chars += chars
                if run.font.size:
                    font_size_pt = run.font.size.pt
                    if abs(font_size_pt - expected_font_size) < 0.5:
                        matching_chars += chars
        if total_chars > 0 and matching_chars / total_chars >= 0.8:
            return 1.0
        else:
            return 0.0
    except Exception as e:
        logger.error(f'Error checking document: {e}')
        return 0.0

