def check_docx_min_locations__530b9f04(result_file_path, expected, **options):
    """
    Check if document contains minimum number of post office location entries in Chinese.
    Verifies:
    - Chinese language content
    - Post office facility type (邮局/邮政)
    - Location specificity (Futian District, Shenzhen)
    - Minimum length for valid addresses

    Args:
        result_file_path: Path to the result DOCX file
        expected: Dict with 'min_count' - minimum required locations
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result_file_path is None:
        return 0.0
    min_count = expected.get('min_count', 3)
    try:
        doc = Document(result_file_path)
        valid_locations = []
        for para in doc.paragraphs:
            text = para.text.strip()
            if not text or len(text) <= 15:
                continue
            if not re.search('[\\u4e00-\\u9fff]', text):
                continue
            if not ('邮局' in text or '邮政' in text):
                continue
            has_location = '福田' in text or '深圳' in text
            if not has_location:
                continue
            has_address_structure = bool(re.search('[区區路街道巷弄号號]', text))
            if not has_address_structure:
                continue
            valid_locations.append(text)
        actual_count = len(valid_locations)
        if actual_count >= min_count:
            return 1.0
        elif actual_count > 0:
            return actual_count / min_count
        else:
            return 0.0
    except Exception as e:
        print(f'Error reading document: {e}')
        return 0.0

def check_docx_line_count__e2e4b1c2(result, expected, **options):
    """Check if document modifications are correct.

    Verifies:
    1. No empty lines exist in the document
    2. Total line count is correct (101 = 100 records + 1 count line)
    3. Last line contains the count (e.g., 'Total: 100' or just '100')
    4. Record count is correct (100 train records)

    Args:
        result: Dict from getter with document info
        expected: Expected values from rules

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if not isinstance(result, dict):
        logger.error(f'Result is not a dict: {type(result)}')
        return 0.0
    expected_total = expected.get('total_line_count', 101)
    expected_records = expected.get('record_count', 100)
    if result.get('has_empty_lines', True):
        logger.error('Document still has empty lines')
        return 0.0
    actual_total = result.get('total_line_count', 0)
    if actual_total != expected_total:
        logger.error(f'Total line count mismatch. Expected: {expected_total}, Got: {actual_total}')
        return 0.0
    last_line = result.get('last_line_text', '')
    numbers = re.findall('\\d+', last_line)
    if not numbers:
        logger.error(f"Last line does not contain a number. Got: '{last_line}'")
        return 0.0
    count_in_last_line = int(numbers[-1])
    if count_in_last_line != expected_records:
        logger.error(f'Count in last line is incorrect. Expected: {expected_records}, Got: {count_in_last_line}')
        return 0.0
    actual_records = result.get('record_count', 0)
    if actual_records != expected_records:
        logger.error(f'Record count mismatch. Expected: {expected_records}, Got: {actual_records}')
        return 0.0
    logger.info(f"All checks passed: {actual_total} total lines, {actual_records} records, no empty lines, last line: '{last_line}'")
    return 1.0

def check_docx_center_alignment__70118bff2da8288404e2b55eea6cd381(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if document content matches expected text and is center-aligned.

    Args:
        result: Dict with 'content' and 'is_centered' from getter
        expected: Dict with 'expected_content' and 'should_be_centered'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    expected_content = expected.get('expected_content', '')
    should_be_centered = expected.get('should_be_centered', True)
    result_content = result.get('content', '')
    result_is_centered = result.get('is_centered', False)
    if result_content and expected_content:
        result_normalized = ' '.join(result_content.split())
        expected_normalized = ' '.join(expected_content.split())
        if result_normalized == expected_normalized:
            score += 0.5
        else:
            from rapidfuzz import fuzz
            similarity = fuzz.ratio(result_normalized, expected_normalized) / 100.0
            if similarity >= 0.9:
                score += 0.5
    if result_is_centered == should_be_centered:
        score += 0.5
    return score

def check_docx_answer_format__49c1a752b7d51fd6cb3587f963d5d516(result: Dict[str, str], expected: Dict[str, Any], **options) -> float:
    """
    Check if the answer file contains the expected formatted answers.

    Args:
        result: Dict mapping test names to answer strings (from getter)
        expected: Dict with 'answers' key containing expected test answers
        **options: Additional options (e.g., 'ignore_case', 'ignore_spaces')

    Returns:
        Score between 0.0 and 1.0
    """
    expected_answers = expected.get('answers', {})
    ignore_case = options.get('ignore_case', False)
    ignore_spaces = options.get('ignore_spaces', False)
    if not expected_answers:
        logger.warning('No expected answers provided')
        return 0.0
    total_tests = len(expected_answers)
    if total_tests == 0:
        return 0.0
    correct_count = 0
    for (test_name, expected_answer) in expected_answers.items():
        if test_name not in result:
            logger.info(f"Test '{test_name}' not found in result")
            continue
        result_answer = result[test_name]
        if ignore_case:
            result_answer = result_answer.lower()
            expected_answer = expected_answer.lower()
        if ignore_spaces:
            result_answer = result_answer.replace(' ', '')
            expected_answer = expected_answer.replace(' ', '')
        if result_answer == expected_answer:
            correct_count += 1
        else:
            logger.info(f"Answer mismatch for '{test_name}': got '{result_answer}', expected '{expected_answer}'")
    score = correct_count / total_tests
    return score

