def check_bold_7020c4cc7233def09c964c3dfbf5a134(pptx_path, rules):
    """
    Check if the specified paragraphs in the presentation have bold formatting.

    Args:
        pptx_path: Path to the PPTX file
        rules: Dict with keys:
            - slide_index_s: List of slide indices (0-indexed)
            - shape_index_s: List of shape indices
            - paragraph_index_s: List of paragraph indices

    Returns:
        1 if all specified paragraphs are bold, 0 otherwise
    """
    try:
        presentation = Presentation(pptx_path)
        slide_index_s = rules['slide_index_s']
        shape_index_s = rules['shape_index_s']
        paragraph_index_s = rules['paragraph_index_s']
        for slide_index in slide_index_s:
            slide = presentation.slides[slide_index]
            for shape_index in shape_index_s:
                paragraphs = slide.shapes[shape_index].text_frame.paragraphs
                for paragraph_index in paragraph_index_s:
                    paragraph = paragraphs[paragraph_index]
                    if not paragraph.runs:
                        return 0
                    for run in paragraph.runs:
                        if not run.font.bold:
                            return 0
        return 1
    except Exception as e:
        logger.error(f'Error checking bold: {e}')
        return 0

