def check_paragraph_fonts__cdc24961(result, expected, **options):
    """
    Compare paragraph font families in a docx file against expected values.

    Args:
        result: Path to the result docx file
        expected: Dictionary with paragraph_fonts mapping (0-indexed paragraph -> font name)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not expected:
        return 0.0
    paragraph_fonts = expected.get('paragraph_fonts', {})
    if not paragraph_fonts:
        return 0.0
    try:
        doc = Document(result)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    score = 0.0
    total_checks = len(paragraph_fonts)
    for (para_idx_str, expected_font) in paragraph_fonts.items():
        para_idx = int(para_idx_str)
        if para_idx >= len(doc.paragraphs):
            continue
        para = doc.paragraphs[para_idx]
        if not para.runs or not any((run.text.strip() for run in para.runs)):
            continue
        matching_runs = 0
        total_text_runs = 0
        for run in para.runs:
            if run.text.strip():
                total_text_runs += 1
                actual_font = run.font.name
                if actual_font and actual_font.lower() == expected_font.lower():
                    matching_runs += 1
        if total_text_runs > 0 and matching_runs / total_text_runs >= 0.8:
            score += 1.0 / total_checks
    return score

