def check_docx_para7_titlecase__54bf0fa2(result, expected, **options):
    """Check if text is in title case."""
    if not result:
        return 0.0
    expected_start = expected.get('starts_with', 'Prepare A Presentation')
    if not result.startswith(expected_start):
        return 0.0
    words = result.split()
    for (i, word) in enumerate(words):
        if not word:
            continue
        alpha_chars = [c for c in word if c.isalpha()]
        if not alpha_chars:
            continue
        small_words = {'a', 'an', 'the', 'and', 'or', 'but', 'for', 'nor', 'on', 'at', 'to', 'by', 'in', 'of'}
        first_alpha_idx = next((j for (j, c) in enumerate(word) if c.isalpha()), None)
        if first_alpha_idx is None:
            continue
        first_letter = word[first_alpha_idx]
        word_lower = word.lower()
        is_small_word = i > 0 and word_lower in small_words
        if is_small_word:
            pass
        else:
            if not first_letter.isupper():
                return 0.0
            for (j, c) in enumerate(word):
                if j > first_alpha_idx and c.isalpha() and c.isupper():
                    return 0.0
    return 1.0

