def check_odt_color__a0593874(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if the text color matches the expected color.

    Args:
        result: Dict from getter with 'color' key
        expected: Expected state with 'target_color' key (e.g., {'target_color': 'blue'})
        **options: Additional options

    Returns:
        float: 1.0 if color matches expected, 0.0 otherwise
    """
    try:
        color = result.get('color')
        if color is None:
            return 0.0
        target_color = expected.get('target_color', 'blue').lower()
        color = color.lower().strip()
        if color.startswith('#'):
            color = color[1:]
        color_mappings = {'blue': {'hex_values': ['0000ff', '0000cc', '0066ff', '0033ff', '0000ee', '0000dd'], 'rgb_check': lambda r, g, b: b > 200 and r < 100 and (g < 100)}, 'red': {'hex_values': ['ff0000', 'cc0000', 'ee0000', 'dd0000', 'ff0033', 'ff0066'], 'rgb_check': lambda r, g, b: r > 200 and g < 100 and (b < 100)}, 'green': {'hex_values': ['00ff00', '00cc00', '00ee00', '00dd00', '33ff00', '66ff00'], 'rgb_check': lambda r, g, b: g > 200 and r < 100 and (b < 100)}, 'yellow': {'hex_values': ['ffff00', 'ffee00', 'ffcc00', 'eeee00'], 'rgb_check': lambda r, g, b: r > 200 and g > 200 and (b < 100)}, 'orange': {'hex_values': ['ff6600', 'ff8800', 'ff9900', 'ff7700'], 'rgb_check': lambda r, g, b: r > 200 and 100 < g < 180 and (b < 100)}, 'purple': {'hex_values': ['800080', '9900cc', 'aa00ff', '8800aa'], 'rgb_check': lambda r, g, b: r > 100 and g < 100 and (b > 100)}, 'black': {'hex_values': ['000000', '111111', '222222'], 'rgb_check': lambda r, g, b: r < 50 and g < 50 and (b < 50)}}
        color_map = color_mappings.get(target_color)
        if not color_map:
            logger.warning(f'Unknown target color: {target_color}, defaulting to exact match')
            return 1.0 if color == target_color else 0.0
        if color in color_map['hex_values']:
            return 1.0
        if len(color) == 6:
            try:
                r = int(color[0:2], 16)
                g = int(color[2:4], 16)
                b = int(color[4:6], 16)
                if color_map['rgb_check'](r, g, b):
                    return 1.0
            except ValueError:
                pass
        return 0.0
    except Exception as e:
        logger.error(f'Error in check_odt_color: {e}')
        return 0.0

def check_writer_table_headers__cb84d8e55491bfd63123932189f4803b(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if Writer document table has expected headers, row count, and actual data content.

    Args:
        result: Dict from getter with table data and content metrics
        expected: Dict with expected headers and row count
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if 'error' in result:
        return 0.0
    score = 0.0
    if 'expected_headers' in expected:
        expected_headers = expected['expected_headers']
        actual_headers = result.get('headers', [])
        if len(actual_headers) >= len(expected_headers):
            headers_match = True
            for (i, exp_header) in enumerate(expected_headers):
                if i >= len(actual_headers) or str(actual_headers[i]) != str(exp_header):
                    headers_match = False
                    break
            if headers_match:
                score += 0.3
    if 'expected_data_rows' in expected:
        expected_rows = expected['expected_data_rows']
        actual_rows = len(result.get('data_rows', []))
        if actual_rows == expected_rows:
            score += 0.3
    content_density = result.get('content_density', 0.0)
    non_empty_cells = result.get('non_empty_data_cells', 0)
    if content_density >= 0.3 and non_empty_cells > 0:
        score += 0.4
    elif content_density >= 0.15 and non_empty_cells > 0:
        score += 0.2
    return score

def check_docx_font_size__bb7c00a491c6ff21c93d4fdd14e8e8b6(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if font size matches expected value.

    Args:
        result: Dict from getter with 'font_size' key
        expected: Dict with 'font_size' expected value
        **options: Additional options (tolerance for size comparison)

    Returns:
        1.0 if font size matches expected (within tolerance), 0.0 otherwise
    """
    result_size = result.get('font_size')
