def check_docx_para_spacing__6241af56(result: Dict[str, Any], expected: Any, **options) -> float:
    """Check if paragraph spacing matches expected values.

    Args:
        result: Spacing info from getter
        expected: Expected spacing values (from rules dict)
        **options: Additional options

    Returns:
        float: Score based on matching spacing attributes
    """
    tolerance = options.get('tolerance', 1.0)
    score = 0.0
    checks = 0
    if 'before' in expected:
        checks += 1
        if abs(result['before'] - expected['before']) <= tolerance:
            score += 1.0
    if 'after' in expected:
        checks += 1
        if abs(result['after'] - expected['after']) <= tolerance:
            score += 1.0
    if 'line_spacing' in expected:
        checks += 1
        if abs(result['line_spacing'] - expected['line_spacing']) <= 0.1:
            score += 1.0
    return score / checks if checks > 0 else 0.0

def check_docx_contains_text__97c6df2d(result, expected, **options):
    """Check if the document text contains the expected string.

    Args:
        result: Text content from the document
        expected: Expected text (either a string or dict with 'text' key from rules)
        **options: Additional options

    Returns:
        float: 1.0 if expected text is found, 0.0 otherwise
    """
    expected_text = expected.get('text') if isinstance(expected, dict) else expected
    if not isinstance(result, str) or not isinstance(expected_text, str):
        return 0.0
    result_normalized = ' '.join(result.lower().split())
    expected_normalized = ' '.join(expected_text.lower().split())
    if expected_normalized in result_normalized:
        return 1.0
    return 0.0

def check_odt_background__a0593874(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if the background color matches the target color from expected parameter.

    Args:
        result: Dict from getter with 'background_color' key
        expected: Expected state with 'target_color' in rules
        **options: Additional options

    Returns:
        float: 1.0 if background matches target color, 0.0 otherwise
    """
    try:
        bg_color = result.get('background_color')
        if bg_color is None:
            return 0.0
        target_color = expected.get('target_color', 'gray').lower()
        bg_color = bg_color.lower().strip()
        if bg_color.startswith('#'):
            bg_color = bg_color[1:]
        color_maps = {'gray': ['c0c0c0', '808080', 'a9a9a9', 'd3d3d3', 'cccccc', '999999']}
        acceptable_colors = color_maps.get(target_color, [])
        if bg_color in acceptable_colors:
            return 1.0
        if target_color == 'gray' and len(bg_color) == 6:
            try:
                r = int(bg_color[0:2], 16)
                g = int(bg_color[2:4], 16)
                b = int(bg_color[4:6], 16)
                max_diff = max(abs(r - g), abs(g - b), abs(r - b))
                if max_diff <= 20:
                    return 1.0
            except ValueError:
                pass
        return 0.0
    except Exception as e:
        logger.error(f'Error in check_odt_background: {e}')
        return 0.0

def check_heading_font_size__8b3632b0245c572f5ae071f9ed7aadad(docx_file, expected, **options):
    """Check if the first line (heading) has the specified font size.

    Args:
        docx_file: Path to the DOCX file
        expected: Dictionary with 'font_size_pt' key specifying the expected font size in points
        **options: Additional options

    Returns:
        float: 1.0 if heading has the correct font size, 0.0 otherwise
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    if not doc.paragraphs:
        logger.error('Document has no paragraphs')
        return 0.0
    expected_font_size = expected.get('font_size_pt', 16)
    first_paragraph = doc.paragraphs[0]
    for run in first_paragraph.runs:
        if run.text.strip():
            font_size = run.font.size
            if font_size is None:
                logger.info(f'Font size is None')
                return 0.0
            font_size_pt = font_size.pt
            if font_size_pt != expected_font_size:
                logger.info(f'Font size mismatch: expected {expected_font_size}pt, got {font_size_pt}pt')
                return 0.0
    return 1.0

def check_docx_line_spacing__80b1dde5ed18c8f57e1f28b547b8b0a4(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if all paragraphs have the expected line spacing.

    Args:
        result: Dict from getter with line_spacings field (list of floats)
        expected: Dict with expected_spacing field (float value like 2.0 for double spacing)
        **options: Optional parameters (tolerance for float comparison)

    Returns:
        1.0 if all paragraphs have expected spacing, 0.0 otherwise
    """
    if not result or not result.get('line_spacings'):
        logger.warning('Result is empty or line_spacings is empty')
        return 0.0
    line_spacings = result.get('line_spacings')
    expected_spacing = expected.get('expected_spacing')
    if expected_spacing is None:
        logger.warning('Expected spacing is None')
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    for (i, spacing) in enumerate(line_spacings):
        if abs(spacing - expected_spacing) > tolerance:
            logger.info(f'Line spacing mismatch at paragraph {i}: expected {expected_spacing}, got {spacing}')
            return 0.0
    return 1.0

def check_double_letter_words_highlight__97140137(file_path1, file_path2, **kwargs):
    """
    Check if words with double letters have background highlighting.

    Args:
        file_path1: Path to result file
        file_path2: Path to expected file (unused)
        **kwargs: Additional options

    Returns:
        float: 1.0 if all double-letter words are highlighted, 0.0 otherwise
    """
    if not file_path1:
        return 0.0
    try:
        document = Document(file_path1)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0

    def has_double_letters(word):
        """Check if word has consecutive duplicate letters"""
        for i in range(len(word) - 1):
            if word[i].lower() == word[i + 1].lower():
                return True
        return False
    for table in document.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    for run in paragraph.runs:
                        word = run.text.strip()
                        if word:
                            has_doubles = has_double_letters(word)
                            if has_doubles:
                                if not run.font.highlight_color:
                                    logger.info(f"Word with double letters '{word}' is not highlighted")
                                    return 0.0
                            elif run.font.highlight_color:
                                logger.info(f"Word without double letters '{word}' should not be highlighted")
                                return 0.0
    return 1.0

