def check_paragraph_contains__34cbc845(result, expected, **options):
    """Check if paragraph contains expected text.

    Args:
        result: Paragraph text from getter
        expected: Dictionary with 'contains' key (text that should be in paragraph)
        **options: Additional options (similarity_threshold, etc.)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        logger.error('No paragraph text found')
        return 0.0
    contains_text = expected.get('contains', '')
    if not contains_text:
        logger.error("No 'contains' text specified in expected")
        return 0.0
    threshold = options.get('similarity_threshold', 85)
    similarity = fuzz.partial_ratio(contains_text.lower(), result.lower())
    if similarity >= threshold:
        logger.info(f'✓ Paragraph contains expected text (similarity: {similarity}%)')
        return 1.0
    else:
        logger.warning(f'✗ Paragraph does not contain expected text (similarity: {similarity}%)')
        return max(0.0, (similarity - 50) / 50)

