def check_italic_d6fbd356becfc5cd8eb05626590e36eb(pptx_path, rules):
    """
    Check if the specified paragraphs in the presentation have italic formatting.

    Args:
        pptx_path: Path to the PPTX file
        rules: Dict with keys:
            - slide_index_s: List of slide indices (0-indexed)
            - shape_index_s: List of shape indices
            - paragraph_index_s: List of paragraph indices

    Returns:
        1 if all specified paragraphs are italic, 0 otherwise
    """
    try:
        presentation = Presentation(pptx_path)
        slide_index_s = rules['slide_index_s']
        shape_index_s = rules['shape_index_s']
        paragraph_index_s = rules['paragraph_index_s']
        expected_content = ['Important Dates', 'Important Resources & Links']
        for slide_index in slide_index_s:
            if slide_index >= len(presentation.slides):
                logger.error(f'Slide index {slide_index} out of range')
                return 0
            slide = presentation.slides[slide_index]
            for shape_index in shape_index_s:
                if shape_index >= len(slide.shapes):
                    logger.error(f'Shape index {shape_index} out of range')
                    return 0
                shape = slide.shapes[shape_index]
                if not hasattr(shape, 'text_frame'):
                    logger.error(f'Shape at index {shape_index} has no text_frame')
                    return 0
                paragraphs = shape.text_frame.paragraphs
                for (i, paragraph_index) in enumerate(paragraph_index_s):
                    if paragraph_index >= len(paragraphs):
                        logger.error(f'Paragraph index {paragraph_index} out of range')
                        return 0
                    paragraph = paragraphs[paragraph_index]
                    paragraph_text = paragraph.text.strip()
                    if i < len(expected_content):
                        if expected_content[i] not in paragraph_text:
                            logger.error(f"Paragraph at index {paragraph_index} does not contain expected content '{expected_content[i]}'. Found: '{paragraph_text}'")
                            return 0
                    if not paragraph.runs:
                        logger.error(f'Paragraph at index {paragraph_index} has no runs')
                        return 0
                    for run in paragraph.runs:
                        if not run.font.italic:
                            logger.error(f"Paragraph at index {paragraph_index} has non-italic run: '{run.text}'")
                            return 0
        return 1
    except Exception as e:
        logger.error(f'Error checking italic: {e}')
        return 0

def check_docx_line_spacing__49cd0011(result, expected, **options):
    """
    Check if paragraphs have the expected line spacing.
    
    Args:
        result: Path to the DOCX file
        expected: Dict with keys:
            - main_body_start: int - first paragraph to check
            - main_body_end: int - last paragraph to check
            - line_spacing_multiple: float - expected line spacing (e.g., 1.5)
        **options: Additional options
        
    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        doc = Document(result)
        start_idx = expected.get('main_body_start', 4)
        end_idx = expected.get('main_body_end', 16)
        expected_spacing = expected.get('line_spacing_multiple', 1.5)
        correct_count = 0
        total_count = 0
        for i in range(start_idx, min(end_idx + 1, len(doc.paragraphs))):
            para = doc.paragraphs[i]
            if not para.text.strip():
                continue
            total_count += 1
            if para.paragraph_format.line_spacing is not None:
                spacing = para.paragraph_format.line_spacing
                if isinstance(spacing, (int, float)):
                    if abs(spacing - expected_spacing) < 0.1:
                        correct_count += 1
                elif hasattr(spacing, 'pt'):
                    font_size = 12.0
                    if para.runs and len(para.runs) > 0:
                        run = para.runs[0]
                        if run.font.size is not None:
                            font_size = run.font.size.pt
                    expected_pt = font_size * expected_spacing
                    actual_pt = spacing.pt
                    tolerance = expected_pt * 0.1
                    if abs(actual_pt - expected_pt) <= tolerance:
                        correct_count += 1
        if total_count == 0:
            return 0.0
        ratio = correct_count / total_count
        if ratio >= 0.9:
            return 1.0
        else:
            return ratio / 0.9
    except Exception as e:
        print(f'Error checking line spacing: {e}')
        return 0.0

