def check_spacing_para_task__11984674(docx_file, expected, **options):
    """Check line spacing for three paragraphs.

    This function verifies that each paragraph has the expected line spacing.
    Expected spacing values: para0=2.0, para1=2.0, para2=2.0

    Args:
        docx_file: Path to the docx file
        expected: Dict with para0, para1, para2 spacing values
        **options: Additional options (tolerance for floating point comparison)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    if len(doc.paragraphs) < 3:
        logger.error(f'Document has {len(doc.paragraphs)} paragraphs, expected at least 3')
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    expected_para0 = expected.get('para0', 2.0)
    expected_para1 = expected.get('para1', 2.0)
    expected_para2 = expected.get('para2', 2.0)
    spacing0 = doc.paragraphs[0].paragraph_format.line_spacing
    spacing1 = doc.paragraphs[1].paragraph_format.line_spacing
    spacing2 = doc.paragraphs[2].paragraph_format.line_spacing
    spacing0 = spacing0 if spacing0 is not None else 1.0
    spacing1 = spacing1 if spacing1 is not None else 1.0
    spacing2 = spacing2 if spacing2 is not None else 1.0
    logger.info(f'Paragraph 0 spacing: {spacing0} (expected: {expected_para0})')
    logger.info(f'Paragraph 1 spacing: {spacing1} (expected: {expected_para1})')
    logger.info(f'Paragraph 2 spacing: {spacing2} (expected: {expected_para2})')
    score = 0.0
    if abs(spacing0 - expected_para0) <= tolerance:
        score += 0.33
    if abs(spacing1 - expected_para1) <= tolerance:
        score += 0.34
    if abs(spacing2 - expected_para2) <= tolerance:
        score += 0.33
    return round(score, 2)

def check_docx_table_count__8c6fecde(result, expected, **options):
    """Check if the docx has the expected table and content.

    Args:
        result: Dict with 'table_count', 'first_table_info', 'table_content', 'document_text' from getter
        expected: Dict with 'min_tables' requirement
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        logger.error('Result is None')
        return 0.0
    min_tables = expected.get('min_tables', 1)
    actual_count = result.get('table_count', 0)
    if actual_count < min_tables:
        logger.info(f'✗ Document has {actual_count} tables (required: >= {min_tables})')
        return 0.0
    logger.info(f'✓ Document has {actual_count} tables (required: >= {min_tables})')
    table_info = result.get('first_table_info')
    if not table_info:
        logger.error('✗ No table info available')
        return 0.0
    row_count = table_info.get('row_count', 0)
    col_count = table_info.get('col_count', 0)
    if row_count != 2 or col_count != 2:
        logger.info(f'✗ Table dimensions are {row_count}x{col_count} (required: 2x2)')
        return 0.0
    logger.info(f'✓ Table dimensions are 2x2')
    document_text = result.get('document_text', [])
    if not document_text or len(document_text) == 0:
        logger.info('✗ Document has no text/heading')
        return 0.0
    logger.info(f"✓ Document contains text/heading: '{document_text[0][:50]}...'")
    table_content = result.get('table_content', [])
    if not table_content:
        logger.error('✗ No table content available')
        return 0.0
    non_empty_cells = 0
    all_cell_text = []
    for row in table_content:
        for cell in row:
            if cell:
                non_empty_cells += 1
                all_cell_text.append(cell.lower())
    if non_empty_cells == 0:
        logger.info('✗ Table is completely empty')
        return 0.0
    logger.info(f'✓ Table has {non_empty_cells} non-empty cells')
    react_keywords = ['react', 'component', 'declarative', 'virtual', 'dom', 'jsx', 'library', 'framework', 'ui', 'interface', 'feature', 'benefit']
    has_react_content = any((keyword in ' '.join(all_cell_text) for keyword in react_keywords))
    if has_react_content:
        logger.info('✓ Table contains React-related content')
    else:
        logger.info('⚠ Table does not contain obvious React-related keywords (but has content)')
    logger.info('✓ All requirements satisfied')
    return 1.0

