def check_conditional_highlighting__d96c11b6(result, expected, **options):
    """Check if cells are highlighted based on a value threshold.

    Args:
        result: List of highlighted cell addresses
        expected: Expected configuration with threshold (from rules dict)
        **options: Additional options

    Returns:
        float: Score based on correct highlighting
    """
    if not isinstance(result, list):
        return 0.0
    expected_cells = expected.get('cells', [])
    if len(expected_cells) == 0:
        return 0.0
    result_set = set(result)
    expected_set = set(expected_cells)
    if len(result_set) == 0:
        return 0.0
    correct = len(result_set & expected_set)
    precision = correct / len(result_set) if len(result_set) > 0 else 0.0
    recall = correct / len(expected_set) if len(expected_set) > 0 else 0.0
    if precision + recall > 0:
        f1 = 2 * (precision * recall) / (precision + recall)
        return f1
    return 0.0

