def check_page_zoom__1c67d2f9(result, expected, **options):
    """Check if page zoom level matches expected value or range.

    Args:
        result: Dict with default_zoom_level from getter
        expected: Expected value or rules dict
        **options: Additional options

    Returns:
        float: 1.0 if match, 0.0 otherwise
    """
    zoom_level = result.get('default_zoom_level', 0.0)
    if expected['type'] == 'value':
        tolerance = options.get('tolerance', 0.01)
        return 1.0 if abs(zoom_level - expected['value']) < tolerance else 0.0
    elif expected['type'] == 'range':
        min_val = expected.get('min', -999999)
        max_val = expected.get('max', 999999)
