def check_paragraph_count_minimum__069e5f51(result: Optional[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """Check if paragraph count meets minimum requirement and content is relevant.

    Args:
        result: Dict with 'paragraph_count', 'word_count', and 'full_text' from getter
        expected: Rules dict with 'min_paragraphs' key
        **options: Additional options

    Returns:
        1.0 if all checks pass, partial score for partial matches, 0.0 otherwise
    """
    if result is None:
        return 0.0
    paragraph_count = result.get('paragraph_count', 0)
    word_count = result.get('word_count', 0)
    full_text = result.get('full_text', '').lower()
    min_paragraphs = expected.get('min_paragraphs', 0)
    if paragraph_count < min_paragraphs:
        return 0.0
    if word_count < 100:
        return 0.0
    apple_keywords = ['apple', 'design', 'guideline', 'human interface', 'hig']
    color_keywords = ['color', 'colour', 'palette', 'rgb', 'hex', 'contrast', 'accessibility']
    apple_keyword_count = sum((1 for keyword in apple_keywords if keyword in full_text))
    color_keyword_count = sum((1 for keyword in color_keywords if keyword in full_text))
    if apple_keyword_count == 0:
        return 0.0
    if color_keyword_count < 2:
        return 0.0
    apple_score = min(apple_keyword_count / 2.0, 1.0)
    color_score = min(color_keyword_count / 3.0, 1.0)
    combined_score = apple_score * 0.5 + color_score * 0.5
    if apple_keyword_count >= 2 and color_keyword_count >= 3:
        return 1.0
    elif combined_score >= 0.7:
        return combined_score
    else:
        return 0.0

def check_docx_highlighted_word__aa90982a(result_file, expected, **options):
    """
    Check if a Word document contains specific text with highlighted words.

    Args:
        result_file: Path to the result .docx file
        expected: Dictionary with 'texts' (list of expected texts) and 'highlighted_word'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result_file or not result_file.endswith('.docx'):
        return 0.0
    try:
        doc = Document(result_file)
    except Exception as e:
        print(f'Error reading document: {e}')
        return 0.0
    expected_texts = expected.get('texts', [])
    highlighted_word = expected.get('highlighted_word', '')
    if not expected_texts or not highlighted_word:
        return 0.0
    all_paragraphs = [p.text for p in doc.paragraphs if p.text.strip()]
    doc_text = '\n'.join(all_paragraphs)
    doc_text_normalized = re.sub('\\s+', ' ', doc_text).strip()
    content_score = 0.0
    texts_found = sum((1 for text in expected_texts if re.sub('\\s+', ' ', text).strip() in doc_text_normalized))
    if texts_found == len(expected_texts):
        content_score = 0.5
    elif texts_found > 0:
        content_score = 0.5 * (texts_found / len(expected_texts))
    non_empty_paragraphs = len(all_paragraphs)
    expected_paragraph_count = len(expected_texts)
    if non_empty_paragraphs < expected_paragraph_count:
        content_score *= non_empty_paragraphs / expected_paragraph_count
    highlight_score = 0.0
    highlighted_count = 0
    word_pattern = '\\b' + re.escape(highlighted_word) + '\\b'
    total_word_count = len(re.findall(word_pattern, doc_text, re.IGNORECASE))
    if total_word_count > 0:
        for paragraph in doc.paragraphs:
            for run in paragraph.runs:
                if run.font.highlight_color is not None:
                    run_text = run.text
                    word_matches = re.findall(word_pattern, run_text, re.IGNORECASE)
                    run_word_count = len(run_text.split())
                    if run_word_count <= 3:
                        highlighted_count += len(word_matches)
                    elif run_word_count <= 10:
                        highlighted_count += len(word_matches) * 0.5
                    else:
                        highlighted_count += len(word_matches) * 0.2
        if highlighted_count >= total_word_count:
            highlight_score = 0.5
        elif highlighted_count > 0:
            highlight_score = 0.5 * (highlighted_count / total_word_count)
    return content_score + highlight_score

def find_default_font__246b24fb(config_file_path, rules):
    """Find the default font in LibreOffice Writer (variation 6: Calibri)."""
    default_font = None
    expected_font = rules['font_name']
    if not config_file_path:
        return 0
    try:
        tree = ET.parse(config_file_path)
        root = tree.getroot()
        namespace = {'oor': 'http://openoffice.org/2001/registry'}
        for elem in root.findall('.//item[@oor:path="/org.openoffice.Office.Writer/DefaultFont"]', namespace):
            for prop in elem.findall('.//prop[@oor:name="Standard"]', namespace):
                for value in prop.findall('value', namespace):
                    default_font = value.text
    except Exception as e:
        logger.error(f'Error: {e}')
    return 1 if default_font == expected_font else 0

def check_docx_section_headings__7c979ab3(result, expected, **options):
    """
    Check if document contains required section headings in correct order and positions.

    Args:
        result: Path to the DOCX file
        expected: Dict with keys:
            - required_headings: list - headings that should be present (partial match)
            - should_be_bold: bool - whether headings should be bold
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        doc = Document(result)
        required_headings = expected.get('required_headings', [])
        should_be_bold = expected.get('should_be_bold', True)
        if not required_headings:
            return 0.0
        body_paragraphs = []
        for (i, para) in enumerate(doc.paragraphs):
            text = para.text.strip()
            if text and len(text) > 30:
                body_paragraphs.append(i)
        if len(body_paragraphs) < len(required_headings):
            found_headings = set()
            for para in doc.paragraphs:
                text = para.text.strip().lower()
                for heading in required_headings:
                    if heading.lower() in text:
                        if should_be_bold:
                            is_bold = any((run.bold for run in para.runs))
                            if is_bold:
                                found_headings.add(heading.lower())
                        else:
                            found_headings.add(heading.lower())
            return len(found_headings) / len(required_headings)
        found_headings_data = []
        for (i, para) in enumerate(doc.paragraphs):
            text = para.text.strip()
            if not text:
                continue
            text_lower = text.lower()
            for heading in required_headings:
                if heading.lower() in text_lower:
                    is_bold = any((run.bold for run in para.runs)) if para.runs else False
                    if should_be_bold and (not is_bold):
                        continue
                    if len(text) < 100:
                        found_headings_data.append({'heading': heading.lower(), 'position': i, 'text': text})
                        break
        found_heading_names = [h['heading'] for h in found_headings_data]
        required_heading_names_lower = [h.lower() for h in required_headings]
        ordered_matches = []
        required_idx = 0
        for found_heading in found_heading_names:
            if required_idx < len(required_heading_names_lower):
                if found_heading == required_heading_names_lower[required_idx]:
                    ordered_matches.append(found_heading)
                    required_idx += 1
        order_score = len(ordered_matches) / len(required_headings)
        position_correct = True
        for heading_data in found_headings_data:
            heading_pos = heading_data['position']
            has_body_after = any((bp > heading_pos for bp in body_paragraphs))
            if not has_body_after and heading_data['heading'] != required_heading_names_lower[-1]:
                position_correct = False
        if position_correct:
            score = order_score
        else:
            score = order_score * 0.8
        return score
    except Exception as e:
        print(f'Error checking section headings: {e}')
        return 0.0

def check_page_number_color_green__3a0c5049(pptx_file, rules):
    """Check if slide numbers are colored green.

    Args:
        pptx_file: Path to the PPTX file
        rules: Dictionary with 'color' key (expected: 'green')

    Returns:
        1.0 if slide numbers are green, 0.0 otherwise
    """
    color = rules['color']

    def is_green(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[1:3], 16), int(rgb_str[3:5], 16), int(rgb_str[5:7], 16))
        return g > r + threshold and g > b + threshold
    with zipfile.ZipFile(pptx_file, 'r') as zip_ref:
        slide_master_name = 'ppt/slideMasters/slideMaster1.xml'
        with zip_ref.open(slide_master_name) as slide_master_file:
            tree = ET.parse(slide_master_file)
            root = tree.getroot()
            namespaces = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main', 'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}
            color_elems = root.findall('.//a:solidFill//a:srgbClr', namespaces)
            for color_elem in color_elems:
                rgb_val = color_elem.get('val')
                if rgb_val and is_green(rgb_val):
                    return 1.0
    return 0.0

