def check_text_highlighting__1f6188764666903805a2bbde08d45ff2(result, expected, **options):
    """Check if the target text has highlighting applied with correct color.

    Args:
        result: Data from getter containing highlighting information
        expected: Expected values (should_be_highlighted, expected_color optional)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result.get('found', False):
        return 0.0
    should_be_highlighted = expected.get('should_be_highlighted', False)
    is_highlighted = result.get('is_highlighted', False)
