def check_title_font_size__edf9799e(pptx_path, expected):
    """
    Check if the title shape has the expected font size.

    Args:
        pptx_path: Path to the PPTX file
        expected: Dict containing 'slide_idx', 'shape_idx', and 'font_size' (in points)

    Returns:
        float: 1.0 if font size matches, 0.0 otherwise
    """
    try:
        presentation = Presentation(pptx_path)
        slide_idx = expected.get('slide_idx', 0)
        shape_idx = expected.get('shape_idx', 1)
        expected_size = expected.get('font_size', 44)
        if slide_idx >= len(presentation.slides):
            return 0.0
        slide = presentation.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            return 0.0
        shape = slide.shapes[shape_idx]
        if not hasattr(shape, 'text_frame'):
            return 0.0
        if len(shape.text_frame.paragraphs) == 0:
            return 0.0
        first_para = shape.text_frame.paragraphs[0]
        if len(first_para.runs) == 0:
            return 0.0
        first_run = first_para.runs[0]
        actual_size = first_run.font.size
        if actual_size is None:
            return 0.0
        actual_size_pt = actual_size.pt
        if abs(actual_size_pt - expected_size) < 0.5:
            return 1.0
        return 0.0
    except Exception as e:
        return 0.0

