def check_docx_min_locations__34ff100e(result_file_path, expected, **options):
    """
    Check if document contains minimum number of park location entries from Futian District in Chinese.

    Args:
        result_file_path: Path to the result DOCX file
        expected: Dict with 'min_count' - minimum required locations
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result_file_path is None:
        return 0.0
    min_count = expected.get('min_count', 4)
    try:
        doc = Document(result_file_path)
        valid_locations = []
        for para in doc.paragraphs:
            text = para.text.strip()
            if not text or len(text) < 5:
                continue
            if not contains_chinese(text):
                continue
            if '公园' not in text:
                continue
            if '福田' not in text:
                continue
            if not looks_like_address(text):
                continue
            valid_locations.append(text)
        actual_count = len(valid_locations)
        if actual_count >= min_count:
            return 1.0
        elif actual_count > 0:
            return actual_count / min_count
        else:
            return 0.0
    except Exception as e:
        print(f'Error reading document: {e}')
        return 0.0

def check_docx_para_alignment__4be41503419a99400a0f45ab431d0b6c(result, expected, **options):
    """Check if specific paragraphs have expected alignment.

    Args:
        result: Dict mapping paragraph index to alignment value from getter
        expected: Dict with 'alignments' key containing expected {para_idx: alignment} mapping
        **options: Additional options (not used)

    Returns:
        float: Score between 0.0 and 1.0 (1.0 = all alignments match)
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        logger.error(f'Invalid input types: result={type(result)}, expected={type(expected)}')
        return 0.0
    expected_alignments = expected.get('alignments', {})
    if not expected_alignments:
        logger.error('No expected alignments provided')
