def check_pdf_pages__1426ffbf(pdf_file: str, rules: Dict[str, Any]) -> float:
    """
    Check if PDF has the expected number of pages and optionally verify content.

    Args:
        pdf_file: Path to the PDF file
        rules: Dict with 'relation', 'ref_value', and optional 'verify_content' flag

    Returns:
        float: 1.0 if conditions met, 0.0 otherwise
    """
    if pdf_file is None:
        return 0.0
    if not os.path.exists(pdf_file):
        return 0.0
    reader = PdfReader(pdf_file)
    nb_pages: int = len(reader.pages)
    page_count_matches = getattr(operator, rules['relation'])(nb_pages, rules['ref_value'])
    if not page_count_matches:
        return 0.0
    if rules.get('verify_content', False):
        file_size = os.path.getsize(pdf_file)
        if file_size < 10240:
            return 0.0
        has_images = False
        for page in reader.pages:
            if '/XObject' in page['/Resources']:
                xobjects = page['/Resources']['/XObject'].get_object()
                for obj in xobjects:
                    if xobjects[obj]['/Subtype'] == '/Image':
                        has_images = True
                        break
            if has_images:
                break
        if not has_images:
            return 0.0
    return 1.0

def check_italic_color_blue__bd7f5184(result_file, expected):
    """Check that all italic text has blue-ish color with fuzzy matching.

    Args:
        result_file: Path to the result .docx file
        expected: Expected configuration (unused, blue is implicit)

    Returns:
        float: Proportion of italic runs that are blue (0.0-1.0)
    """
    if not result_file:
        return 0.0
    try:
        doc = Document(result_file)
    except Exception as e:
        logger.error(f'Error opening document: {e}')
        return 0.0
    italic_count = 0
    blue_italic_count = 0
    for paragraph in doc.paragraphs:
        for run in paragraph.runs:
            if run.italic:
                italic_count += 1
                if run.font.color and run.font.color.rgb:
                    rgb = run.font.color.rgb
                    (r, g, b) = (rgb[0], rgb[1], rgb[2])
                    if b > r and b > g and (b > 100):
                        blue_italic_count += 1
    if italic_count == 0:
        return 0.0
    return blue_italic_count / italic_count

