def check_page_number_colors__dba582db9f285ebba56893a94f5be30c(pptx_file_path, expected, **options):
    """
    Check if page number colors match the expected color.

    Args:
        pptx_file_path: Path to the PPTX file
        expected: Dictionary with 'color' key (e.g., 'red', 'blue', 'green', 'black')

    Returns:
        1.0 if colors match, 0.0 otherwise
    """
    color = expected.get('color', 'red')

    def is_red(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[0:2], 16), int(rgb_str[2:4], 16), int(rgb_str[4:6], 16))
        return r > g + threshold and r > b + threshold

    def is_blue(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[0:2], 16), int(rgb_str[2:4], 16), int(rgb_str[4:6], 16))
        return b > g + threshold and b > r + threshold

    def is_green(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[0:2], 16), int(rgb_str[2:4], 16), int(rgb_str[4:6], 16))
        return g > r + threshold and g > b + threshold

    def is_black(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[0:2], 16), int(rgb_str[2:4], 16), int(rgb_str[4:6], 16))
        return r < threshold and g < threshold and (b < threshold)
    try:
        with zipfile.ZipFile(pptx_file_path, 'r') as zip_ref:
            namespaces = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main', 'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}
            slide_masters = []
            for name in zip_ref.namelist():
                if name.startswith('ppt/slideMasters/slideMaster') and name.endswith('.xml'):
                    slide_masters.append(name)
            if not slide_masters:
                logger.error('No slide masters found in presentation')
                return 0.0
            page_number_color = None
            for slide_master_name in slide_masters:
                try:
                    with zip_ref.open(slide_master_name) as slide_master_file:
                        tree = ET.parse(slide_master_file)
                        root = tree.getroot()
                        page_num_shapes = root.findall('.//p:sp[.//p:nvSpPr//p:ph[@type="sldNum"]]', namespaces)
                        if not page_num_shapes:
                            page_num_shapes = root.findall('.//p:sp[.//p:nvSpPr//p:ph[@type="dt"]]', namespaces)
                        if not page_num_shapes:
                            continue
                        for shape in page_num_shapes:
                            color_elem = shape.find('.//p:txBody//a:r//a:rPr//a:solidFill//a:srgbClr', namespaces)
                            if color_elem is not None:
                                page_number_color = color_elem.get('val')
                                logger.info(f'Found page number color in text run properties: {page_number_color}')
                                break
                            color_elem = shape.find('.//p:txBody//a:p//a:pPr//a:defRPr//a:solidFill//a:srgbClr', namespaces)
                            if color_elem is not None:
                                page_number_color = color_elem.get('val')
                                logger.info(f'Found page number color in default run properties: {page_number_color}')
                                break
                            color_elem = shape.find('.//p:txBody//a:lstStyle//a:defRPr//a:solidFill//a:srgbClr', namespaces)
                            if color_elem is not None:
                                page_number_color = color_elem.get('val')
                                logger.info(f'Found page number color in list style: {page_number_color}')
                                break
                            color_elem = shape.find('.//p:style//a:fontRef//a:srgbClr', namespaces)
                            if color_elem is not None:
                                page_number_color = color_elem.get('val')
                                logger.info(f'Found page number color in shape style: {page_number_color}')
                                break
                        if page_number_color:
                            break
                except Exception as e:
                    logger.warning(f'Error parsing {slide_master_name}: {e}')
                    continue
            if page_number_color is None:
                logger.error('Could not find page number placeholder text color in any slide master')
                return 0.0
        if color == 'red' and (not is_red(page_number_color)):
            logger.info(f'Expected red color, but got: {page_number_color}')
            return 0.0
        elif color == 'blue' and (not is_blue(page_number_color)):
            logger.info(f'Expected blue color, but got: {page_number_color}')
            return 0.0
        elif color == 'green' and (not is_green(page_number_color)):
            logger.info(f'Expected green color, but got: {page_number_color}')
            return 0.0
        elif color == 'black' and (not is_black(page_number_color)):
            logger.info(f'Expected black color, but got: {page_number_color}')
            return 0.0
        logger.info(f'Page number color {page_number_color} matches expected color {color}')
        return 1.0
    except Exception as e:
        logger.error(f'Error checking page number colors: {e}')
        return 0.0

def check_right_aligned_header_numbers__1aac1e051260ed91efb8096c1e6898bd(docx_file, expected):
    """
    Check if the document has automatic page number fields in headers with right alignment.

    Args:
        docx_file: Path to the .docx file
        expected: Expected configuration (not used for this metric)

    Returns:
        float: 1.0 if right-aligned automatic page numbers exist in headers, 0.0 otherwise
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0

    def has_page_number_field(paragraph):
        """
        Check if a paragraph contains an automatic page number field.
        Looks for field codes (w:fldChar) in the paragraph's XML structure.
        """
        for run in paragraph.runs:
            run_element = run._element
            fld_chars = run_element.findall('.//{http://schemas.openxmlformats.org/wordprocessingml/2006/main}fldChar')
            if fld_chars:
                para_xml = paragraph._element.xml.decode('utf-8') if isinstance(paragraph._element.xml, bytes) else str(paragraph._element.xml)
                if 'PAGE' in para_xml or 'NUMPAGES' in para_xml:
                    return True
        para_element = paragraph._element
        instr_texts = para_element.findall('.//{http://schemas.openxmlformats.org/wordprocessingml/2006/main}instrText')
        for instr in instr_texts:
            if instr.text and ('PAGE' in instr.text or 'NUMPAGES' in instr.text):
                return True
        return False
    sections_with_headers = 0
    sections_with_valid_page_numbers = 0
    for section in doc.sections:
        header = section.header
        if header is None or not header.paragraphs:
            continue
        sections_with_headers += 1
        found_page_field = False
        is_right_aligned = False
        for para in header.paragraphs:
            if has_page_number_field(para):
                found_page_field = True
                if para.paragraph_format.alignment == WD_PARAGRAPH_ALIGNMENT.RIGHT:
                    is_right_aligned = True
                    break
        if found_page_field and is_right_aligned:
            sections_with_valid_page_numbers += 1
    if sections_with_headers == 0:
        return 0.0
    if sections_with_valid_page_numbers == sections_with_headers:
        return 1.0
    else:
        return float(sections_with_valid_page_numbers) / float(sections_with_headers)

def check_font_and_spacing__206bbcca(result: List[Tuple[str, float]], expected: Dict[str, Any], **options) -> float:
    """Check if font name and spacing match expected values.

    Args:
        result: List of (font_name, spacing) tuples from getter
        expected: Dict with 'font_spacing_pairs' key containing list of expected tuples
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    expected_pairs = expected.get('font_spacing_pairs', [])
    if not expected_pairs:
        return 0.0
    if not result:
        return 0.0
    min_len = min(len(result), len(expected_pairs))
    score = 0.0
    for i in range(min_len):
        (actual_font, actual_spacing) = result[i]
        (exp_font, exp_spacing) = expected_pairs[i]
        if actual_font == exp_font and abs(actual_spacing - exp_spacing) < 0.1:
            score += 1.0 / len(expected_pairs)
    if len(result) != len(expected_pairs):
        count_penalty = abs(len(result) - len(expected_pairs)) * 0.1
        score = max(0.0, score - count_penalty)
    return min(1.0, score)

