def check_low_marks_highlighted__9815dbed(result, expected, **options):
    """Check if students with marks below threshold are highlighted.

    Args:
        result: Path to the result Excel file
        expected: Dict with 'sheet', 'threshold', 'expected_rows'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        wb = openpyxl.load_workbook(result, data_only=True)
        sheet_idx = expected.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        threshold = expected.get('threshold', 20)
        expected_rows = expected.get('expected_rows', [])
        if not expected_rows:
            logger.error('No expected_rows provided')
            return 0.0
        highlighted_count = 0
        for row_idx in expected_rows:
            cell = ws[f'B{row_idx}']
            fill = cell.fill
            if fill and fill.start_color and fill.start_color.rgb:
                color = fill.start_color.rgb
                if isinstance(color, str) and len(color) == 8:
                    r_hex = color[2:4]
                    g_hex = color[4:6]
                    b_hex = color[6:8]
                    try:
                        r = int(r_hex, 16)
                        g = int(g_hex, 16)
                        b = int(b_hex, 16)
                        if r > 200 and g < 100 and (b < 100):
                            highlighted_count += 1
                    except ValueError:
                        logger.warning(f'Invalid color format at row {row_idx}: {color}')
                        continue
        score = highlighted_count / len(expected_rows) if expected_rows else 0.0
        logger.info(f'Low marks highlighting: {highlighted_count}/{len(expected_rows)} rows highlighted, score={score:.2f}')
        return score
    except Exception as e:
        logger.error(f'Error checking low marks highlighting: {e}')
        return 0.0

