def check_first_para_underline__1cf28d44(result_state, expected_state, **options):
    """
    Check if the first paragraph in a LibreOffice Writer document has underline formatting.

    This function verifies that all text runs in the first paragraph have underline formatting applied.
    The task requires underlining the heading text (first paragraph) in the document.

    Args:
        result_state: Path to the document file (str)
        expected_state: Expected rules dict containing 'first_paragraph_underlined': true
        **options: Additional options

    Returns:
        float: Score (1.0 if all runs in first paragraph are underlined, 0.0 otherwise)
    """
    if not result_state:
        logger.error('No file path provided in result_state')
        return 0.0
    try:
        doc = Document(result_state)
    except Exception as e:
        logger.error(f'Error opening document {result_state}: {e}')
        return 0.0
    if not doc.paragraphs:
        logger.error('Document has no paragraphs')
        return 0.0
    first_paragraph = doc.paragraphs[0]
    if not first_paragraph.text.strip():
        logger.warning('First paragraph is empty')
        return 0.0
    if not first_paragraph.runs:
        logger.warning('First paragraph has no runs')
        return 0.0
    all_underlined = True
    for (run_idx, run) in enumerate(first_paragraph.runs):
        if run.text.strip():
            if not run.font.underline:
                logger.info(f"Run {run_idx} (text: '{run.text}') is not underlined. underline={run.font.underline}")
                all_underlined = False
                break
            else:
                logger.debug(f"Run {run_idx} (text: '{run.text}') is underlined. underline={run.font.underline}")
    if all_underlined:
        logger.info('✅ All runs in first paragraph are underlined')
        return 1.0
    else:
        logger.info('❌ Not all runs in first paragraph are underlined')
        return 0.0

def check_writer_line_spacing__ded8af3e2f2cb08d572f4f0efb0f8c9d(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if the first paragraph has the expected line spacing.

    Args:
        result: Dict from getter with 'paragraph_spacings' list
        expected: Dict with 'spacing' value to check (1.5 means 1.5x line spacing)
        **options: Additional options (unused)

    Returns:
        float: 1.0 if first paragraph has expected spacing, 0.0 otherwise
    """
    try:
        paragraph_spacings = result.get('paragraph_spacings', [])
        expected_spacing = expected.get('spacing')
        if not paragraph_spacings:
            logger.warning('No paragraph spacings found in result')
            return 0.0
        if expected_spacing is None:
            logger.warning('No expected spacing specified')
            return 0.0
        first_para = paragraph_spacings[0]
        actual_spacing = first_para.get('spacing')
        tolerance = 0.01
        if actual_spacing is not None and abs(actual_spacing - expected_spacing) < tolerance:
            logger.info(f'Line spacing matches: {actual_spacing}')
            return 1.0
        else:
            logger.info(f'Line spacing mismatch: expected={expected_spacing}, got={actual_spacing}')
            return 0.0
    except Exception as e:
        logger.error(f'Error checking line spacing: {e}')
        return 0.0

def check_bold_italic_last_paragraph__c977b8be(result, expected, **options):
    """Check if all text in the last paragraph is both bold and italic.

    Args:
        result: Path to the modified DOCX file
        expected: Not used (relies on rule-based check)
        **options: Additional options

    Returns:
        float: 1.0 if all text in last paragraph is both bold and italic, 0.0 otherwise
    """
    if not result:
        return 0.0
    try:
        doc = Document(result)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    non_empty_paragraphs = [para for para in doc.paragraphs if para.text.strip()]
    if len(non_empty_paragraphs) == 0:
        return 0.0
    last_paragraph = non_empty_paragraphs[-1]
    for run in last_paragraph.runs:
        if run.text.strip():
            if not (run.font.bold and run.font.italic):
                return 0.0
    return 1.0

def check_docx_matches_earliest_paper__aba926f58e18a60bbf80c32b31c75828(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if the DOCX content contains the title of the earliest paper from the spreadsheet.

    This composite metric verifies both steps of the task:
    1. The agent correctly identified the earliest paper from the spreadsheet
    2. The agent created a DOCX file containing that paper's title

    Args:
        result: Dict with 'docx_content' and 'earliest_paper' keys
        expected: Dict (empty, as we dynamically determine the correct answer)
        **options: Additional options

    Returns:
        1.0 if the DOCX contains the earliest paper's title, 0.0 otherwise
    """
    if not result:
        return 0.0
    docx_content = result.get('docx_content', '')
    earliest_paper = result.get('earliest_paper', {})
    if not earliest_paper or 'title' not in earliest_paper:
        return 0.0
    if not docx_content:
        return 0.0
    earliest_title = earliest_paper['title']
    if earliest_title.lower() in docx_content.lower():
        return 1.0
    return 0.0

def check_min_mark_bold__4b06e5ed8197a71ac39c9ea9322f4951(result: Dict[str, Any], expected: dict, **options) -> float:
    """Check if the minimum mark cell is correctly identified and has bold formatting.

    This metric verifies both requirements:
    1. The cell with the minimum value is correctly identified (partial credit: 0.5)
    2. That cell has bold formatting applied (partial credit: 0.5)

    Args:
        result: Dict with min_value, min_cell, bold_cells, and correct_cell_bold
        expected: Dict with 'type' and 'rules' fields. Rules should contain expected behavior.

    Returns:
        float: Score between 0.0 and 1.0
        - 0.5 if minimum cell is identified but not bold
        - 1.0 if minimum cell is identified and is bold
        - 0.0 if minimum cell not found or no bold applied
    """
    rules = expected.get('rules', expected)
    min_cell = result.get('min_cell')
    if not min_cell:
        return 0.0
    bold_cells = result.get('bold_cells', [])
    if not bold_cells:
        return 0.5
    correct_cell_bold = result.get('correct_cell_bold', False)
    expected_correct_cell_bold = rules.get('correct_cell_bold', True)
    if correct_cell_bold == expected_correct_cell_bold:
        return 1.0
    else:
        return 0.25

def check_odt_italic_words__a0593874(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if ALL occurrences of the target word are in italic format.

    Args:
        result: Dict from getter with 'italic_words' and 'all_words' keys
        expected: Expected state dict containing 'target_word' in rules
        **options: Additional options

    Returns:
        float: 1.0 if all occurrences of target word are italic, 0.0 otherwise
    """
    try:
        target_word = expected.get('target_word', 'Person')
        italic_words = result.get('italic_words', [])
        all_words = result.get('all_words', [])
        total_count = all_words.count(target_word)
        italic_count = italic_words.count(target_word)
        if total_count == 0:
            logger.warning(f"No occurrences of '{target_word}' found in document")
            return 0.0
        if italic_count > 0 and italic_count == total_count:
            return 1.0
        else:
            logger.info(f"Found {italic_count}/{total_count} italic occurrences of '{target_word}'")
            return 0.0
    except Exception as e:
        logger.error(f'Error in check_odt_italic_words: {e}')
        return 0.0

