def check_docx_contains__e19b4814(result, expected, **options):
    """Check if the docx text contains the expected string.

    Args:
        result: Text content from docx file (string)
        expected: Expected text to find (string)
        **options: Additional options (case_sensitive, partial_match)

    Returns:
        float: 1.0 if text is found, 0.0 otherwise
    """
    if not isinstance(result, str) or not isinstance(expected, str):
        return 0.0
    case_sensitive = options.get('case_sensitive', False)
    if not case_sensitive:
        result = result.lower()
