def check_fixed_font_size__b7f59f23(result, expected, **options):
    """Check if default fixed font size matches expected value or range.

    Args:
        result: Dict with default_fixed_font_size from getter
        expected: Expected value or rules dict
        **options: Additional options

    Returns:
        float: 1.0 if match, 0.0 otherwise
    """
    fixed_font_size = result.get('default_fixed_font_size', 13)
    if expected['type'] == 'value':
        return 1.0 if fixed_font_size == expected['value'] else 0.0
    elif expected['type'] == 'range':
        min_val = expected.get('min', 0)
        max_val = expected.get('max', 999999)
        return 1.0 if min_val <= fixed_font_size <= max_val else 0.0
    else:
        raise TypeError(f"{expected['type']} not supported yet!")

