def check_italic_formatting__e7d4b812fa60e0a3abfa2828010b529f(result, expected, **options):
    """
    Check if the document has italic formatting as expected.
    For pattern matching, verifies that ALL occurrences of each pattern are italicized.

    Args:
        result: Dict from getter with italic text info
        expected: Dict with expected values (from rules)
        **options: Additional options

    Returns:
        float: 1.0 if italic formatting matches expectations, 0.0 otherwise
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    has_italic = result.get('has_italic', False)
    expected_has_italic = expected.get('has_italic', True)
    if has_italic != expected_has_italic:
        return 0.0
    min_count = expected.get('min_italic_count')
    if min_count is not None:
        actual_count = result.get('italic_count', 0)
        if actual_count < min_count:
            return 0.0
    required_patterns = expected.get('required_italic_patterns', [])
    if required_patterns:
        all_runs = result.get('all_runs', [])
        if not all_runs:
            return 0.0
        for pattern in required_patterns:
            total_occurrences = 0
            italic_occurrences = 0
            for run in all_runs:
                text = run.get('text', '')
                is_italic = run.get('italic', False)
                pattern_count = text.count(pattern)
                if pattern_count > 0:
                    total_occurrences += pattern_count
                    if is_italic:
                        italic_occurrences += pattern_count
            if total_occurrences > 0 and italic_occurrences < total_occurrences:
                return 0.0
            if total_occurrences == 0:
                return 0.0
    return 1.0

