def check_docx_content__a1471ab6(result, expected, **options):
    """Compare docx file content against expected text.
    
    Args:
        result: Path to the docx file
        expected: Dict with 'expected_text' key containing the text to find
        **options: Additional comparison options
        
    Returns:
        float: 1.0 if expected text is found, 0.0 otherwise
    """
    ignore_case = options.get('ignore_case', True)
    fuzzy_match = options.get('fuzzy_match', True)
    if not result:
        return 0.0
    try:
        doc = Document(result)
        doc_text = '\n'.join([p.text for p in doc.paragraphs])
        expected_text = expected.get('expected_text', '')
        if not expected_text:
            return 0.0
        if ignore_case:
            doc_text_normalized = doc_text.lower()
            expected_normalized = expected_text.lower()
        else:
            doc_text_normalized = doc_text
            expected_normalized = expected_text
        doc_text_normalized = re.sub('\\s+', ' ', doc_text_normalized).strip()
        expected_normalized = re.sub('\\s+', ' ', expected_normalized).strip()
        if expected_normalized in doc_text_normalized:
            return 1.0
        if fuzzy_match:
            doc_alphanum = re.sub('[^a-z0-9]', '', doc_text_normalized)
            expected_alphanum = re.sub('[^a-z0-9]', '', expected_normalized)
            if expected_alphanum in doc_alphanum:
                return 1.0
        return 0.0
    except Exception as e:
        print(f'Error checking docx content: {e}')
        return 0.0

def check_default_heading_font__2d2d0be6(config_file_path, rules):
    """Check the default heading font in LibreOffice Writer."""
    default_font = None
    expected_font = rules['font_name']
    if not config_file_path:
        return 0
    try:
        tree = ET.parse(config_file_path)
        root = tree.getroot()
        namespace = {'oor': 'http://openoffice.org/2001/registry'}
        for elem in root.findall('.//item[@oor:path="/org.openoffice.Office.Writer/DefaultFont"]', namespace):
            for prop in elem.findall('.//prop[@oor:name="Heading"]', namespace):
                for value in prop.findall('value', namespace):
                    default_font = value.text
    except Exception as e:
        logger.error(f'Error: {e}')
    return 1 if default_font == expected_font else 0

def check_docx_formatted_words__289698c9(result_file, expected, **options):
    """
    Check if words matching the filter have the correct formatting.

    Args:
        result_file: Path to the result .docx file
        expected: Expected value (not used, filter is in code)
        **options: Additional options

    Returns:
        float: 1.0 if all matching words have correct formatting, 0.0 otherwise
    """
    if not result_file:
        return 0.0
    try:
        doc = Document(result_file)
    except Exception:
        return 0.0

    def should_format(w):
        return w[-1].lower() == 'e'

    def is_green_color(rgb_tuple):
        """Check if color is green: green channel should be significantly higher than red and blue"""
        if not rgb_tuple or len(rgb_tuple) < 3:
            return False
        (r, g, b) = (rgb_tuple[0], rgb_tuple[1], rgb_tuple[2])
        return g >= 100 and g > r + 50 and (g > b + 50)

    def check_paragraph_runs(paragraph):
        """Check all runs in a paragraph for correct formatting"""
        for run in paragraph.runs:
            words = run.text.split()
            for word in words:
                word = word.strip()
                if not word:
                    continue
                if should_format(word):
                    if run.font.color and run.font.color.rgb:
                        actual_rgb = (run.font.color.rgb[0], run.font.color.rgb[1], run.font.color.rgb[2])
                        if not is_green_color(actual_rgb):
                            return False
                    else:
                        return False
                elif run.font.color and run.font.color.rgb:
                    actual_rgb = (run.font.color.rgb[0], run.font.color.rgb[1], run.font.color.rgb[2])
                    if is_green_color(actual_rgb):
                        return False
        return True
    for paragraph in doc.paragraphs:
        if not check_paragraph_runs(paragraph):
            return 0.0
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    if not check_paragraph_runs(paragraph):
                        return 0.0
    return 1.0

def check_row_highlight__8955ff18(result, expected, **options):
    """
    Check if specific cells have background fill color applied.

    Args:
        result: Path to the Excel file
        expected: Dict with keys:
            - sheet: Sheet index
            - row: Row number (1-indexed)
            - cells: List of cell addresses to check (e.g., ["A8", "B8", "C8"])
            - has_fill: Whether cells should have fill color
        **options: Additional options
            - strict_color_match: Whether to check for specific color (default: False)
            - color_tolerance: RGB tolerance for color matching (default: 25)

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        sheet_idx = expected.get('sheet', 0)
        cells = expected.get('cells', [])
        has_fill = expected.get('has_fill', True)
        strict_color = options.get('strict_color_match', False)
        tolerance = options.get('color_tolerance', 25)
        wb = openpyxl.load_workbook(result)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        score = 0.0
        if not cells:
            return 0.0
        cells_with_fill = 0
        for cell_addr in cells:
            cell = ws[cell_addr]
            has_color = False
            if cell.fill and cell.fill.start_color:
                color = cell.fill.start_color
                if hasattr(color, 'rgb') and color.rgb:
                    rgb = color.rgb
                    if rgb not in ['00000000', 'FFFFFFFF', None]:
                        if len(rgb) == 8:
                            r = int(rgb[2:4], 16)
                            g = int(rgb[4:6], 16)
                            b = int(rgb[6:8], 16)
                            if not strict_color:
                                if not (r > 240 and g > 240 and (b > 240)):
                                    has_color = True
                            elif r > 200 and g > 200 and (b < 100):
                                has_color = True
                logger.info(f"Cell {cell_addr} fill: {(rgb if hasattr(color, 'rgb') else 'none')}, has_color: {has_color}")
            if has_fill and has_color:
                cells_with_fill += 1
            elif not has_fill and (not has_color):
                cells_with_fill += 1
        if len(cells) > 0:
            score = cells_with_fill / len(cells)
        logger.info(f'Cells with correct fill: {cells_with_fill}/{len(cells)}, score: {score}')
        return min(score, 1.0)
    except Exception as e:
        logger.error(f'Error checking row highlight: {e}')
        return 0.0

