def check_table_count_and_paragraph__2cd34689(result, expected, **options):
    """Check if the document has the correct table count and the last paragraph states it correctly."""
    if not isinstance(result, dict):
        return 0.0
    actual_table_count = result.get('table_count', 0)
    last_para = result.get('last_paragraph', '')
    pattern = 'this\\s+document\\s+contains\\s+(\\d+)\\s+tables?'
    match = re.search(pattern, last_para.lower())
    if not match:
        logger.info(f'Pattern not found in last paragraph: {last_para}')
        return 0.0
    stated_count = int(match.group(1))
    if stated_count == actual_table_count:
        return 1.0
    else:
        logger.info(f'Table count mismatch: stated={stated_count}, actual={actual_table_count}')
        return 0.0

def check_font_color_last_paragraph__f2be9083(result, expected, **options):
    """Check if all text in the last paragraph has specified font color.

    Args:
        result: Path to the docx file
        expected: Dictionary with 'rules' containing 'r', 'g', 'b' color values
        **options: Additional options

    Returns:
        float: 1.0 if all text in last paragraph has the target color, 0.0 otherwise
    """
    if not result:
        return 0.0
    try:
        document = Document(result)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    if len(document.paragraphs) == 0:
        return 0.0
    last_paragraph = document.paragraphs[-1]
    if not last_paragraph.text.strip():
        return 0.0
    if isinstance(expected, dict):
        target_r = expected.get('r', 255)
        target_g = expected.get('g', 0)
        target_b = expected.get('b', 0)
    else:
        (target_r, target_g, target_b) = (255, 0, 0)
    if len(last_paragraph.runs) == 0:
        return 0.0
    for run in last_paragraph.runs:
        if run.text.strip():
            if run.font.color.rgb is None:
                return 0.0
            if run.font.color.rgb.r != target_r or run.font.color.rgb.g != target_g or run.font.color.rgb.b != target_b:
                return 0.0
    return 1.0

