def check_docx_uppercase__67090a7f(result_file, expected, **options):
    """Check if all text in docx file is uppercase.

    Args:
        result_file: Path to the result docx file
        expected: Expected value dict with rules
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result_file:
        return 0.0
    try:
        doc = Document(result_file)
        total_chars = 0
        uppercase_chars = 0
        for para in doc.paragraphs:
            for run in para.runs:
                text = run.text
                for char in text:
                    if char.isalpha():
                        total_chars += 1
                        if char.isupper():
                            uppercase_chars += 1
        if total_chars == 0:
            return 0.0
        percentage = uppercase_chars / total_chars
        if percentage >= 0.99:
            return 1.0
        else:
            return percentage
    except Exception as e:
        print(f'Error checking uppercase: {e}')
        return 0.0

def check_writer_first_n_rows__92370bc17bf2e2a5bd844c976eb32eb3(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if Writer document has expected number of rows including header.

    Args:
        result: Dict from getter with table data
        expected: Dict with expected row count and content validation rules
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if 'error' in result:
        return 0.0
    expected_count = expected.get('row_count', 0)
    actual_count = result.get('row_count', 0)
    if actual_count != expected_count:
        return 0.0
    rows = result.get('rows', [])
    if len(rows) == 0:
        return 0.0
    if 'first_cell' in expected:
        if len(rows[0]) > 0:
            first_val = rows[0][0]
            expected_val = expected['first_cell']
            if first_val != expected_val and str(first_val) != str(expected_val):
                return 0.0
        else:
            return 0.0
    if 'quantities' in expected:
        expected_quantities = expected['quantities']
        actual_quantities = []
        for i in range(1, len(rows)):
            row = rows[i]
            for cell_val in row:
                if isinstance(cell_val, (int, float)):
                    if int(cell_val) in expected_quantities:
                        actual_quantities.append(int(cell_val))
                        break
                elif isinstance(cell_val, str):
                    try:
                        val = int(cell_val.replace(',', ''))
                        if val in expected_quantities:
                            actual_quantities.append(val)
                            break
                    except:
                        continue
        if actual_quantities != expected_quantities:
            return 0.0
    if 'header_keywords' in expected:
        header_keywords = expected['header_keywords']
        header_row = rows[0]
        header_text = ' '.join([str(cell).lower() for cell in header_row])
        for keyword in header_keywords:
            if keyword.lower() not in header_text:
                return 0.0
    return 1.0

