def check_docx_min_locations__48637897(result_file_path, expected, **options):
    """
    Check if document contains minimum number of metro station location entries in Chinese.

    Verifies:
    1. Text is in Chinese (contains Chinese characters)
    2. Text mentions metro station (地铁站/站/号线)
    3. Text mentions Futian District or Shenzhen (福田/深圳)
    4. Text has address-like characteristics

    Args:
        result_file_path: Path to the result DOCX file
        expected: Dict with 'min_count' - minimum required locations
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result_file_path is None:
        return 0.0
    min_count = expected.get('min_count', 5)
    futian_stations = ['会展中心', '购物公园', '福田', '市民中心', '少年宫', '莲花村', '华强路', '岗厦', '岗厦北', '福民', '石厦', '益田', '香蜜湖', '车公庙', '福田口岸', '皇岗村', '赤尾', '华新', '通新岭', '莲花北', '红岭北', '上梅林', '民乐', '白石龙', '深圳北', '红山', '上塘', '龙华', '深圳会展中心']
    try:
        doc = Document(result_file_path)
        valid_locations = []
        for para in doc.paragraphs:
            text = para.text.strip()
            if not text or len(text) <= 5:
                continue
            if not re.search('[\\u4e00-\\u9fff]', text):
                continue
            metro_keywords = ['地铁站', '站', '号线', '线']
            has_metro_keyword = any((keyword in text for keyword in metro_keywords))
            location_keywords = ['福田', '深圳']
            has_location = any((keyword in text for keyword in location_keywords))
            has_known_station = any((station in text for station in futian_stations))
            address_patterns = ['区', '街道', '路', '大道', '地铁', '号', '站']
            has_address_pattern = any((pattern in text for pattern in address_patterns))
            is_valid = (has_metro_keyword or has_known_station) and (has_location or has_known_station) and has_address_pattern
            if is_valid:
                valid_locations.append(text)
        actual_count = len(valid_locations)
        if actual_count >= min_count:
            return 1.0
        elif actual_count > 0:
            return actual_count / min_count
        else:
            return 0.0
    except Exception as e:
        print(f'Error reading document: {e}')
        return 0.0

