def check_docx_bold_text__80c75f88(result, expected, **options):
    """
    Check if specific text is formatted as bold throughout the document.

    Args:
        result: File bytes from vm_file getter
        expected: Dict with 'rules' containing:
            - target_word: Word to search for
            - must_be_bold: Whether it should be bold (True/False)
            - case_insensitive: Whether search is case-insensitive
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        target_word = expected.get('target_word', '')
        must_be_bold = expected.get('must_be_bold', True)
        case_insensitive = expected.get('case_insensitive', True)
        doc = Document(io.BytesIO(result))
        total_occurrences = 0
        bold_occurrences = 0
        for para in doc.paragraphs:
            for run in para.runs:
                text = run.text
                search_text = text.lower() if case_insensitive else text
                search_target = target_word.lower() if case_insensitive else target_word
                if search_target in search_text:
                    count = search_text.count(search_target)
                    total_occurrences += count
                    if run.bold:
                        bold_occurrences += count
        for table in doc.tables:
            for row in table.rows:
                for cell in row.cells:
                    for para in cell.paragraphs:
                        for run in para.runs:
                            text = run.text
                            search_text = text.lower() if case_insensitive else text
                            search_target = target_word.lower() if case_insensitive else target_word
                            if search_target in search_text:
                                count = search_text.count(search_target)
                                total_occurrences += count
                                if run.bold:
                                    bold_occurrences += count
        if total_occurrences == 0:
            return 0.0
        ratio = bold_occurrences / total_occurrences
        if ratio >= 0.8:
            return 1.0
        else:
            return ratio / 0.8
    except Exception as e:
        print(f'Error in check_docx_bold_text__80c75f88: {e}')
        return 0.0

