def check_docx_line_spacing__597eae9cea0a72757fe99e2e7f6f305e(result, expected, **options):
    """Check if specific paragraphs have expected line spacing.

    Args:
        result: Dict mapping paragraph index to line spacing value from getter
        expected: Dict with 'spacings' key containing expected {para_idx: spacing} mapping
        **options: Additional options (tolerance for float comparison)

    Returns:
        float: Score between 0.0 and 1.0 (1.0 = all spacings match)
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        logger.error(f'Invalid input types: result={type(result)}, expected={type(expected)}')
        return 0.0
    expected_spacings = expected.get('spacings', {})
    if not expected_spacings:
        logger.error('No expected spacings provided')
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    matched = 0
    total = len(expected_spacings)
    for (para_idx, expected_spacing) in expected_spacings.items():
        para_idx_int = int(para_idx)
        actual_spacing = result.get(para_idx_int)
        if actual_spacing is not None and abs(actual_spacing - expected_spacing) <= tolerance:
            matched += 1
        else:
            logger.debug(f'Paragraph {para_idx}: expected {expected_spacing}, got {actual_spacing}')
    score = matched / total if total > 0 else 0.0
    logger.info(f'Line spacing check: {matched}/{total} paragraphs matched (score={score})')
    return score

