def check_docx_font_size__80877825(docx_file, rules: dict):
    """Check if all text in the document has the specified font size.

    Args:
        docx_file: Path to the DOCX file
        rules: Dictionary with 'font_size' key specifying the expected font size in pt

    Returns:
        float: 1.0 if all text has the expected font size, 0.0 otherwise
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error opening document: {e}')
        return 0.0
    expected_size = rules.get('font_size')
    if expected_size is None:
        logger.error('No font_size specified in rules')
        return 0.0
    for paragraph in doc.paragraphs:
        for run in paragraph.runs:
            if run.font.size is None:
                logger.info(f'Found run with no explicit font size (using default)')
                return 0.0
            actual_size_pt = run.font.size.pt
            if actual_size_pt != expected_size:
                logger.info(f'Expected font size {expected_size}pt, found {actual_size_pt}pt')
                return 0.0
    return 1.0

