def check_docx_highlighted_word__f4a8d2f1(result_file, expected, **options):
    """
    Check if a Word document contains specific text with highlighted words.
    Verifies paragraph structure: each response should be in its own paragraph,
    separated by new lines. Uses exact matching to ensure ONLY expected texts are present.

    Args:
        result_file: Path to the result .docx file
        expected: Dictionary with 'texts' (list of expected texts) and 'highlighted_word'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result_file or not result_file.endswith('.docx'):
        return 0.0
    try:
        doc = Document(result_file)
    except Exception as e:
        print(f'Error reading document: {e}')
        return 0.0
    expected_texts = expected.get('texts', [])
    highlighted_word = expected.get('highlighted_word', '')
    if not expected_texts or not highlighted_word:
        return 0.0
    non_empty_paragraphs = [p.text.strip() for p in doc.paragraphs if p.text.strip()]
    content_score = 0.0
    if len(non_empty_paragraphs) != len(expected_texts):
        content_score = 0.0
    else:
        matched_expected = set()
        matched_paragraphs = set()
        for (i, paragraph_text) in enumerate(non_empty_paragraphs):
            para_normalized = re.sub('\\s+', ' ', paragraph_text).strip()
            for (j, expected_text) in enumerate(expected_texts):
                if j not in matched_expected:
                    expected_normalized = re.sub('\\s+', ' ', expected_text).strip()
                    if expected_normalized == para_normalized:
                        matched_expected.add(j)
                        matched_paragraphs.add(i)
                        break
        if len(matched_expected) == len(expected_texts) and len(matched_paragraphs) == len(non_empty_paragraphs):
            content_score = 0.5
        else:
            content_score = 0.5 * (len(matched_expected) / len(expected_texts))
    highlight_score = 0.0
    highlighted_count = 0
    total_word_count = 0
    for paragraph_text in non_empty_paragraphs:
        total_word_count += paragraph_text.count(highlighted_word)
    if total_word_count > 0:
        for paragraph in doc.paragraphs:
            if paragraph.text.strip():
                for run in paragraph.runs:
                    if highlighted_word in run.text:
                        if run.font.highlight_color is not None:
                            highlighted_count += run.text.count(highlighted_word)
        if highlighted_count >= total_word_count:
            highlight_score = 0.5
        elif highlighted_count > 0:
            highlight_score = 0.5 * (highlighted_count / total_word_count)
    return content_score + highlight_score

