def check_docx_text_formatting__2ccb30d0bc330cfb3498fc1ffe64e170(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if text content matches expected responses and formatting is correct.

    Args:
        result: Dictionary from getter with paragraphs data and source responses
        expected: Expected rules (num_responses, target_word, etc.)
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    paragraphs = result.get('paragraphs', [])
    source_responses = result.get('source_responses', [])
    expected_num_responses = expected.get('num_responses', 6)
    target_word = expected.get('target_word', 'Odyssey')
    expected_target_word_count = expected.get('target_word_count', 7)
    non_empty_paragraphs = [p for p in paragraphs if p.get('text', '').strip()]
    if len(non_empty_paragraphs) != expected_num_responses:
        return 0.0
    if len(non_empty_paragraphs) > 1:
        non_empty_indices = []
        for (idx, p) in enumerate(paragraphs):
            if p.get('text', '').strip():
                non_empty_indices.append(idx)
        for i in range(len(non_empty_indices) - 1):
            current_idx = non_empty_indices[i]
            next_idx = non_empty_indices[i + 1]
            has_blank_between = False
            for j in range(current_idx + 1, next_idx):
                if not paragraphs[j].get('text', '').strip():
                    has_blank_between = True
                    break
            if not has_blank_between:
                return 0.0
    total_target_words = 0
    correctly_formatted = 0
    target_pattern = re.compile('\\b' + re.escape(target_word) + '\\b')
    for para in non_empty_paragraphs:
        runs = para.get('runs', [])
        for run_info in runs:
            run_text = run_info.get('text', '')
            matches = target_pattern.findall(run_text)
            target_count_in_run = len(matches)
            if target_count_in_run > 0:
                total_target_words += target_count_in_run
                if run_info.get('bold', False):
                    correctly_formatted += target_count_in_run
    if total_target_words != expected_target_word_count:
        return 0.0
    if total_target_words == 0:
        return 0.0
    score = correctly_formatted / total_target_words
    if score < 1.0:
        return score
    if source_responses and len(source_responses) >= expected_num_responses:
        content_match_count = 0
        for para in non_empty_paragraphs:
            para_text = para.get('text', '').strip()
            if len(para_text) < 50:
                continue
            best_match_ratio = 0.0
            for source_resp in source_responses:
                source_text = str(source_resp).strip()
                similarity = SequenceMatcher(None, para_text.lower(), source_text.lower()).ratio()
                if similarity > best_match_ratio:
                    best_match_ratio = similarity
            if best_match_ratio >= 0.7:
                content_match_count += 1
        required_matches = int(expected_num_responses * 0.8)
        if content_match_count < required_matches:
            return 0.0
    total_length = sum((len(p.get('text', '')) for p in non_empty_paragraphs))
    avg_length = total_length / len(non_empty_paragraphs) if non_empty_paragraphs else 0
    if avg_length < 100:
        return 0.5
    return score

