def check_pdf_pages__f953191d(pdf_file: str, rules: Dict[str, Any]) -> float:
    """
    Check if PDF has the expected number of pages and optionally verify content.

    Args:
        pdf_file: Path to the PDF file
        rules: Dict with 'relation', 'ref_value', and optional 'verify_content' flag

    Returns:
        float: 1.0 if conditions met, 0.0 otherwise
    """
    if pdf_file is None:
        return 0.0
    if not os.path.exists(pdf_file):
        return 0.0
    reader = PdfReader(pdf_file)
    nb_pages: int = len(reader.pages)
    page_count_matches = getattr(operator, rules['relation'])(nb_pages, rules['ref_value'])
    if not page_count_matches:
        return 0.0
    if rules.get('verify_content', False):
        file_size = os.path.getsize(pdf_file)
        if file_size < 10240:
            return 0.0
        has_images = False
        for page in reader.pages:
            if '/XObject' in page['/Resources']:
                xobjects = page['/Resources']['/XObject'].get_object()
                for obj in xobjects:
                    if xobjects[obj]['/Subtype'] == '/Image':
                        has_images = True
                        break
            if has_images:
                break
        if not has_images:
            return 0.0
    return 1.0

