def check_docx_formatted_words__14c7d824(result_file, expected, **options):
    """
    Check if words matching the filter have the correct formatting.

    Args:
        result_file: Path to the result .docx file
        expected: Expected value with rules (expected_count)
        **options: Additional options

    Returns:
        float: 1.0 if all matching words have correct formatting, 0.0 otherwise
    """
    if not result_file:
        return 0.0
    try:
        doc = Document(result_file)
    except Exception:
        return 0.0

    def has_consecutive_letters(word):
        word_lower = word.lower()
        return any((word_lower[j] == word_lower[j + 1] for j in range(len(word_lower) - 1)))
    matching_words_found = 0
    matching_words_underlined = 0
    for paragraph in doc.paragraphs:
        for run in paragraph.runs:
            words = re.findall('\\b\\w+\\b', run.text)
            for word in words:
                if word and has_consecutive_letters(word):
                    matching_words_found += 1
                    if run.underline:
                        matching_words_underlined += 1
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    for run in paragraph.runs:
                        words = re.findall('\\b\\w+\\b', run.text)
                        for word in words:
                            if word and has_consecutive_letters(word):
                                matching_words_found += 1
                                if run.underline:
                                    matching_words_underlined += 1
    if matching_words_found == 0:
        return 0.0
    if matching_words_found == matching_words_underlined:
        return 1.0
    return 0.0

