def check_docx_reference_exists__e8417487(result, expected, **options):
    """Check if a complete reference with all components exists in References section.

    Args:
        result: Path to the result DOCX file
        expected: Dict with reference components: 'authors', 'year', 'title',
                  'journal', 'volume_issue', 'pages', 'doi'

    Returns:
        float: Score based on presence of all reference components together
    """
    if not result or not isinstance(result, str):
        return 0.0
    try:
        doc = Document(result)
        authors = expected.get('authors', '')
        year = expected.get('year', '')
        title = expected.get('title', '')
        journal = expected.get('journal', '')
        volume_issue = expected.get('volume_issue', '')
        pages = expected.get('pages', '')
        doi = expected.get('doi', '')
        in_references = False
        reference_paragraphs = []
        for para in doc.paragraphs:
            para_text = para.text.strip()
            if not in_references:
                heading_patterns = ['^references\\s*$', '^bibliography\\s*$', '^works\\s+cited\\s*$', '^literature\\s+cited\\s*$']
                for pattern in heading_patterns:
                    if re.match(pattern, para_text.lower()):
                        in_references = True
                        break
                continue
            if in_references and para_text:
                if len(para_text) < 50 and (para_text.isupper() or (para.style and 'Heading' in str(para.style.name))):
                    break
                reference_paragraphs.append(para_text)
        component_scores = {'authors': 0.2, 'year': 0.1, 'title': 0.2, 'journal': 0.2, 'volume_issue': 0.1, 'pages': 0.1, 'doi': 0.1}
        complete_reference_found = False
        for ref_para in reference_paragraphs:
            ref_lower = ref_para.lower()
            has_all = True
            if authors and authors.lower() not in ref_lower:
                has_all = False
            if year and year not in ref_para:
                has_all = False
            if title and title.lower() not in ref_lower:
                has_all = False
            if journal and journal.lower() not in ref_lower:
                has_all = False
            if volume_issue and volume_issue not in ref_para:
                has_all = False
            if pages and pages not in ref_para:
                has_all = False
            if doi and doi not in ref_para:
                has_all = False
            if has_all:
                complete_reference_found = True
                break
        if complete_reference_found:
            return 1.0
        all_refs_text = ' '.join(reference_paragraphs).lower()
        score = 0.0
        if authors and authors.lower() in all_refs_text:
            score += component_scores['authors']
        if year and year in ' '.join(reference_paragraphs):
            score += component_scores['year']
        if title and title.lower() in all_refs_text:
            score += component_scores['title']
        if journal and journal.lower() in all_refs_text:
            score += component_scores['journal']
        if volume_issue and volume_issue in ' '.join(reference_paragraphs):
            score += component_scores['volume_issue']
        if pages and pages in ' '.join(reference_paragraphs):
            score += component_scores['pages']
        if doi and doi in ' '.join(reference_paragraphs):
            score += component_scores['doi']
        return score
    except Exception as e:
        print(f'Error in check_docx_reference_exists__e8417487: {e}')
        return 0.0

