def check_line_spacing__230dbd91(result, expected, **options):
    """Check if line spacing matches expected value.

    Args:
        result: Line spacing dict from getter
        expected: Expected line spacing value (e.g., 1.5, 2.0)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        logger.error('No line spacing data')
        return 0.0
    expected_value = expected.get('value')
    if expected_value is None:
        logger.error('No expected value provided')
        return 0.0
    actual_value = result.get('value')
    if actual_value is None:
        logger.warning('No actual line spacing value found')
        return 0.0
    tolerance = options.get('tolerance', 0.1)
    if abs(actual_value - expected_value) <= tolerance:
        logger.info(f'✓ Line spacing matches: {actual_value} ≈ {expected_value}')
        return 1.0
    else:
        logger.warning(f'✗ Line spacing mismatch: expected {expected_value}, got {actual_value}')
        diff = abs(actual_value - expected_value)
        if diff < 0.5:
            return 1.0 - diff / 0.5 * 0.5
        return 0.0

