def check_docx_alignment__de3cebe4(result_file, expected, **options):
    """Check if all paragraphs in docx file have specified alignment.

    Args:
        result_file: Path to the result docx file
        expected: Expected value dict with rules containing 'alignment'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result_file:
        return 0.0
    try:
        doc = Document(result_file)
        target_alignment = expected.get('alignment', 'CENTER')
        alignment_map = {'LEFT': WD_PARAGRAPH_ALIGNMENT.LEFT, 'CENTER': WD_PARAGRAPH_ALIGNMENT.CENTER, 'RIGHT': WD_PARAGRAPH_ALIGNMENT.RIGHT, 'JUSTIFY': WD_PARAGRAPH_ALIGNMENT.JUSTIFY}
        target_enum = alignment_map.get(target_alignment.upper(), WD_PARAGRAPH_ALIGNMENT.CENTER)
        total_paragraphs_with_text = 0
        correct_alignment_paragraphs = 0
        for para in doc.paragraphs:
            if para.text.strip():
                total_paragraphs_with_text += 1
                if para.alignment == target_enum:
                    correct_alignment_paragraphs += 1
        if total_paragraphs_with_text == 0:
            return 0.0
        percentage = correct_alignment_paragraphs / total_paragraphs_with_text
        if percentage >= 0.95:
            return 1.0
        else:
            return percentage
    except Exception as e:
        print(f'Error checking alignment: {e}')
        return 0.0

def check_default_font_size__df371ef8(config_file_path, rules):
    """Check the default font size in LibreOffice Writer (variation 1: 14pt)."""
    default_size = None
    expected_size = str(rules['font_size'])
    if not config_file_path:
        return 0
    try:
        tree = ET.parse(config_file_path)
        root = tree.getroot()
        namespace = {'oor': 'http://openoffice.org/2001/registry'}
        for elem in root.findall('.//item[@oor:path="/org.openoffice.Office.Writer/DefaultFont"]', namespace):
            for prop in elem.findall('.//prop[@oor:name="StandardHeight"]', namespace):
                for value in prop.findall('value', namespace):
                    default_size = value.text
    except Exception as e:
        logger.error(f'Error: {e}')
    return 1 if default_size == expected_size else 0

def check_italic_underline__176d7b875bae8ec1c11de1f17d63e097(result, expected, **options):
    """
    Check if all italic text in the document also has underline formatting.

    Args:
        result: Path to the docx file to check
        expected: Dictionary containing 'reference_file' URL or path to expected docx file
        **options: Additional options

    Returns:
        float: 1.0 if all italic text also has underline, 0.0 otherwise
    """
    if not result or not expected:
        return 0.0
    expected_path = expected
    if isinstance(expected, dict):
        reference_url = expected.get('reference_file')
        if not reference_url:
            logger.error("No 'reference_file' found in expected dictionary")
            return 0.0
        try:
            logger.info(f'Downloading reference file from {reference_url}')
            response = requests.get(reference_url, timeout=30)
            response.raise_for_status()
            with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
                tmp.write(response.content)
                expected_path = tmp.name
                logger.info(f'Reference file saved to {expected_path}')
        except Exception as e:
            logger.error(f'Error downloading reference file: {e}')
            return 0.0
    try:
        doc_result = Document(result)
        doc_expected = Document(expected_path)
    except Exception as e:
        logger.error(f'Error opening documents: {e}')
        if isinstance(expected, dict) and os.path.exists(expected_path):
            try:
                os.unlink(expected_path)
            except:
                pass
        return 0.0
    result_paragraphs = [p.text for p in doc_result.paragraphs]
    expected_paragraphs = [p.text for p in doc_expected.paragraphs]
    if len(result_paragraphs) != len(expected_paragraphs):
        if isinstance(expected, dict) and os.path.exists(expected_path):
            try:
                os.unlink(expected_path)
            except:
                pass
        return 0.0
    for (p1, p2) in zip(result_paragraphs, expected_paragraphs):
        if p1.strip() != p2.strip():
            if isinstance(expected, dict) and os.path.exists(expected_path):
                try:
                    os.unlink(expected_path)
                except:
                    pass
            return 0.0
    for paragraph in doc_result.paragraphs:
        for run in paragraph.runs:
            if run.italic:
                if run.font.underline is None or not run.font.underline:
                    logger.info(f"Found italic text without underline: '{run.text}'")
                    if isinstance(expected, dict) and os.path.exists(expected_path):
                        try:
                            os.unlink(expected_path)
                        except:
                            pass
                    return 0.0
    if isinstance(expected, dict) and os.path.exists(expected_path):
        try:
            os.unlink(expected_path)
        except:
            pass
    return 1.0

