def check_docx_formatted_words__a2e6c95b(result_file, expected, **options):
    """
    Check if words matching the filter have the correct formatting.

    Args:
        result_file: Path to the result .docx file
        expected: Expected value (not used, filter is in code)
        **options: Additional options

    Returns:
        float: 1.0 if all matching words have correct formatting, 0.0 otherwise
    """
    if not result_file:
        return 0.0
    try:
        doc = Document(result_file)
    except Exception:
        return 0.0

    def should_format(w):
        return len(w) <= 3

    def check_runs_for_words(runs):
        """
        Check runs for words that need formatting.
        Returns False if any word that should be formatted is not italic.
        """
        for run in runs:
            if not run.text:
                continue
            words = re.findall('\\b\\w+\\b', run.text)
            for word in words:
                if should_format(word):
                    if not run.italic:
                        return False
        return True
    for paragraph in doc.paragraphs:
        if not check_runs_for_words(paragraph.runs):
            return 0.0
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    if not check_runs_for_words(paragraph.runs):
                        return 0.0
    for section in doc.sections:
        header = section.header
        for paragraph in header.paragraphs:
            if not check_runs_for_words(paragraph.runs):
                return 0.0
        footer = section.footer
        for paragraph in footer.paragraphs:
            if not check_runs_for_words(paragraph.runs):
                return 0.0
    return 1.0

def check_docx_font_colors__19e803f1f0b772e18ba3645767900e72(result: List[Tuple[int, int, int]], expected: Dict, **options) -> float:
    """Check if document contains text with expected color.

    Args:
        result: List of RGB color tuples from the document
        expected: Expected configuration from rules dict with 'target_color' (r, g, b)
        **options: Additional options (color_tolerance for fuzzy matching)

    Returns:
        1.0 if all text has target color (with tolerance), 0.0 otherwise
    """
    target_color = expected.get('target_color')
    tolerance = options.get('color_tolerance', 30)
    if not target_color:
        return 0.0
    if not result:
        return 0.0
    for color in result:
        r_diff = abs(color[0] - target_color[0])
        g_diff = abs(color[1] - target_color[1])
        b_diff = abs(color[2] - target_color[2])
        if r_diff > tolerance or g_diff > tolerance or b_diff > tolerance:
            return 0.0
    return 1.0

def check_macys_url_params__29ba7d7c48cbc7f21a5e114affc6f1be(result, expected, **options):
    """
    Compare Macy's URL parsing result against expected values.
    Variation 4: men's medium-size short-sleeve shirts with any discount.

    Args:
        result: Dictionary from getter function
        expected: Expected dictionary with filter values
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 and 1.0
    """
    logger.info(f'[DEBUG] check_macys_url_params called with result: {result}')
    logger.info(f'[DEBUG] check_macys_url_params called with expected: {expected}')
    if result is None:
        logger.info('[DEBUG] Result is None, returning 0.0')
        return 0.0
    expected_dict = expected.get('expected', {})
    score = 0.0
    total_fields = len(expected_dict)
    if total_fields == 0:
        return 0.0
    for (key, expected_value) in expected_dict.items():
        if key in result and result[key] == expected_value:
            score += 1.0
            logger.info(f"[DEBUG] Field '{key}' matches: {result[key]} == {expected_value}")
        else:
            logger.info(f"[DEBUG] Field '{key}' mismatch: {result.get(key)} != {expected_value}")
    final_score = score / total_fields
    logger.info(f'[DEBUG] Final score: {final_score} ({score}/{total_fields} fields matched)')
    return final_score

def check_docx_lowercase__36692c9a0775f222c7be183b53e60594(result, expected, **options):
    """Check if all text in the document is lowercase.

    Args:
        result: dict with 'paragraphs' key containing list of paragraph texts
        expected: dict (rules) - not used for this check
        **options: Additional options

    Returns:
        float: 1.0 if all text is lowercase, 0.0 otherwise
    """
    if not result or 'paragraphs' not in result:
        return 0.0
    paragraphs = result['paragraphs']
    if not paragraphs:
        return 0.0
    for para in paragraphs:
        alpha_chars = [c for c in para if c.isalpha()]
        if not alpha_chars:
            continue
        if any((c.isupper() for c in alpha_chars)):
            return 0.0
    return 1.0

