def check_page_number_color_orange__b2ed7834(pptx_file, rules):
    """Check if slide numbers are colored orange.

    Args:
        pptx_file: Path to the PPTX file
        rules: Dictionary with 'color' key (expected: 'orange')

    Returns:
        1.0 if slide numbers are orange, 0.0 otherwise
    """
    color = rules['color']

    def is_orange(rgb_str, threshold=30):
        (r, g, b) = (int(rgb_str[1:3], 16), int(rgb_str[3:5], 16), int(rgb_str[5:7], 16))
        return r > 200 and 100 < g < 200 and (b < 100)
    with zipfile.ZipFile(pptx_file, 'r') as zip_ref:
        slide_master_name = 'ppt/slideMasters/slideMaster1.xml'
        with zip_ref.open(slide_master_name) as slide_master_file:
            tree = ET.parse(slide_master_file)
            root = tree.getroot()
            namespaces = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main', 'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}
            color_elems = root.findall('.//a:solidFill//a:srgbClr', namespaces)
            for color_elem in color_elems:
                rgb_val = color_elem.get('val')
                if rgb_val and is_orange(rgb_val):
                    return 1.0
    return 0.0

