def check_italic_yellow_highlight__4db38c61(result_path, expected_rules, **options):
    """Check if all italic text has yellow highlight.

    Args:
        result_path: Path to the result DOCX file
        expected_rules: Expected rules
        **options: Additional options

    Returns:
        float: 1.0 if all italic text has yellow highlight, 0.0 otherwise
    """
    if not result_path:
        return 0.0
    try:
        doc = Document(result_path)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    italic_count = 0
    highlighted_count = 0
    for paragraph in doc.paragraphs:
        for run in paragraph.runs:
            if run.italic and run.text.strip():
                italic_count += 1
                if run.font.highlight_color:
                    highlighted_count += 1
    if italic_count == 0:
        return 0.0
    return 1.0 if highlighted_count == italic_count else 0.0

def check_googledoc_content__cb1a63e54bdfaf51469b71532be0ad88(result: str, expected: Dict[str, Any], **options) -> float:
    """
    Check if Google Doc contains expected content with partial credit scoring.

    This metric validates document content by checking for required keywords/phrases
    and minimum length requirements.

    Args:
        result: Text content extracted from the Google Doc
        expected: Rules dict with:
            - required_keywords: List of keywords that must appear (case-insensitive)
            - min_length: Minimum character count (optional)
            - title_keywords: Keywords that should appear near the start (optional)
        **options: Additional options (not used currently)

    Returns:
        float: Score from 0.0 to 1.0:
            - 0.4: Document exists and has content
            - +0.3: Contains all required keywords
            - +0.2: Meets minimum length requirement (if specified)
            - +0.1: Title keywords appear in first 500 chars (if specified)
    """
    if not result or len(result.strip()) == 0:
        return 0.0
    score = 0.0
    result_lower = result.lower()
    score += 0.4
    required_keywords = expected.get('required_keywords', [])
    if required_keywords:
        keywords_found = sum((1 for kw in required_keywords if kw.lower() in result_lower))
        keyword_ratio = keywords_found / len(required_keywords)
        score += 0.3 * keyword_ratio
    else:
        score += 0.3
    min_length = expected.get('min_length', 0)
    if min_length > 0:
        if len(result) >= min_length:
            score += 0.2
    else:
        score += 0.2
    title_keywords = expected.get('title_keywords', [])
    if title_keywords:
        first_section = result_lower[:500]
        title_found = sum((1 for kw in title_keywords if kw.lower() in first_section))
        title_ratio = title_found / len(title_keywords)
        score += 0.1 * title_ratio
    else:
        score += 0.1
    return min(score, 1.0)

