def check_font_calibri__9ebe71c7325cdd1ca6ece79f9fe24f63(docx_file, expected, **options):
    """
    Check if all text in the document uses Calibri font.

    Args:
        docx_file: Path to the DOCX file or file bytes
        expected: Expected value dict with 'font_name' key
        **options: Additional options

    Returns:
        float: 1.0 if all text is Calibri, 0.0 otherwise
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
