def check_default_font_size__89a41ac8(config_file_path, rules):
    """Check the default font size for standard paragraphs in LibreOffice Writer."""
    default_font_size = None
    expected_font_size = rules['font_size']
    if not config_file_path:
        return 0
    try:
        tree = ET.parse(config_file_path)
        root = tree.getroot()
        namespace = {'oor': 'http://openoffice.org/2001/registry'}
        for elem in root.findall('.//item[@oor:path="/org.openoffice.Office.Writer/DefaultFont"]', namespace):
            for prop in elem.findall('.//prop[@oor:name="StandardSize"]', namespace):
                for value in prop.findall('value', namespace):
                    default_font_size = value.text
    except Exception as e:
        logger.error(f'Error: {e}')
    return 1 if default_font_size == expected_font_size else 0

def check_odt_font_size__a34364cfed7c7e9e11ed1d12c2e11819(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if specific text has a font size greater than or equal to the expected minimum.

    Args:
        result: Dict with 'text_with_sizes' list from getter
        expected: Dict with 'target_text' and 'min_font_size' (in pt)
        **options: Additional options

    Returns:
        float: 1.0 if target text has font size >= min_font_size, 0.0 otherwise
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    text_with_sizes = result.get('text_with_sizes', [])
    target_text = expected.get('target_text', '')
    min_font_size = expected.get('min_font_size', '')
    if not target_text or not min_font_size:
        return 0.0
    if isinstance(min_font_size, str):
        min_size_value = float(min_font_size.replace('pt', ''))
    else:
        min_size_value = float(min_font_size)
    for item in text_with_sizes:
        text = item.get('text', '')
        font_size = item.get('font_size', '')
        if target_text in text:
            if isinstance(font_size, str):
                size_value = float(font_size.replace('pt', ''))
            else:
                size_value = float(font_size)
            if size_value >= min_size_value:
                return 1.0
    return 0.0

def check_centered_page_numbers__8ab094fd00d45aa7b27a2fdfc3febbf3(docx_file, expected):
    """
    Check if the document has automatic page numbers in footers with centered alignment.

    Verifies:
    1. Footer exists in all sections
    2. Footer contains actual PAGE field (automatic page numbering), not just digit text
    3. Page number is in a center-aligned paragraph

    Args:
        docx_file: Path to the .docx file
        expected: Expected configuration (not used for this metric)

    Returns:
        float: 1.0 if centered automatic page numbers exist in all footers, 0.0 otherwise
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    for section in doc.sections:
        footer = section.footer
        if footer is None or not footer.paragraphs:
            logger.debug('Section missing footer or footer paragraphs')
            return 0.0
        found_centered_page_field = False
        for para in footer.paragraphs:
            if _has_page_field(para):
                if para.paragraph_format.alignment == WD_PARAGRAPH_ALIGNMENT.CENTER:
                    found_centered_page_field = True
                    break
        if not found_centered_page_field:
            logger.debug('Section footer does not have centered automatic page number')
            return 0.0
    return 1.0

def check_pdf_pages__703df7c6(pdf_file: str, rules: Dict[str, Any]) -> float:
    """
    Check if PDF has the expected number of pages and optionally verify content.

    Args:
        pdf_file: Path to the PDF file
        rules: Dict with 'relation', 'ref_value', and optional 'verify_content' flag

    Returns:
        float: 1.0 if conditions met, 0.0 otherwise
    """
    if pdf_file is None:
        return 0.0
    if not os.path.exists(pdf_file):
        return 0.0
    reader = PdfReader(pdf_file)
    nb_pages: int = len(reader.pages)
    page_count_matches = getattr(operator, rules['relation'])(nb_pages, rules['ref_value'])
    if not page_count_matches:
        return 0.0
    if rules.get('verify_content', False):
        file_size = os.path.getsize(pdf_file)
        if file_size < 10240:
            return 0.0
        has_images = False
        for page in reader.pages:
            if '/XObject' in page['/Resources']:
                xobjects = page['/Resources']['/XObject'].get_object()
                for obj in xobjects:
                    if xobjects[obj]['/Subtype'] == '/Image':
                        has_images = True
                        break
            if has_images:
                break
        if not has_images:
            return 0.0
    return 1.0

def check_docx_image_embedded__6ed140cad2fa6c5f3349fe322a43680c(result, expected, **options):
    """
    Check if DOCX file contains embedded images with required dimensions.

    Args:
        result: Dict from getter with file_exists, image_count, max_width
        expected: Dict with has_image and min_width requirements
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    if result.get('file_exists', False):
        score += 0.4
        logger.info('✓ DOCX file exists')
    else:
        logger.warning('✗ DOCX file does not exist')
        return 0.0
    has_image_expected = expected.get('has_image', True)
    image_count = result.get('image_count', 0)
    if has_image_expected and image_count > 0:
        score += 0.3
        logger.info(f'✓ Found {image_count} image(s)')
    elif not has_image_expected and image_count == 0:
        score += 0.3
        logger.info('✓ No images found as expected')
    else:
        logger.warning(f'✗ Image count {image_count} does not meet expectation')
        return score
    max_width = result.get('max_width', 0)
    min_width = expected.get('min_width', 0)
    if max_width >= min_width:
        score += 0.3
        logger.info(f'✓ Image width {max_width} >= {min_width}')
    else:
        logger.warning(f'✗ Image width {max_width} < {min_width}')
    logger.info(f'Final score: {score}')
    return score

def check_page_number_color_purple__9340dde9(pptx_file, rules):
    """Check if slide numbers are colored purple/magenta.

    Args:
        pptx_file: Path to the PPTX file
        rules: Dictionary with 'color' key (expected: 'purple')

    Returns:
        1.0 if slide numbers are purple, 0.0 otherwise
    """
    color = rules['color']

    def is_purple(rgb_str, threshold=30):
        (r, g, b) = (int(rgb_str[1:3], 16), int(rgb_str[3:5], 16), int(rgb_str[5:7], 16))
        return r > g + threshold and b > g + threshold and (abs(r - b) < 50)
    with zipfile.ZipFile(pptx_file, 'r') as zip_ref:
        slide_master_name = 'ppt/slideMasters/slideMaster1.xml'
        with zip_ref.open(slide_master_name) as slide_master_file:
            tree = ET.parse(slide_master_file)
            root = tree.getroot()
            namespaces = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main', 'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}
            color_elems = root.findall('.//a:solidFill//a:srgbClr', namespaces)
            for color_elem in color_elems:
                rgb_val = color_elem.get('val')
                if rgb_val and is_purple(rgb_val):
                    return 1.0
    return 0.0

def check_first_para_font_size__5b0ac7ad(docx_file, expected):
    """
    Check if the first paragraph has the expected font size.

    Args:
        docx_file: Path to the DOCX file
        expected: Dict with 'font_size' key (in points)

    Returns:
        float: 1.0 if all runs in first paragraph have expected size, 0.0 otherwise
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error opening document: {e}')
        return 0.0
    expected_size = expected.get('font_size', 16)
    if not doc.paragraphs:
        logger.error('Document has no paragraphs')
        return 0.0
    first_para = doc.paragraphs[0]
    if not first_para.runs:
        logger.error('First paragraph has no runs')
        return 0.0
    for run in first_para.runs:
        if run.font.size is None:
            logger.info(f'Run has no explicit font size (using default)')
            return 0.0
        actual_size = run.font.size.pt
        if actual_size != expected_size:
            logger.info(f'Font size mismatch: expected {expected_size}pt, got {actual_size}pt')
            return 0.0
    return 1.0

