def check_docx_table_contains__1c032efed907d41d75501f3895adca32(result: List[List[str]], expected: Dict[str, Any], **options) -> float:
    """Check if the document contains a table with expected digraphs and example words.

    Args:
        result: List of all tables from the document (each table is a list of rows)
        expected: Dict with 'expected_cells' - list of cell values that should exist in one of the tables
        **options: Additional options

    Returns:
        1.0 if a properly structured table with all expected digraph-example pairings is found, 0.0 otherwise
    """
    if not result:
        return 0.0
    expected_cells = expected.get('expected_cells', [])
    if not expected_cells:
        return 0.0
    expected_pairings = {'sh': ['ship'], 'ch': ['chain'], 'th': ['thin', 'this'], 'ck': ['pick'], 'ng': ['sing']}
    for table_data in result:
        if len(table_data) < 2:
            continue
        has_two_columns = all((len(row) >= 2 for row in table_data if row))
        if not has_two_columns:
            continue
        all_cells = []
        for row in table_data:
            all_cells.extend(row)
        all_cells_normalized = [cell.strip().lower() for cell in all_cells]
        all_present = all((expected_cell.strip().lower() in all_cells_normalized for expected_cell in expected_cells))
        if not all_present:
            continue
        found_pairings = 0
        total_required_pairings = len(expected_pairings)
        for row in table_data:
            if len(row) < 2:
                continue
            row_normalized = [cell.strip().lower() for cell in row]
            for (digraph, examples) in expected_pairings.items():
                if digraph in row_normalized:
                    if any((example in row_normalized for example in examples)):
                        found_pairings += 1
        if found_pairings == total_required_pairings:
            return 1.0
    return 0.0

def check_font_size__ed1a97dae9ec3a584c26acbc45279859(result, expected, **options):
    """
    Check if font size for specific paragraphs matches expected value.
    All-or-nothing scoring: all first N paragraphs must have consistent font size matching expected value.

    Args:
        result: Dict from getter with font size info
        expected: Dict with expected font size (from rules)
        **options: Additional options

    Returns:
        float: 1.0 if all first N paragraphs match expected size, 0.0 otherwise
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    expected_size = expected.get('font_size')
    num_paragraphs = expected.get('num_paragraphs', 3)
    if expected_size is None:
        return 0.0
    para_sizes = result.get('paragraph_font_sizes', [])
    if not para_sizes:
        return 0.0
    first_n_sizes = para_sizes[:num_paragraphs]
    if len(first_n_sizes) < num_paragraphs:
        return 0.0
    for size in first_n_sizes:
        if size != expected_size:
            return 0.0
    return 1.0

def check_italic_bold__ed7f193539432c8d439ccecc21c0038d(result, expected, **options):
    """
    Check if all originally-italic text in the reference document is both italic and bold in the result document.

    Args:
        result: Path to the docx file to check
        expected: Rules dictionary with 'reference_file' URL (when type='rule')
        **options: Additional options

    Returns:
        float: 1.0 if all originally-italic text is both italic and bold, 0.0 otherwise
    """
    if not result or not expected:
        return 0.0
    try:
        doc_result = Document(result)
        reference_url = expected.get('reference_file')
        if not reference_url:
            logger.error('No reference_file found in expected rules dictionary')
            return 0.0
        response = requests.get(reference_url, timeout=30)
        response.raise_for_status()
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp_file:
            tmp_file.write(response.content)
            tmp_path = tmp_file.name
        try:
            doc_expected = Document(tmp_path)
        finally:
            if os.path.exists(tmp_path):
                os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error opening documents: {e}')
        return 0.0
    result_paragraphs = [p.text for p in doc_result.paragraphs]
    expected_paragraphs = [p.text for p in doc_expected.paragraphs]
    if len(result_paragraphs) != len(expected_paragraphs):
        logger.info('Paragraph count mismatch')
        return 0.0
    for (p1, p2) in zip(result_paragraphs, expected_paragraphs):
        if p1.strip() != p2.strip():
            logger.info(f"Content mismatch in paragraph: '{p1}' vs '{p2}'")
            return 0.0
    originally_italic_runs = []
    for (para_idx, paragraph) in enumerate(doc_expected.paragraphs):
        text_position = 0
        for run in paragraph.runs:
            if run.italic and run.text.strip():
                originally_italic_runs.append({'para_idx': para_idx, 'text': run.text, 'position': text_position})
            text_position += len(run.text)
    if not originally_italic_runs:
        logger.info('No originally-italic runs found in reference document')
        return 0.0
    logger.info(f'Found {len(originally_italic_runs)} originally-italic runs in reference')
    for orig_run_info in originally_italic_runs:
        para_idx = orig_run_info['para_idx']
        orig_text = orig_run_info['text']
        orig_position = orig_run_info['position']
        if para_idx >= len(doc_result.paragraphs):
            logger.info(f'Paragraph {para_idx} not found in result')
            return 0.0
        result_paragraph = doc_result.paragraphs[para_idx]
        found = False
        text_position = 0
        for run in result_paragraph.runs:
            run_start = text_position
            run_end = text_position + len(run.text)
            if run_start <= orig_position < run_end or (run.text == orig_text and abs(text_position - orig_position) < 5):
                if not run.italic:
                    logger.info(f"Originally-italic text '{orig_text}' at para {para_idx} is no longer italic")
                    return 0.0
                if not run.bold:
                    logger.info(f"Originally-italic text '{orig_text}' at para {para_idx} is italic but not bold")
                    return 0.0
                found = True
                break
            text_position = run_end
        if not found:
            paragraph_text = result_paragraph.text
            if orig_text.strip() in paragraph_text:
                for run in result_paragraph.runs:
                    if orig_text.strip() in run.text or run.text.strip() in orig_text.strip():
                        if not run.italic or not run.bold:
                            logger.info(f"Originally-italic text '{orig_text}' found but not both italic and bold")
                            return 0.0
                        found = True
                        break
        if not found:
            logger.info(f"Originally-italic text '{orig_text}' at para {para_idx} not found in result")
            return 0.0
    logger.info(f'All {len(originally_italic_runs)} originally-italic runs are both italic and bold')
    return 1.0

def check_docx_font_size__8a9f8232(result, expected, **options):
    """
    Check if paragraphs containing a specific word have the correct font size.

    Args:
        result: File bytes from vm_file getter
        expected: Dict with 'rules' containing:
            - search_word: Word to search for
            - expected_font_size: Expected font size in points
            - case_insensitive: Whether search is case-insensitive
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        search_word = expected.get('search_word', '')
        expected_font_size = expected.get('expected_font_size', 12)
        case_insensitive = expected.get('case_insensitive', True)
        doc = Document(io.BytesIO(result))
        matching_paragraphs = 0
        correct_paragraphs = 0
        for para in doc.paragraphs:
            text = para.text
            search_text = text.lower() if case_insensitive else text
            search_target = search_word.lower() if case_insensitive else search_word
            if search_target in search_text:
                matching_paragraphs += 1
                all_correct = True
                for run in para.runs:
                    if run.font.size is not None:
                        actual_size = run.font.size.pt
                        if abs(actual_size - expected_font_size) > 0.5:
                            all_correct = False
                            break
                if all_correct and len(para.runs) > 0:
                    correct_paragraphs += 1
        if matching_paragraphs == 0:
            return 0.0
        ratio = correct_paragraphs / matching_paragraphs
        if ratio >= 0.8:
            return 1.0
        else:
            return ratio / 0.8
    except Exception as e:
        print(f'Error in check_docx_font_size__8a9f8232: {e}')
        return 0.0

