def check_docx_min_locations__806e0291(result_file_path, expected, **options):
    """
    Check if document contains minimum number of police station location entries in Chinese.

    Validates that each location:
    - Contains Chinese characters
    - Has reasonable length (at least 10 characters for a valid address)
    - Contains police station keywords (派出所 or 公安局)
    - Preferably contains location keywords (福田 or 深圳)

    Args:
        result_file_path: Path to the result DOCX file
        expected: Dict with 'min_count' - minimum required locations
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result_file_path is None:
        return 0.0
    min_count = expected.get('min_count', 3)
    try:
        doc = Document(result_file_path)
        valid_locations = []
        for para in doc.paragraphs:
            text = para.text.strip()
            if not text or len(text) < 10:
                continue
            if not re.search('[\\u4e00-\\u9fff]+', text):
                continue
            has_police_station = '派出所' in text or '公安局' in text
            if not has_police_station:
                continue
            has_location = '福田' in text or '深圳' in text
            valid_locations.append(text)
        actual_count = len(valid_locations)
        if actual_count >= min_count:
            return 1.0
        elif actual_count > 0:
            return actual_count / min_count
        else:
            return 0.0
    except Exception as e:
        print(f'Error reading document: {e}')
        return 0.0

