def check_reference_alphabetical__b9e3f600(result, expected, **options):
    """Check if new reference is in correct alphabetical position.

    Args:
        result: Path to the result DOCX file
        expected: Dict with 'new_reference', 'should_be_before', 'should_be_after' keys

    Returns:
        float: Score based on presence and position
    """
    if not result or not isinstance(result, str):
        return 0.0
    try:
        doc = Document(result)
        new_ref = expected.get('new_reference', '')
        should_be_before = expected.get('should_be_before', '')
        should_be_after = expected.get('should_be_after', '')
        in_references = False
        ref_paras = []
        for para in doc.paragraphs:
            para_text = para.text.strip()
            if 'references' in para_text.lower() and len(para_text) < 50:
                in_references = True
                continue
            if in_references and para_text:
                ref_paras.append(para_text)
        new_ref_idx = -1
        before_idx = -1
        after_idx = -1
        for (i, ref) in enumerate(ref_paras):
            if new_ref in ref:
                new_ref_idx = i
            if should_be_before in ref:
                before_idx = i
            if should_be_after in ref:
                after_idx = i
        if new_ref_idx == -1:
            return 0.0
        score = 0.5
        if after_idx >= 0 and before_idx >= 0:
            if after_idx < new_ref_idx < before_idx:
                score = 1.0
        return score
    except Exception as e:
        print(f'Error in check_reference_alphabetical__b9e3f600: {e}')
        return 0.0

def check_docx_text_formatting__8051bbbf8bb6e492bd4dea258f9abe99(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if text content matches expected responses and formatting is correct.

    Args:
        result: Dictionary from getter with paragraphs data
        expected: Expected rules (num_responses, target_word, etc.)
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    paragraphs = result.get('paragraphs', [])
    expected_num_responses = expected.get('num_responses', 6)
    target_word = expected.get('target_word', 'Homer')
    expected_word_count = expected.get('target_word_count', 7)
    non_empty_paragraphs = [p for p in paragraphs if p.get('text', '').strip()]
    if len(non_empty_paragraphs) != expected_num_responses:
        return 0.0
    expected_total_paragraphs = expected_num_responses + (expected_num_responses - 1)
    if len(paragraphs) != expected_total_paragraphs:
        return 0.0
    total_target_words = 0
    correctly_formatted = 0
    for para in non_empty_paragraphs:
        runs = para.get('runs', [])
        for run_info in runs:
            run_text = run_info.get('text', '')
            if target_word in run_text:
                target_count_in_run = run_text.count(target_word)
                total_target_words += target_count_in_run
                if run_info.get('underline', False):
                    correctly_formatted += target_count_in_run
    if total_target_words != expected_word_count:
        return 0.0
    if total_target_words == 0:
        return 0.0
    score = correctly_formatted / total_target_words if total_target_words > 0 else 0.0
    return score

def check_page_number_bold__7432dce9(pptx_file, rules):
    """Check if slide numbers are formatted as bold.

    Args:
        pptx_file: Path to the PPTX file
        rules: Dictionary with 'bold' key (expected: True)

    Returns:
        1.0 if slide numbers are bold, 0.0 otherwise
    """
    expected_bold = rules.get('bold', True)
    with zipfile.ZipFile(pptx_file, 'r') as zip_ref:
        slide_master_name = 'ppt/slideMasters/slideMaster1.xml'
        with zip_ref.open(slide_master_name) as slide_master_file:
            tree = ET.parse(slide_master_file)
            root = tree.getroot()
            namespaces = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main', 'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}
            rpr_elems = root.findall('.//a:rPr', namespaces)
            for rpr in rpr_elems:
                bold_attr = rpr.get('b')
                if bold_attr in ['1', 'true']:
                    return 1.0
    return 0.0

def check_docx_content__26f2a67b(result, expected, **options):
    """Compare docx file content against expected text.
    
    Args:
        result: Path to the docx file
        expected: Dict with 'expected_text' key containing the text to find
        **options: Additional comparison options
        
    Returns:
        float: 1.0 if expected text is found, 0.0 otherwise
    """
    ignore_case = options.get('ignore_case', True)
    fuzzy_match = options.get('fuzzy_match', True)
    if not result:
        return 0.0
    try:
        doc = Document(result)
        doc_text = '\n'.join([p.text for p in doc.paragraphs])
        expected_text = expected.get('expected_text', '')
        if not expected_text:
            return 0.0
        if ignore_case:
            doc_text_normalized = doc_text.lower()
            expected_normalized = expected_text.lower()
        else:
            doc_text_normalized = doc_text
            expected_normalized = expected_text
        doc_text_normalized = re.sub('\\s+', ' ', doc_text_normalized).strip()
        expected_normalized = re.sub('\\s+', ' ', expected_normalized).strip()
        if expected_normalized in doc_text_normalized:
            return 1.0
        if fuzzy_match:
            doc_alphanum = re.sub('[^a-z0-9]', '', doc_text_normalized)
            expected_alphanum = re.sub('[^a-z0-9]', '', expected_normalized)
            if expected_alphanum in doc_alphanum:
                return 1.0
        return 0.0
    except Exception as e:
        print(f'Error checking docx content: {e}')
        return 0.0

def check_line_spacing__32927c4d(result: List[float], expected: Dict[str, Any], **options) -> float:
    """Check if line spacing matches expected values.

    Args:
        result: List of line spacing values from getter
        expected: Dict with 'spacings' key containing list of expected spacing values
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    expected_spacings = expected.get('spacings', [])
    if len(result) != len(expected_spacings):
        return 0.0
    score = 0.0
    for (i, (actual, exp)) in enumerate(zip(result, expected_spacings)):
        if abs(actual - exp) < 0.01:
            score += 1.0 / len(expected_spacings)
    return score

