def check_page_number_italic_blue__0af91cb4(pptx_file, rules):
    """Check if slide page numbers in master slide are formatted as italic and blue."""
    try:
        with zipfile.ZipFile(pptx_file, 'r') as zip_ref:
            slide_master_name = 'ppt/slideMasters/slideMaster1.xml'
            with zip_ref.open(slide_master_name) as slide_master_file:
                tree = ET.parse(slide_master_file)
                root = tree.getroot()
                namespaces = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main', 'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}

                def is_blue(rgb_str, threshold=50):
                    (r, g, b) = (int(rgb_str[1:3], 16), int(rgb_str[3:5], 16), int(rgb_str[5:7], 16))
                    return b > g + threshold and b > r + threshold
                has_italic = False
                has_blue = False
                for sp in root.findall('.//p:sp', namespaces):
                    for ph in sp.findall('.//p:ph', namespaces):
                        ph_type = ph.get('type')
                        if ph_type == 'sldNum':
                            for rPr in sp.findall('.//a:rPr', namespaces):
                                italic_attr = rPr.get('i')
                                if italic_attr == '1':
                                    has_italic = True
                            for defRPr in sp.findall('.//a:defRPr', namespaces):
                                italic_attr = defRPr.get('i')
                                if italic_attr == '1':
                                    has_italic = True
                            color_elems = sp.findall('.//a:solidFill//a:srgbClr', namespaces)
                            for color_elem in color_elems:
                                color_val = color_elem.get('val')
                                if color_val and is_blue(color_val):
                                    has_blue = True
                                    break
                return 1.0 if has_italic and has_blue else 0.0
    except Exception as e:
        return 0.0

