def check_title_bold_and_color__c619ced4(result_file, expected, **options):
    """
    Check if the title text is both bold and has the expected color.

    Args:
        result_file: Path to the PPTX file
        expected: Expected values with 'slide_idx', 'shape_idx', 'expected_rgb'
        **options: Additional options

    Returns:
        float: 1.0 if title is bold and has expected color, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        shape_idx = expected.get('shape_idx', 0)
        expected_rgb = tuple(expected.get('expected_rgb', (255, 0, 0)))
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            return 0.0
        shape = slide.shapes[shape_idx]
        if not hasattr(shape, 'text_frame'):
            return 0.0
        has_text = False
        all_bold = True
        all_correct_color = True
        for paragraph in shape.text_frame.paragraphs:
            for run in paragraph.runs:
                if run.text.strip():
                    has_text = True
                    if not run.font.bold:
                        all_bold = False
                    if hasattr(run.font.color, 'rgb'):
                        actual_rgb = run.font.color.rgb
                        if tuple(actual_rgb) != expected_rgb:
                            all_correct_color = False
                    else:
                        all_correct_color = False
                    if not all_bold or not all_correct_color:
                        break
            if not all_bold or not all_correct_color:
                break
        if has_text and all_bold and all_correct_color:
            return 1.0
        else:
            return 0.0
    except Exception as e:
        return 0.0

def check_italic_font_size_16__38e1eedf3f5ecb88aac2d1ca73ce4a34(result, expected, **options):
    """
    Check if all italic text in the document has font size 16.

    Args:
        result: Path to the docx file to check
        expected: Path to the expected docx file or dict with 'reference_file' URL
        **options: Additional options (must include 'env' for downloading)

    Returns:
        float: 1.0 if all italic text has size 16, 0.0 otherwise
    """
    if not result or not expected:
        return 0.0
    expected_path = expected
    if isinstance(expected, dict) and 'reference_file' in expected:
        url = expected['reference_file']
        filename = os.path.basename(url.split('/')[-1])
        env = options.get('env')
        if not env:
            logger.error('Environment object not provided in options')
            return 0.0
        cache_path = os.path.join(env.cache_dir, filename)
        if not os.path.exists(cache_path):
            try:
                response = requests.get(url, stream=True)
                response.raise_for_status()
                os.makedirs(env.cache_dir, exist_ok=True)
                with open(cache_path, 'wb') as f:
                    for chunk in response.iter_content(chunk_size=8192):
                        if chunk:
                            f.write(chunk)
                logger.info(f'Downloaded reference file to {cache_path}')
            except Exception as e:
                logger.error(f'Error downloading reference file from {url}: {e}')
                return 0.0
        expected_path = cache_path
    try:
        doc_result = Document(result)
        doc_expected = Document(expected_path)
    except Exception as e:
        logger.error(f'Error opening documents: {e}')
        return 0.0
    result_paragraphs = [p.text for p in doc_result.paragraphs]
    expected_paragraphs = [p.text for p in doc_expected.paragraphs]
    if len(result_paragraphs) != len(expected_paragraphs):
        return 0.0
    for (p1, p2) in zip(result_paragraphs, expected_paragraphs):
        if p1.strip() != p2.strip():
            return 0.0
    for paragraph in doc_result.paragraphs:
        for run in paragraph.runs:
            if run.italic:
                if run.font.size is None or run.font.size.pt != 16:
                    logger.info(f"Found italic text with size {(run.font.size.pt if run.font.size else 'None')}, expected 16")
                    return 0.0
    return 1.0

