def check_docx_addresses__eb632d387236c4364430fac7b00b1c6b(result_file_path, expected, **options):
    """
    Check if document contains expected addresses using fuzzy matching.

    Args:
        result_file_path: Path to the DOCX file
        expected: Dict with 'addresses' key containing list of expected addresses
        **options: Additional options (e.g., threshold for fuzzy matching)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result_file_path is None:
        return 0.0
    expected_addresses = expected.get('addresses', [])
    required_count = expected.get('count', len(expected_addresses))
    threshold = options.get('threshold', 0.75)
    if not expected_addresses:
        return 0.0
    try:
        doc = Document(result_file_path)
        doc_text = []
        for para in doc.paragraphs:
            text = para.text.strip()
            if text:
                doc_text.append(text)
        full_text = ' '.join(doc_text)
        matches = 0
        for addr in expected_addresses:
            if any((fuzz.partial_ratio(addr, line) > threshold * 100 for line in doc_text)):
                matches += 1
            elif fuzz.partial_ratio(addr, full_text) > threshold * 100:
                matches += 1
        if matches >= required_count:
            return 1.0
        else:
            return matches / required_count
    except Exception as e:
        print(f'Error checking document: {e}')
        return 0.0

def check_highlight_with_o__96eb02f4ac90683da522ea44f75e2519(result, expected, **options):
    """
    Check if words containing the letter 'o' are highlighted in yellow.

    Args:
        result: File path to the DOCX file
        expected: Rules dict with 'target_letter' key
        **options: Additional options

    Returns:
        float: Score based on percentage of correct highlighting (0.0 to 1.0)
    """
    if not result:
        return 0.0
    target_letter = expected.get('target_letter', 'o')
    try:
        document = Document(result)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    expected_words_with_o = ['do', 'no', 'on', 'so', 'now', 'four', 'our', 'out', 'soon', 'good', 'who', 'brown', 'into', 'too']
    words_with_o_count = 0
    words_with_o_correctly_highlighted = 0
    words_without_o_count = 0
    words_without_o_incorrectly_highlighted = 0
    unique_words_with_o_found = set()
    for table in document.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    for run in paragraph.runs:
                        word = run.text.strip()
                        if word:
                            highlight = run.font.highlight_color
                            if target_letter.lower() in word.lower():
                                words_with_o_count += 1
                                unique_words_with_o_found.add(word.lower())
                                if highlight == 7:
                                    words_with_o_correctly_highlighted += 1
                                else:
                                    logger.info(f"Word '{word}' contains '{target_letter}' but highlight is {highlight}, expected 7 (yellow)")
                            else:
                                words_without_o_count += 1
                                if highlight == 7:
                                    logger.info(f"Word '{word}' does NOT contain '{target_letter}' but is incorrectly highlighted yellow")
                                    words_without_o_incorrectly_highlighted += 1
    if words_with_o_count == 0:
        logger.error(f"No words containing '{target_letter}' found in tables. Expected to find at least some of: {expected_words_with_o}")
        return 0.0
    logger.info(f"Words with '{target_letter}': {words_with_o_count} (unique: {len(unique_words_with_o_found)})")
    logger.info(f'Correctly highlighted with yellow: {words_with_o_correctly_highlighted}/{words_with_o_count}')
    logger.info(f"Words without '{target_letter}': {words_without_o_count}")
    logger.info(f'Incorrectly highlighted: {words_without_o_incorrectly_highlighted}')
    logger.info(f"Unique words with '{target_letter}' found: {sorted(unique_words_with_o_found)}")
    if words_without_o_incorrectly_highlighted > 0:
        logger.error(f"Found {words_without_o_incorrectly_highlighted} words without '{target_letter}' that are incorrectly highlighted yellow")
        return 0.0
    if words_with_o_correctly_highlighted == words_with_o_count:
        logger.info(f"All words with '{target_letter}' are correctly highlighted yellow")
        return 1.0
    else:
        score = words_with_o_correctly_highlighted / words_with_o_count
        logger.info(f'Partial credit: {words_with_o_correctly_highlighted}/{words_with_o_count} = {score:.2f}')
        return score

