def check_docx_table_structure__aa3c98fadda85fd2b11814a9c969fa8c(result: Dict, expected: Dict, **options) -> float:
    """
    Check if a table has the expected structure and cell contents.

    Args:
        result: Actual table structure from getter (dict with table_exists, row_count, col_count, cells)
        expected: Expected structure with min_rows, min_cols, expected_cols, and cell_values
        **options: Additional options

    Returns:
        1.0 if all checks pass, 0.0 otherwise
    """
    if not result.get('table_exists', False):
        logger.info('Table does not exist in document')
        return 0.0
    min_rows = expected.get('min_rows', 0)
    actual_rows = result.get('row_count', 0)
    if actual_rows < min_rows:
        logger.info(f'Insufficient rows: expected at least {min_rows}, got {actual_rows}')
        return 0.0
    expected_cols = expected.get('expected_cols')
    if expected_cols is not None:
        actual_cols = result.get('col_count', 0)
        if actual_cols != expected_cols:
            logger.info(f'Column count mismatch: expected {expected_cols}, got {actual_cols}')
            return 0.0
    cell_values = expected.get('cell_values', {})
    actual_cells = result.get('cells', {})
    for (cell_key, expected_value) in cell_values.items():
        actual_value = actual_cells.get(cell_key, '')
        if actual_value != expected_value:
            logger.info(f"Cell {cell_key} mismatch: expected '{expected_value}', got '{actual_value}'")
            return 0.0
    return 1.0

