def check_docx_font_size__b88bed88(result, expected, **options):
    """Check if specific paragraphs have correct font size.

    Args:
        result: Dict mapping paragraph index to dict with 'font_size' and 'text' keys
        expected: Dict with 'paragraphs_with_size' key, optionally 'verify_headers' dict

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_sizes = expected.get('paragraphs_with_size', {})
    if not expected_sizes:
        return 0.0
    matches = 0
    for (para_idx, expected_size) in expected_sizes.items():
        para_idx_int = int(para_idx) if isinstance(para_idx, str) else para_idx
        if para_idx_int in result:
            para_data = result[para_idx_int]
            if isinstance(para_data, dict):
                actual_size = para_data.get('font_size')
                text = para_data.get('text', '')
            else:
                actual_size = para_data
                text = ''
            if actual_size is None:
                continue
            if abs(actual_size - expected_size) < 0.5:
                matches += 1
    score = matches / len(expected_sizes)
    return score

