def check_title_size_subtitle_italic__72ce357b(result_file, expected, **options):
    """
    Check if the title font size is 28 points and if the subtitle text is italic.

    Args:
        result_file: Path to the PPTX file
        expected: Rules dictionary containing:
            - 'title_size': Float indicating expected title font size in points
            - 'subtitle_italic': Boolean indicating if subtitle should be italic
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 (partial credit supported)
    """
    try:
        prs = Presentation(result_file)
        title_size_expected = expected.get('title_size', 28.0)
        subtitle_italic_expected = expected.get('subtitle_italic', True)
        if len(prs.slides) == 0:
            logger.error('No slides found in presentation')
            return 0.0
        slide = prs.slides[0]
        title_shape = None
        subtitle_shape = None
        if hasattr(slide, 'shapes') and hasattr(slide.shapes, 'title'):
            title_shape = slide.shapes.title
        for shape in slide.shapes:
            if hasattr(shape, 'placeholder_format'):
                if shape.placeholder_format.type == 1:
                    title_shape = shape
                elif shape.placeholder_format.type == 2:
                    subtitle_shape = shape
        if title_shape is None or subtitle_shape is None:
            text_shapes = [s for s in slide.shapes if hasattr(s, 'text_frame') and hasattr(s, 'text')]
            if len(text_shapes) >= 2:
                if title_shape is None:
                    title_shape = text_shapes[0]
                if subtitle_shape is None:
                    subtitle_shape = text_shapes[1] if len(text_shapes) > 1 else None
        score = 0.0
        max_score = 2.0
        if title_shape is not None and hasattr(title_shape, 'text_frame'):
            title_size_match = True
            for paragraph in title_shape.text_frame.paragraphs:
                for run in paragraph.runs:
                    run_size = run.font.size
                    if run_size is not None:
                        run_size_pt = run_size / 12700.0
                        if abs(run_size_pt - title_size_expected) > 0.5:
                            title_size_match = False
                            logger.debug(f'Title size mismatch: found={run_size_pt:.1f}pt, expected={title_size_expected}pt')
                            break
                if not title_size_match:
                    break
            if title_size_match:
                score += 1.0
        else:
            logger.error('No title shape found')
        if subtitle_shape is not None and hasattr(subtitle_shape, 'text_frame'):
            subtitle_italic_found = False
            for paragraph in subtitle_shape.text_frame.paragraphs:
                for run in paragraph.runs:
                    if run.font.italic is True:
                        subtitle_italic_found = True
                        break
                if subtitle_italic_found:
                    break
            if subtitle_italic_found == subtitle_italic_expected:
                score += 1.0
            else:
                logger.debug(f'Subtitle italic check failed: found={subtitle_italic_found}, expected={subtitle_italic_expected}')
        else:
            logger.error('No subtitle shape found')
        return score / max_score
    except Exception as e:
        logger.error(f'Error checking title size and subtitle italic: {e}')
        return 0.0

