def check_docx_title_and_image__5faf290b(result, expected, **options):
    """
    Check if DOCX contains specific title text and an image.

    Args:
        result: Path to the DOCX file
        expected: Dict with rules specifying title_text and has_image
        **options: Additional options

    Returns:
        float: Score (0.5 for title, 0.5 for image, 1.0 for both)
    """
    if not result:
        logger.error('Result file path is None')
        return 0.0
    expected_title = expected.get('title_text', '')
    expected_has_image = expected.get('has_image', True)
    try:
        doc = Document(result)
    except Exception as e:
        logger.error(f'Error loading DOCX file: {e}')
        return 0.0
    score = 0.0
    if doc.paragraphs and len(doc.paragraphs) > 0:
        first_para_text = doc.paragraphs[0].text.strip()
        if expected_title.lower() in first_para_text.lower():
            score += 0.5
            logger.info(f"Title check passed: found '{expected_title}' in first paragraph")
        else:
            logger.error(f"Title mismatch: expected '{expected_title}', first paragraph is '{first_para_text}'")
    has_image = False
    for rel in doc.part.rels.values():
        if 'image' in rel.reltype:
            has_image = True
            break
    if has_image == expected_has_image:
        score += 0.5
        logger.info(f'Image presence check passed: {has_image}')
    else:
        logger.error(f'Image presence mismatch: expected {expected_has_image}, got {has_image}')
    logger.info(f'Final score: {score}')
    return score

