def check_docx_min_locations__8a73f43e(result_file_path, expected, **options):
    """
    Check if document contains minimum number of valid hospital location entries.

    Validates that entries:
    - Are in Chinese (contain Chinese characters)
    - Reference hospitals (contain '医院' keyword)
    - Are from Futian District (contain '福田' or '福田区')
    - Are from Shenzhen (contain '深圳')

    Args:
        result_file_path: Path to the result DOCX file
        expected: Dict with 'min_count' - minimum required locations
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result_file_path is None:
        return 0.0
    min_count = expected.get('min_count', 3)
    try:
        doc = Document(result_file_path)
        valid_locations = []
        for para in doc.paragraphs:
            text = para.text.strip()
            if not text or len(text) <= 5:
                continue
            if not re.search('[\\u4e00-\\u9fff]', text):
                continue
            if '医院' not in text:
                continue
            if '福田' not in text:
                continue
            if '深圳' not in text:
                continue
            valid_locations.append(text)
        actual_count = len(valid_locations)
        if actual_count >= min_count:
            return 1.0
        elif actual_count > 0:
            return actual_count / min_count
        else:
            return 0.0
    except Exception as e:
        print(f'Error reading document: {e}')
        return 0.0

def check_default_font_size__bb9f9cd7a1841ce429a56b51c9188ec4(config_file_path, rules):
    """Check the default font size in LibreOffice Writer configuration.

    Args:
        config_file_path: Path to registrymodifications.xcu file
        rules: Dictionary with expected_size_pt (int) key

    Returns:
        float: 1.0 if default font size matches expected, 0.0 otherwise
    """
    default_font_size = None
    expected_size = rules['expected_size_pt']
    if not config_file_path:
        return 0.0
    try:
        tree = ET.parse(config_file_path)
        root = tree.getroot()
        namespace = {'oor': 'http://openoffice.org/2001/registry'}
        for elem in root.findall('.//item[@oor:path="/org.openoffice.Office.Writer/DefaultFont"]', namespace):
            for prop in elem.findall('.//prop[@oor:name="StandardHeight"]', namespace):
                for value in prop.findall('value', namespace):
                    default_font_size = int(value.text) if value.text else None
    except Exception as e:
        logger.error(f'Error parsing config file: {e}')
        return 0.0
    return 1.0 if default_font_size == expected_size else 0.0

def check_docx_page_numbers__a3671ccf(result, expected, **options):
    """
    Check if a DOCX file has page numbers in the footer with correct alignment.

    Args:
        result: Path to the DOCX file
        expected: Dict with keys:
            - has_page_numbers: bool - whether page numbers should exist
            - alignment: str - expected alignment ('left', 'center', 'right')
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
               0.5 for page numbers existing, 0.5 for correct alignment
    """
    try:
        with zipfile.ZipFile(result, 'r') as docx_zip:
            footer_files = [name for name in docx_zip.namelist() if 'footer' in name.lower()]
            if not footer_files:
                if expected.get('has_page_numbers', True):
                    return 0.0
                else:
                    return 1.0
            has_page_num = False
            page_num_alignment = None
            namespaces = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
            for footer_file in footer_files:
                footer_xml = docx_zip.read(footer_file)
                root = etree.fromstring(footer_xml)
                paragraphs = root.xpath('.//w:p', namespaces=namespaces)
                for paragraph in paragraphs:
                    fld_instrs = paragraph.xpath('.//w:instrText/text()', namespaces=namespaces)
                    has_page_in_para = any(('PAGE' in instr.upper() for instr in fld_instrs))
                    if has_page_in_para:
                        has_page_num = True
                        jc_elements = paragraph.xpath('.//w:pPr/w:jc/@w:val', namespaces=namespaces)
                        if jc_elements:
                            alignment_val = jc_elements[0]
                            if alignment_val in ['center', 'both']:
                                page_num_alignment = 'center'
                            elif alignment_val == 'left':
                                page_num_alignment = 'left'
                            elif alignment_val == 'right':
                                page_num_alignment = 'right'
                            else:
                                page_num_alignment = alignment_val
                        else:
                            page_num_alignment = 'left'
                        break
                if has_page_num:
                    break
            if not expected.get('has_page_numbers', True):
                return 0.0 if has_page_num else 1.0
            score = 0.0
            if has_page_num:
                score += 0.5
            else:
                return 0.0
            expected_alignment = expected.get('alignment')
            if expected_alignment:
                if page_num_alignment == expected_alignment:
                    score += 0.5
            else:
                score += 0.5
            return score
    except Exception as e:
        print(f'Error checking page numbers: {e}')
        return 0.0

def check_page_number_color_blue__e7486855(pptx_file, rules):
    """Check if slide page numbers in master slide are formatted in blue color."""
    color = rules.get('color', 'blue')

    def is_blue(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[1:3], 16), int(rgb_str[3:5], 16), int(rgb_str[5:7], 16))
        return b > g + threshold and b > r + threshold

    def is_red(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[1:3], 16), int(rgb_str[3:5], 16), int(rgb_str[5:7], 16))
        return r > g + threshold and r > b + threshold

    def is_green(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[1:3], 16), int(rgb_str[3:5], 16), int(rgb_str[5:7], 16))
        return g > r + threshold and g > b + threshold
    try:
        with zipfile.ZipFile(pptx_file, 'r') as zip_ref:
            slide_master_name = 'ppt/slideMasters/slideMaster1.xml'
            with zip_ref.open(slide_master_name) as slide_master_file:
                tree = ET.parse(slide_master_file)
                root = tree.getroot()
                namespaces = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main', 'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}
                slide_num_placeholders = root.findall('.//p:sp[.//p:ph[@type="sldNum"]]', namespaces)
                if not slide_num_placeholders:
                    slide_num_placeholders = root.findall('.//p:sp[.//p:ph[@type="ftr"]]', namespaces)
                if not slide_num_placeholders:
                    return 0.0
                slides_color_val = None
                for placeholder in slide_num_placeholders:
                    color_elem = placeholder.find('.//a:rPr//a:solidFill//a:srgbClr', namespaces)
                    if color_elem is not None:
                        slides_color_val = color_elem.get('val')
                        break
                    color_elem = placeholder.find('.//a:pPr//a:defRPr//a:solidFill//a:srgbClr', namespaces)
                    if color_elem is not None:
                        slides_color_val = color_elem.get('val')
                        break
                    color_elem = placeholder.find('.//p:txBody//a:solidFill//a:srgbClr', namespaces)
                    if color_elem is not None:
                        slides_color_val = color_elem.get('val')
                        break
        if slides_color_val is None:
            return 0.0
        elif color == 'blue' and (not is_blue(slides_color_val)):
            return 0.0
        elif color == 'red' and (not is_red(slides_color_val)):
            return 0.0
        elif color == 'green' and (not is_green(slides_color_val)):
            return 0.0
        return 1.0
    except Exception as e:
        return 0.0

def check_fixed_font_family__a0c1ef41(result, expected, **options):
    """Check if fixed font family matches expected value.

    Args:
        result: Dict with fixed_font_family from getter
        expected: Expected font name or rules dict
        **options: Additional options

    Returns:
        float: 1.0 if match, 0.0 otherwise
    """
    font_family = result.get('fixed_font_family', '').strip()
    if expected['type'] == 'value':
        expected_font = expected['value'].strip()
        return 1.0 if font_family.lower() == expected_font.lower() else 0.0
    elif expected['type'] == 'list':
        allowed_fonts = [f.strip().lower() for f in expected.get('values', [])]
        return 1.0 if font_family.lower() in allowed_fonts else 0.0
    else:
        raise TypeError(f"{expected['type']} not supported yet!")

def check_spacing_para_task__4559b4c9(docx_file, expected, **options):
    """Check line spacing for three paragraphs.

    This function verifies that each paragraph has the expected line spacing.
    Expected spacing values: para0=1.0, para1=1.5, para2=2.0

    Args:
        docx_file: Path to the docx file
        expected: Dict with para0, para1, para2 spacing values
        **options: Additional options (tolerance for floating point comparison)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    if len(doc.paragraphs) < 3:
        logger.error(f'Document has {len(doc.paragraphs)} paragraphs, expected at least 3')
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    expected_para0 = expected.get('para0', 1.0)
    expected_para1 = expected.get('para1', 1.5)
    expected_para2 = expected.get('para2', 2.0)
    spacing0 = doc.paragraphs[0].paragraph_format.line_spacing
    spacing1 = doc.paragraphs[1].paragraph_format.line_spacing
    spacing2 = doc.paragraphs[2].paragraph_format.line_spacing
    spacing0 = spacing0 if spacing0 is not None else 1.0
    spacing1 = spacing1 if spacing1 is not None else 1.0
    spacing2 = spacing2 if spacing2 is not None else 1.0
    logger.info(f'Paragraph 0 spacing: {spacing0} (expected: {expected_para0})')
    logger.info(f'Paragraph 1 spacing: {spacing1} (expected: {expected_para1})')
    logger.info(f'Paragraph 2 spacing: {spacing2} (expected: {expected_para2})')
    score = 0.0
    if abs(spacing0 - expected_para0) <= tolerance:
        score += 0.33
    if abs(spacing1 - expected_para1) <= tolerance:
        score += 0.34
    if abs(spacing2 - expected_para2) <= tolerance:
        score += 0.33
    return round(score, 2)

def check_docx_two_cols__92cd8bde(docx_file, expected, **options):
    """Check if docx table has exactly two columns with expected data."""
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
        tables = doc.tables
        if len(tables) == 0:
            return 0.0
        table = tables[0]
        if len(table.columns) != 2:
            return 0.0
        col1_header = expected.get('col1_header', '')
        col2_header = expected.get('col2_header', '')
        if len(table.rows) > 0:
            if table.cell(0, 0).text.strip() != col1_header:
                return 0.0
            if table.cell(0, 1).text.strip() != col2_header:
                return 0.0
        sample_row_idx = expected.get('sample_row_idx', 1)
        sample_col1_val = expected.get('sample_col1_val', None)
        sample_col2_val = expected.get('sample_col2_val', None)
        if len(table.rows) > sample_row_idx:
            if sample_col1_val is not None:
                cell_text = table.cell(sample_row_idx, 0).text.strip()
                try:
                    cell_val = float(cell_text)
                    if abs(cell_val - sample_col1_val) > 0.1:
                        return 0.0
                except:
                    return 0.0
            if sample_col2_val is not None:
                cell_text = table.cell(sample_row_idx, 1).text.strip()
                try:
                    cell_val = float(cell_text)
                    if abs(cell_val - sample_col2_val) > 0.1:
                        return 0.0
                except:
                    return 0.0
        return 1.0
    except Exception as e:
        print(f'Error in check_docx_two_cols__92cd8bde: {e}')
        return 0.0

def check_writer_text_font_size__2e74dc9f0cceb87379ab69e99e2704f7(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if all target text occurrences have the expected font size.

    Args:
        result: Dict from getter with 'font_sizes' list
        expected: Dict with expected 'size_pt' value
        **options: Additional options (unused)

    Returns:
        float: Proportion of occurrences with the expected size (0.0 to 1.0)
               Returns 1.0 only if ALL occurrences have the expected size
    """
    try:
        font_sizes = result.get('font_sizes', [])
        expected_size = expected.get('size_pt')
        if not font_sizes:
            logger.warning('No font sizes found in result')
            return 0.0
        if expected_size is None:
            logger.warning('No expected font size specified')
            return 0.0
        tolerance = 0.1
        total_count = len(font_sizes)
        matching_count = 0
        for item in font_sizes:
            actual_size = item.get('size_pt')
            if actual_size is not None and abs(actual_size - expected_size) < tolerance:
                matching_count += 1
                logger.info(f"Font size matches: {actual_size}pt for text '{item.get('text', '')[:30]}'")
            else:
                logger.warning(f"Font size mismatch: expected={expected_size}pt, got={actual_size}pt for text '{item.get('text', '')[:30]}'")
        score = matching_count / total_count
        if score == 1.0:
            logger.info(f'All {total_count} occurrences have correct font size {expected_size}pt')
        else:
            logger.warning(f'Only {matching_count}/{total_count} occurrences have correct font size')
        return score
    except Exception as e:
        logger.error(f'Error checking font size: {e}')
        return 0.0

def check_para_bold_italic__8a56b827(result, expected, **options):
    """Check if all text in a specific paragraph is both bold and italic.

    Args:
        result: Path to the docx file
        expected: Dict with 'para_index', 'must_be_bold', 'must_be_italic'
        **options: Additional options

    Returns:
        float: Partial credit score (0.0 to 1.0)
    """
    if not result:
        return 0.0
    try:
        doc = Document(result)
    except Exception as e:
        logger.error(f'Error opening document: {e}')
        return 0.0
    para_index = expected.get('para_index', 2)
    must_be_bold = expected.get('must_be_bold', True)
    must_be_italic = expected.get('must_be_italic', True)
    if para_index >= len(doc.paragraphs):
        logger.error(f'Paragraph index {para_index} out of range')
        return 0.0
    para = doc.paragraphs[para_index]
    if not para.runs:
        logger.error(f'Paragraph {para_index} has no runs')
        return 0.0
    all_bold = True
    all_italic = True
    for run in para.runs:
        if run.text.strip():
            if must_be_bold and (not run.bold):
                all_bold = False
            if must_be_italic and (not run.italic):
                all_italic = False
    score = 0.0
    if all_bold:
        score += 0.5
        logger.info(f'Paragraph {para_index} has all text bold')
    if all_italic:
        score += 0.5
        logger.info(f'Paragraph {para_index} has all text italic')
    logger.info(f'Paragraph {para_index} bold+italic score: {score}')
    return score

def check_docx_contains__c0dbd7508ef71f2573df14afb37d7549(result: str, expected: Any, **options) -> float:
    """Check if the docx content contains the expected text.

    Args:
        result: Text content from the docx file
        expected: Dictionary with 'expected_text' key containing the text to find
        **options: Additional options (e.g., case_sensitive)

    Returns:
        float: 1.0 if expected text is found, 0.0 otherwise
    """
    if not isinstance(result, str):
        return 0.0
    expected_text = expected.get('expected_text', '')
    if not expected_text:
        return 0.0
    case_sensitive = options.get('case_sensitive', False)
    if case_sensitive:
        return 1.0 if expected_text in result else 0.0
    else:
        return 1.0 if expected_text.lower() in result.lower() else 0.0

