def check_docx_bold__1e11b8812f21045043113b8b0bfd681f(result, expected, **options):
    """Check if specified paragraphs have bold formatting.

    Args:
        result: dict mapping paragraph indices to bold status
        expected: dict with 'para_bold' key containing dict of {para_num: True/False}
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    para_bold = expected.get('para_bold', {})
    if not para_bold:
        return 0.0
    correct = 0
    total = len(para_bold)
    for (para_num, expected_bold) in para_bold.items():
        para_num_int = int(para_num)
        actual_bold = result.get(para_num_int, False)
        if actual_bold == expected_bold:
            correct += 1
    return correct / total if total > 0 else 0.0

def check_docx_keywords__d373d25e(result_file_path, rules):
    """
    Check if a DOCX file contains required keywords.
    
    Args:
        result_file_path: Path to the DOCX file to check
        rules: Dict with 'keywords' (list of required keywords) and 'min_matches' (minimum number of keywords to find)
        
    Returns:
        float: 1.0 if min_matches keywords are found, 0.0 otherwise
    """
    if result_file_path is None:
        return 0.0
    keywords = rules.get('keywords', [])
    min_matches = rules.get('min_matches', len(keywords))
    doc = Document(result_file_path)
    full_text = []
    for para in doc.paragraphs:
        full_text.append(para.text)
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                full_text.append(cell.text)
    document_text = ' '.join(full_text)
    matches = 0
    for keyword in keywords:
        if keyword in document_text:
            matches += 1
    if matches >= min_matches:
        return 1.0
    else:
        return 0.0

def check_page_numbers_in_header__8c815f1b(docx_file, expected):
    """Check if the document has page numbers in the header.

    Args:
        docx_file: Path to the docx file
        expected: Expected value (not used, checks for page numbers in header)

    Returns:
        float: 1.0 if page numbers are in header, 0.0 otherwise
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    for section in doc.sections:
        header = section.header
        if header is None:
            return 0.0
        header_text = header.paragraphs[0].text if header.paragraphs else ''
        if not any((char.isdigit() for char in header_text)):
            return 0.0
    return 1.0

