def check_ages_and_highlight__599223fb612f6c3c3362c3de00669490(result, expected, **options):
    """Check if ages are calculated for all employees and oldest row is highlighted.

    Args:
        result: Dict from getter with:
            - ages: List of tuples (row_num, age_value, birthday, expected_age)
            - highlighted_row: Row number that is highlighted
            - highlighted_color: Color code of the highlighted row
            - max_age_row: Row number with maximum age
        expected: Dict with 'row' indicating expected row to be highlighted
                  and optionally 'color' for expected highlight color
        **options: Additional options (e.g., strict_color_match)

    Returns:
        float: Score from 0.0 to 1.0
            - 1.0: All ages calculated correctly AND correct row highlighted in correct color
            - 0.8: All ages calculated correctly AND correct row highlighted (any color)
            - 0.6: Most ages calculated correctly but not all
            - 0.4: Ages calculated but not verified as correct
            - 0.2: Some ages calculated but not enough
            - 0.0: No ages calculated or major issues
    """
    if not result or not isinstance(result, dict):
        return 0.0
    ages = result.get('ages', [])
    highlighted_row = result.get('highlighted_row')
    highlighted_color = result.get('highlighted_color')
    max_age_row = result.get('max_age_row')
    expected_row = expected.get('row')
    expected_color = expected.get('color')
    strict_color_match = options.get('strict_color_match', False)
    min_employees = 3
    full_coverage_threshold = 8
    if len(ages) < min_employees:
        return 0.0
    score = 0.2
    correct_age_count = 0
    total_verifiable_ages = 0
    for (row_num, age, birthday, expected_age) in ages:
        if expected_age is not None:
            total_verifiable_ages += 1
            if abs(age - expected_age) <= 1:
                correct_age_count += 1
    if total_verifiable_ages > 0:
        age_accuracy = correct_age_count / total_verifiable_ages
        if age_accuracy < 0.7:
            return 0.2
        elif age_accuracy >= 0.9:
            score = 0.4
        else:
            score = 0.3
    if len(ages) >= full_coverage_threshold:
        score = 0.6
    if max_age_row and highlighted_row:
        if max_age_row == highlighted_row:
            score = 0.8
            if strict_color_match and expected_color and highlighted_color:
                norm_highlighted = highlighted_color.upper()
                norm_expected = expected_color.upper()
                if norm_highlighted == norm_expected:
                    score = 1.0
                else:
                    score = 0.8
            elif expected_color and highlighted_color:
                norm_highlighted = highlighted_color.upper()
                norm_expected = expected_color.upper()
                if norm_highlighted == norm_expected:
                    score = 1.0
        else:
            score = max(score, 0.6)
    elif max_age_row and expected_row:
        if max_age_row == expected_row:
            if highlighted_row == expected_row:
                score = 0.8
                if expected_color and highlighted_color:
                    norm_highlighted = highlighted_color.upper()
                    norm_expected = expected_color.upper()
                    if norm_highlighted == norm_expected:
                        score = 1.0
            else:
                score = max(score, 0.6)
    return score

