def check_python_hyperparams__abfaa466(result_file, expected, **options):
    """
    Check if a Python file contains required hyperparameter variable assignments.

    Args:
        result_file: Path to the Python file to check
        expected: Dict with 'required_vars' and 'min_vars' keys
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 based on partial credit
    """
    if not result_file:
        return 0.0
    try:
        with open(result_file, 'r', encoding='utf-8') as f:
            content = f.read()
    except Exception as e:
        print(f'Error reading file: {e}')
        return 0.0
    required_vars = expected.get('required_vars', [])
    min_vars = expected.get('min_vars', len(required_vars))
    if not required_vars:
        return 0.0
    found_vars = set()
    try:
        tree = ast.parse(content)
        for node in ast.walk(tree):
            if isinstance(node, ast.Assign):
                for target in node.targets:
                    if isinstance(target, ast.Name):
                        found_vars.add(target.id)
            elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
                found_vars.add(node.target.id)
    except SyntaxError as e:
        print(f'Syntax error parsing file: {e}')
        return 0.0
    found_count = sum((1 for var in required_vars if var in found_vars))
    if found_count >= min_vars:
        score = found_count / len(required_vars)
    else:
        score = found_count / len(required_vars) * 0.5
    return score

