def check_docx_paragraph_count__dc060780(result_state: Optional[List[str]], expected_state: Dict[str, Any], **options) -> float:
    """
    Check if exactly 2 new paragraphs were added at the end of the document.

    Args:
        result_state: List of paragraph texts from getter (None if there was an error)
        expected_state: Dict containing 'original_paragraphs' (list of original paragraph texts)
                       and 'added_paragraphs' (number of paragraphs to add)
        **options: Additional options (not used)

    Returns:
        float: 1.0 if all original paragraphs exist in same positions AND exactly 2 new
               non-empty paragraphs are added at the end, 0.0 otherwise
    """
    if result_state is None:
        return 0.0
    original_paragraphs = expected_state.get('original_paragraphs', [])
    added_count = expected_state.get('added_paragraphs', 2)
    expected_total = len(original_paragraphs) + added_count
    if len(result_state) != expected_total:
        return 0.0
    for (i, original_para) in enumerate(original_paragraphs):
        if i >= len(result_state):
            return 0.0
        if result_state[i] != original_para:
            return 0.0
    if len(result_state) < len(original_paragraphs) + added_count:
        return 0.0
    return 1.0

