def check_docx_formatted_words__84063579(result_file, expected, **options):
    """
    Check if words with 5+ letters have dark red color formatting.

    This function uses a run-level approach to handle LibreOffice Writer's
    formatting model where formatting is applied to runs (contiguous text segments),
    not individual words.

    Strategy:
    1. For each run, extract all words
    2. Determine if the run SHOULD be dark red based on its word content:
       - If ALL words in the run are 5+ letters: MUST be dark red
       - If NO words in the run are 5+ letters: MUST NOT be dark red
       - If MIXED (some 5+, some <5): Accept any formatting (user may format at run level)
    3. Verify the run's actual formatting matches expectations

    Args:
        result_file: Path to the result .docx file
        expected: Expected value (not used, filter is in code)
        **options: Additional options

    Returns:
        float: 1.0 if formatting is correct, 0.0 otherwise
    """
    if not result_file:
        return 0.0
    try:
        doc = Document(result_file)
    except Exception:
        return 0.0
    expected_rgb = (139, 0, 0)
    COLOR_TOLERANCE = 15
    total_long_words = 0
    correctly_formatted_runs = 0
    total_runs_with_long_words = 0

    def is_dark_red(run):
        """Check if a run has dark red color formatting"""
        if not run.font.color or not run.font.color.rgb:
            return False
        try:
            actual_rgb = (run.font.color.rgb[0], run.font.color.rgb[1], run.font.color.rgb[2])
            return all((abs(actual_rgb[i] - expected_rgb[i]) <= COLOR_TOLERANCE for i in range(3)))
        except:
            return False

    def check_runs(runs):
        """Check formatting of runs based on their word content"""
        nonlocal total_long_words, correctly_formatted_runs, total_runs_with_long_words
        for run in runs:
            text = run.text
            if not text.strip():
                continue
            words = re.findall('\\b\\w+\\b', text)
            if not words:
                continue
            long_words = [w for w in words if len(w) >= 5]
            short_words = [w for w in words if len(w) < 5]
            total_long_words += len(long_words)
            has_long_words = len(long_words) > 0
            has_short_words = len(short_words) > 0
            run_is_dark_red = is_dark_red(run)
            if has_long_words and (not has_short_words):
                total_runs_with_long_words += 1
                if not run_is_dark_red:
                    return False
                correctly_formatted_runs += 1
            elif has_short_words and (not has_long_words):
                if run_is_dark_red:
                    return False
            elif has_long_words and has_short_words:
                total_runs_with_long_words += 1
                if run_is_dark_red:
                    correctly_formatted_runs += 1
        return True
    for paragraph in doc.paragraphs:
        if not check_runs(paragraph.runs):
            return 0.0
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    if not check_runs(paragraph.runs):
                        return 0.0
    if total_long_words == 0:
        return 0.0
    if total_runs_with_long_words > 0 and correctly_formatted_runs == 0:
        return 0.0
    if total_runs_with_long_words > 0:
        format_ratio = correctly_formatted_runs / total_runs_with_long_words
        if format_ratio < 0.5:
            return 0.0
    return 1.0

