def check_italic_four_letters__a46a1ebc95419808bbd66e4ed9c5acac(result, expected, **options):
    """
    Check if 4-letter words are italicized.

    Args:
        result: File path to the DOCX file
        expected: Rules dict with 'word_length' key
        **options: Additional options

    Returns:
        float: 1.0 if all 4-letter words are italic, 0.0 otherwise
    """
    if not result:
        return 0.0
    word_length = expected.get('word_length', 4)
    try:
        document = Document(result)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    for table in document.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    for run in paragraph.runs:
                        words = run.text.split()
                        for word in words:
                            word_stripped = word.strip('.,;:!?"\'')
                            if word_stripped:
                                if len(word_stripped) == word_length:
                                    if not run.font.italic:
                                        logger.info(f"Word '{word_stripped}' (4 letters) should be italic but is not")
                                        return 0.0
                                elif run.font.italic:
                                    logger.info(f"Word '{word_stripped}' ({len(word_stripped)} letters) should not be italic but is")
                                    return 0.0
    return 1.0

