def check_paragraph_line_spacing__52445c32(docx_file, expected, **options):
    """Check if a specific paragraph has the expected line spacing.

    Args:
        docx_file: Path to the DOCX file
        expected: Expected state (dict with 'paragraph_index' and 'line_spacing')
        **options: Additional options

    Returns:
        float: 1.0 if paragraph has expected line spacing, 0.0 otherwise
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    para_index = expected.get('paragraph_index', 0)
    expected_spacing = expected.get('line_spacing', 1.5)
    if para_index >= len(doc.paragraphs):
        logger.error(f'Paragraph index {para_index} out of range (document has {len(doc.paragraphs)} paragraphs)')
        return 0.0
    target_para = doc.paragraphs[para_index]
    actual_spacing = target_para.paragraph_format.line_spacing
    if actual_spacing is None:
        logger.info(f'Line spacing is None (default)')
        return 0.0
    tolerance = 0.05
    if abs(actual_spacing - expected_spacing) <= tolerance:
        return 1.0
    else:
        logger.info(f'Line spacing mismatch: expected {expected_spacing}, got {actual_spacing}')
        return 0.0

