def check_docx_text_formatting__4d81853918ea4e13075a40ffbba4308e(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if text content matches expected responses and formatting is correct.

    Verifies:
    1. Correct number of non-empty paragraphs (GEMINI responses)
    2. Blank line separators between paragraphs
    3. Exact count of target word occurrences
    4. All target words are bold AND underlined
    5. Content verification: paragraphs match source GEMINI responses

    Args:
        result: Dictionary from getter with paragraphs data and source_gemini_responses
        expected: Expected rules (num_responses, target_word, target_word_count, verify_content)
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0 (partial credit for each requirement)
    """
    paragraphs = result.get('paragraphs', [])
    source_gemini_responses = result.get('source_gemini_responses', [])
    expected_num_responses = expected.get('num_responses', 6)
    target_word = expected.get('target_word', 'Trojan War')
    expected_target_count = expected.get('target_word_count', 1)
    verify_content = expected.get('verify_content', True)
    scores = {'paragraph_count': 0.0, 'blank_separators': 0.0, 'target_word_count': 0.0, 'target_word_formatting': 0.0, 'content_match': 0.0}
    non_empty_paragraphs = [p for p in paragraphs if p.get('text', '').strip()]
    if len(non_empty_paragraphs) == expected_num_responses:
        scores['paragraph_count'] = 0.2
    if len(non_empty_paragraphs) == expected_num_responses:
        expected_separator_count = expected_num_responses - 1
        has_correct_separators = True
        non_empty_indices = [i for (i, p) in enumerate(paragraphs) if p.get('text', '').strip()]
        for i in range(len(non_empty_indices) - 1):
            current_idx = non_empty_indices[i]
            next_idx = non_empty_indices[i + 1]
            if next_idx - current_idx != 2:
                has_correct_separators = False
                break
        if has_correct_separators and len(non_empty_indices) == expected_num_responses:
            scores['blank_separators'] = 0.2
    total_target_words = 0
    correctly_formatted = 0
    for para in paragraphs:
        runs = para.get('runs', [])
        for run_info in runs:
            run_text = run_info.get('text', '')
            if target_word in run_text:
                target_count_in_run = run_text.count(target_word)
                total_target_words += target_count_in_run
                is_bold = run_info.get('bold', False)
                is_underline = run_info.get('underline', False)
                if is_bold and is_underline:
                    correctly_formatted += target_count_in_run
    if total_target_words == expected_target_count:
        scores['target_word_count'] = 0.2
    if total_target_words > 0 and correctly_formatted == total_target_words:
        scores['target_word_formatting'] = 0.2
    if verify_content and source_gemini_responses:
        if len(source_gemini_responses) >= expected_num_responses:
            matched_count = 0
            non_empty_texts = [p.get('text', '').strip() for p in non_empty_paragraphs]
            for para_text in non_empty_texts:
                best_match_ratio = 0.0
                for source_response in source_gemini_responses:
                    normalized_para = ' '.join(para_text.split())
                    normalized_source = ' '.join(source_response.split())
                    ratio = difflib.SequenceMatcher(None, normalized_para, normalized_source).ratio()
                    if ratio > best_match_ratio:
                        best_match_ratio = ratio
                if best_match_ratio >= 0.85:
                    matched_count += 1
            if matched_count == len(non_empty_texts) and len(non_empty_texts) == expected_num_responses:
                scores['content_match'] = 0.2
            elif matched_count > 0:
                scores['content_match'] = 0.2 * (matched_count / expected_num_responses)
    elif not verify_content or not source_gemini_responses:
        scores['content_match'] = 0.2
    final_score = sum(scores.values())
    return final_score

