def check_docx_locations__481b10e530aee0667a7fe9244cf18718(result_file_path, expected, **options):
    """
    Check if the Word document contains at least 5 locations from the expected list.
    Uses fuzzy matching to handle minor variations in location names.

    Args:
        result_file_path: Path to the .docx file
        expected: Dict with 'locations' key containing list of expected location names
        **options: Additional options (e.g., threshold for fuzzy matching)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result_file_path is None:
        return 0.0
    expected_locations = expected.get('locations', [])
    min_count = expected.get('min_count', 5)
    fuzzy_threshold = options.get('fuzzy_threshold', 80)
    if not expected_locations:
        return 0.0
    try:
        doc = Document(result_file_path)
    except Exception:
        return 0.0
    doc_text = []
    for para in doc.paragraphs:
        if para.text.strip():
            doc_text.append(para.text.strip())
    full_text = '\n'.join(doc_text)
    found_count = 0
    for location in expected_locations:
        found = False
        for para_text in doc_text:
            score = fuzz.partial_ratio(location, para_text)
            if score >= fuzzy_threshold:
                found = True
                break
        if found:
            found_count += 1
    if found_count >= min_count:
        return 1.0
    else:
        return found_count / min_count

def check_spacing_para_task__fb2054ce(docx_file, expected, **options):
    """Check line spacing for three paragraphs.

    This function verifies that each paragraph has the expected line spacing.
    Expected spacing values: para0=1.5, para1=2.0, para2=1.0

    Args:
        docx_file: Path to the docx file
        expected: Dict with para0, para1, para2 spacing values
        **options: Additional options (tolerance for floating point comparison)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    if len(doc.paragraphs) < 3:
        logger.error(f'Document has {len(doc.paragraphs)} paragraphs, expected at least 3')
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    expected_para0 = expected.get('para0', 1.5)
    expected_para1 = expected.get('para1', 2.0)
    expected_para2 = expected.get('para2', 1.0)
    spacing0 = doc.paragraphs[0].paragraph_format.line_spacing
    spacing1 = doc.paragraphs[1].paragraph_format.line_spacing
    spacing2 = doc.paragraphs[2].paragraph_format.line_spacing
    spacing0 = spacing0 if spacing0 is not None else 1.0
    spacing1 = spacing1 if spacing1 is not None else 1.0
    spacing2 = spacing2 if spacing2 is not None else 1.0
    logger.info(f'Paragraph 0 spacing: {spacing0} (expected: {expected_para0})')
    logger.info(f'Paragraph 1 spacing: {spacing1} (expected: {expected_para1})')
    logger.info(f'Paragraph 2 spacing: {spacing2} (expected: {expected_para2})')
    score = 0.0
    if abs(spacing0 - expected_para0) <= tolerance:
        score += 0.33
    if abs(spacing1 - expected_para1) <= tolerance:
        score += 0.34
    if abs(spacing2 - expected_para2) <= tolerance:
        score += 0.33
    return round(score, 2)

