def check_docx_table_cols__5521faef(docx_file, expected, **options):
    """Check if docx table has expected columns."""
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
        tables = doc.tables
        if len(tables) == 0:
            return 0.0
        table = tables[0]
        expected_col_count = expected.get('expected_col_count', 0)
        if len(table.columns) != expected_col_count:
            return 0.0
        header_row = expected.get('header_row', [])
        if header_row and len(table.rows) > 0:
            for (col_idx, expected_val) in enumerate(header_row):
                if col_idx >= len(table.columns):
                    return 0.0
                cell_text = table.cell(0, col_idx).text.strip()
                expected_str = str(expected_val) if expected_val is not None else ''
                if cell_text != expected_str:
                    return 0.0
        sample_row_idx = expected.get('sample_row_idx', 1)
        sample_row_data = expected.get('sample_row_data', [])
        if sample_row_data and len(table.rows) > sample_row_idx:
            for (col_idx, expected_val) in enumerate(sample_row_data):
                if col_idx >= len(table.columns):
                    return 0.0
                cell_text = table.cell(sample_row_idx, col_idx).text.strip()
                if isinstance(expected_val, (int, float)):
                    try:
                        cell_val = float(cell_text)
                        if abs(cell_val - expected_val) > 0.1:
                            return 0.0
                    except:
                        return 0.0
                else:
                    expected_str = str(expected_val) if expected_val is not None else ''
                    if cell_text != expected_str:
                        return 0.0
        return 1.0
    except Exception as e:
        print(f'Error in check_docx_table_cols__5521faef: {e}')
        return 0.0

