def check_docx_exists__900f226e(result, expected, **options):
    """Check if file exists and contains kernel-related content.

    Args:
        result: Dict with 'exists', 'size', 'has_kernel_content' from getter
        expected: Dict with 'should_exist' and 'min_size' requirements
        **options: Additional options

    Returns:
        float: Score 1.0 if all checks pass, 0.0 otherwise
    """
    if not result:
        logger.info('✗ No result from getter')
        return 0.0
    should_exist = expected.get('should_exist', True)
    min_size = expected.get('min_size', 100)
    if result.get('exists') != should_exist:
        logger.info(f'✗ File existence does not match expectation (expected: {should_exist})')
        return 0.0
    if not should_exist:
        logger.info('✓ File correctly does not exist')
        return 1.0
    file_size = result.get('size', 0)
    if file_size < min_size:
        logger.info(f'✗ File size too small: {file_size} bytes (minimum: {min_size} bytes)')
        return 0.0
    has_kernel_content = result.get('has_kernel_content', False)
    if not has_kernel_content:
        logger.info('✗ File does not contain kernel-related content')
        return 0.0
    word_count = result.get('word_count', 0)
    if word_count < 5:
        logger.info(f'✗ File has too few words: {word_count}')
        return 0.0
    logger.info(f'✓ File exists with size {file_size} bytes, {word_count} words, and kernel-related content')
    return 1.0

def check_docx_image_count__2ceb2e40a4dbc2ef362c792411e6262a(result, expected, **options):
    """
    Check if DOCX file contains the exact number of images required.

    Args:
        result: Dict from getter with file_exists and image_count
        expected: Dict with has_image and exact_count requirements
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
