def check_docx_header_and_image__ac4750c6(result, expected, **options):
    """
    Check if DOCX contains header text and an image.

    Args:
        result: Path to the DOCX file
        expected: Dict with rules specifying header_text and has_image
        **options: Additional options

    Returns:
        float: Score (0.5 for header, 0.5 for image, 1.0 for both)
    """
    if not result:
        logger.error('Result file path is None')
        return 0.0
    expected_header = expected.get('header_text', '')
    expected_has_image = expected.get('has_image', True)
    try:
        doc = Document(result)
    except Exception as e:
        logger.error(f'Error loading DOCX file: {e}')
        return 0.0
    score = 0.0
    header_found = False
    for section in doc.sections:
        header = section.header
        if header:
            for para in header.paragraphs:
                if expected_header.lower() in para.text.lower():
                    header_found = True
                    score += 0.5
                    logger.info(f"Header check passed: found '{expected_header}'")
                    break
        if header_found:
            break
    if not header_found:
        logger.error(f"Header not found: expected '{expected_header}'")
    has_image = False
    for rel in doc.part.rels.values():
        if 'image' in rel.reltype:
            has_image = True
            break
    if has_image == expected_has_image:
        score += 0.5
        logger.info(f'Image presence check passed: {has_image}')
    else:
        logger.error(f'Image presence mismatch: expected {expected_has_image}, got {has_image}')
    logger.info(f'Final score: {score}')
    return score

