def check_docx_word_count_range__78c2239d(result: Dict[str, Any], expected: Any, env=None, **options) -> float:
    """
    Check if word count is in expected range AND content matches source PPTX.

    Args:
        result: Dict with 'word_count', 'text', 'path' from getter
        expected: Dict with 'min_words', 'max_words', and 'source_pptx_path' keys
        env: DesktopEnv instance (needed to read source PPTX)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict):
        logger.error(f'Result should be a dict, got {type(result)}')
        return 0.0
    if not isinstance(expected, dict):
        logger.error(f'Expected should be a dict, got {type(expected)}')
        return 0.0
    word_count = result.get('word_count', 0)
    docx_text = result.get('text', '')
    min_words = expected.get('min_words', 0)
    max_words = expected.get('max_words', float('inf'))
    source_pptx_path = expected.get('source_pptx_path', '')
    logger.info(f'Word count: {word_count}, expected range: {min_words}-{max_words}')
    if not min_words <= word_count <= max_words:
        logger.warning(f'Word count {word_count} not in range [{min_words}, {max_words}]')
        return 0.0
    if env and source_pptx_path:
        pptx_text = _extract_pptx_text(env, source_pptx_path)
        if not pptx_text:
            logger.warning('Could not extract text from source PPTX, skipping content check')
            return 1.0 if min_words <= word_count <= max_words else 0.0
        if not docx_text:
            logger.warning('DOCX text is empty')
            return 0.0
        sequence_similarity = _calculate_text_similarity(pptx_text, docx_text)
        jaccard_similarity = _calculate_jaccard_similarity(pptx_text, docx_text)
        logger.info(f'Sequence similarity: {sequence_similarity:.3f}')
        logger.info(f'Jaccard similarity: {jaccard_similarity:.3f}')
        content_score = sequence_similarity * 0.6 + jaccard_similarity * 0.4
        logger.info(f'Combined content score: {content_score:.3f}')
        if content_score < 0.75:
            logger.warning(f'Content similarity {content_score:.3f} below threshold 0.75')
            return 0.0
        return 1.0
    else:
        logger.warning('Environment not provided, using word count check only')
        return 1.0 if min_words <= word_count <= max_words else 0.0

def check_docx_office_apps_table__f06c6ff6344501bcedf4d007c342b6fd(result: Optional[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """Check if DOCX contains a table with LibreOffice application performance metrics for GPT-4.

    This metric verifies:
    1. Table exists in the "Main Results" section
    2. Table mentions GPT-4 (confirms data is for GPT-4)
    3. Table contains all three LibreOffice apps (Calc, Impress, Writer) as distinct words
    4. Table has numeric performance metrics (actual data, not just app names)

    Args:
        result: Data from get_docx_table_content getter with section information
        expected: Expected table structure from rules dict with:
            - office_apps: list of office app names to check for ['calc', 'impress', 'writer']
            - min_apps: minimum number of apps to find (not used - all required)
        **options: Additional options (not used)

    Returns:
        float: Score 1.0 if all requirements met, 0.0 otherwise
    """
    if not result or not isinstance(result, dict):
        logger.error('Invalid result data')
        return 0.0
    num_tables = result.get('num_tables', 0)
    if num_tables == 0:
        logger.info('No tables found in document')
        return 0.0
    tables = result.get('tables', [])
    if not tables:
        logger.error('Tables list is empty')
        return 0.0
    office_apps = expected.get('office_apps', ['calc', 'impress', 'writer'])
    logger.info(f"Found {num_tables} table(s) in document. Looking for table in 'Main Results' section with GPT-4 data...")
    for (table_idx, table) in enumerate(tables):
        section = table.get('section', '').lower()
        preceding_heading = table.get('preceding_heading', '').lower()
        data = table.get('data', [])
        if len(data) < 1:
            logger.info(f'Table {table_idx}: Skipping - no data')
            continue
        is_in_main_results = 'main results' in section or 'main results' in preceding_heading
        if not is_in_main_results:
            logger.info(f"Table {table_idx}: Not in 'Main Results' section (section='{table.get('section', '')}', heading='{table.get('preceding_heading', '')}')")
            continue
        logger.info(f"Table {table_idx}: ✓ Found in 'Main Results' section")
        table_text = ' '.join([' '.join(row) for row in data])
        table_text_lower = table_text.lower()
        has_gpt4 = bool(re.search('\\bgpt-?4\\b', table_text_lower))
        if not has_gpt4:
            logger.info(f'Table {table_idx}: Missing GPT-4 reference')
            continue
        logger.info(f'Table {table_idx}: ✓ Contains GPT-4 reference')
        found_apps = []
        for app in office_apps:
            pattern = '\\b' + re.escape(app) + '\\b'
            if re.search(pattern, table_text_lower):
                found_apps.append(app)
                logger.info(f"Table {table_idx}: ✓ Found '{app}' as distinct word")
            else:
                logger.info(f"Table {table_idx}: Missing '{app}' as distinct word")
        if len(found_apps) < len(office_apps):
            logger.info(f'Table {table_idx}: Only found {len(found_apps)}/{len(office_apps)} office apps')
            continue
        logger.info(f'Table {table_idx}: ✓ All {len(office_apps)} office apps found')
        has_numeric_data = _contains_numeric_metrics(data)
        if not has_numeric_data:
            logger.info(f'Table {table_idx}: Missing numeric performance metrics')
            continue
        logger.info(f'Table {table_idx}: ✓ Contains numeric performance metrics')
        logger.info(f'Table {table_idx}: ✓✓✓ ALL requirements satisfied - Full score!')
        return 1.0
    logger.info('No table found that meets all requirements (Main Results section + GPT-4 + all apps + numeric metrics)')
    return 0.0

def check_default_page_margins__8e756232531faf04f5b1ea51c481d270(config_file_path, rules):
    """Check the default page margins in LibreOffice Writer configuration.

    Args:
        config_file_path: Path to registrymodifications.xcu file
        rules: Dictionary with margin_mm (int) key for all-sides margin in millimeters

    Returns:
        float: 1.0 if all margins match expected value, 0.0 otherwise
    """
    expected_margin = rules['margin_mm']
    if not config_file_path:
        return 0.0
    try:
        tree = ET.parse(config_file_path)
        root = tree.getroot()
        namespace = {'oor': 'http://openoffice.org/2001/registry'}
        margins = {}
        for elem in root.findall('.//item', namespace):
            path_attr = elem.get('{http://openoffice.org/2001/registry}path', '')
            if 'StandardPageStyle' in path_attr:
                for prop in elem.findall('.//prop', namespace):
                    prop_name = prop.get('{http://openoffice.org/2001/registry}name', '')
                    for value in prop.findall('value', namespace):
                        if value.text:
                            if prop_name == 'LeftMargin':
                                margins['Left'] = int(value.text)
                            elif prop_name == 'RightMargin':
                                margins['Right'] = int(value.text)
                            elif prop_name == 'TopMargin':
                                margins['Top'] = int(value.text)
                            elif prop_name == 'BottomMargin':
                                margins['Bottom'] = int(value.text)
        if len(margins) == 4 and all((m == expected_margin for m in margins.values())):
            return 1.0
    except Exception as e:
        logger.error(f'Error parsing config file: {e}')
    return 0.0

def check_docx_footnote__38cbe154(result, expected, **options):
    """
    Check if a DOCX file contains footnotes attached to the title with specific content.

    Args:
        result: Path to the DOCX file
        expected: Dict with keys:
            - has_footnote: bool - whether footnote should exist
            - footnote_contains: str - primary keyword that should be in footnote
            - additional_keywords: list - additional keywords that should be present
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        doc = Document(result)
        with zipfile.ZipFile(result, 'r') as docx_zip:
            try:
                footnotes_xml = docx_zip.read('word/footnotes.xml')
            except KeyError:
                if expected.get('has_footnote', True):
                    return 0.0
                else:
                    return 1.0
            footnotes_root = etree.fromstring(footnotes_xml)
            document_xml = docx_zip.read('word/document.xml')
            doc_root = etree.fromstring(document_xml)
            namespaces = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
            title_paragraphs = doc_root.xpath('.//w:body/w:p', namespaces=namespaces)[:3]
            title_has_footnote = False
            footnote_ids_in_title = []
            for para in title_paragraphs:
                footnote_refs = para.xpath('.//w:footnoteReference/@w:id', namespaces=namespaces)
                if footnote_refs:
                    title_has_footnote = True
                    footnote_ids_in_title.extend(footnote_refs)
            if not expected.get('has_footnote', True):
                return 0.0 if title_has_footnote else 1.0
            if not title_has_footnote:
                return 0.0
            title_footnote_texts = []
            for footnote_id in footnote_ids_in_title:
                footnote_elem = footnotes_root.xpath(f'.//w:footnote[@w:id="{footnote_id}"]//w:t/text()', namespaces=namespaces)
                if footnote_elem:
                    title_footnote_texts.extend(footnote_elem)
            all_footnote_text = ' '.join(title_footnote_texts).lower()
            if not all_footnote_text:
                return 0.0
            primary_keyword = expected.get('footnote_contains', '').lower()
            if primary_keyword and primary_keyword not in all_footnote_text:
                return 0.0
            additional_keywords = expected.get('additional_keywords', [])
            for keyword in additional_keywords:
                if keyword.lower() not in all_footnote_text:
                    return 0.0
            return 1.0
    except Exception as e:
        print(f'Error checking footnotes: {e}')
        import traceback
        traceback.print_exc()
        return 0.0

