def check_italic_blue_color__16abfdb3(result_path, expected_rules, **options):
    """Check if all italic text is colored blue.

    Args:
        result_path: Path to the result DOCX file
        expected_rules: Expected color rules
        **options: Additional options (color_tolerance)

    Returns:
        float: 1.0 if all italic text is blue, 0.0 otherwise
    """
    if not result_path:
        return 0.0
    try:
        doc = Document(result_path)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    target_color = expected_rules.get('color', {'r': 0, 'g': 0, 'b': 255})
    tolerance = options.get('color_tolerance', 20)
    italic_count = 0
    correct_color_count = 0
    for paragraph in doc.paragraphs:
        for run in paragraph.runs:
            if run.italic and run.text.strip():
                italic_count += 1
                if run.font.color.rgb:
                    (r, g, b) = run.font.color.rgb
                    if abs(r - target_color['r']) <= tolerance and abs(g - target_color['g']) <= tolerance and (abs(b - target_color['b']) <= tolerance):
                        correct_color_count += 1
    if italic_count == 0:
        return 0.0
    return 1.0 if correct_color_count == italic_count else 0.0

