def check_consonant_words_bold_red__336f1c42(file_path1, file_path2, **kwargs):
    """
    Check if words starting with consonants are both bold and red.

    Args:
        file_path1: Path to result file
        file_path2: Path to expected file (unused)
        **kwargs: threshold for color tolerance

    Returns:
        float: Score with partial credit: 0.5 for bold only, 0.5 for color
    """
    if not file_path1:
        return 0.0
    try:
        document = Document(file_path1)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    threshold = kwargs.get('threshold', 20.0)

    def _calculate_color_difference(rgb1, rgb2):
        """Calculate color difference using CIEDE2000"""
        srgb1 = [rgb1[0] / 255.0, rgb1[1] / 255.0, rgb1[2] / 255.0]
        srgb2 = [rgb2[0] / 255.0, rgb2[1] / 255.0, rgb2[2] / 255.0]
        (lab1, lab2) = (rgb2lab(srgb1), rgb2lab(srgb2))
        delta_e = deltaE_ciede2000(lab1, lab2)
        return delta_e
    red_color = RGBColor(255, 0, 0)
    bold_score = 0.0
    color_score = 0.0
    total_consonant_words = 0
    for table in document.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    for run in paragraph.runs:
                        word = run.text.strip()
                        if word:
                            starts_consonant = word[0].lower() not in 'aeiou'
                            if starts_consonant:
                                total_consonant_words += 1
                                if run.font.bold:
                                    bold_score += 1
                                if run.font.color and run.font.color.rgb:
                                    if _calculate_color_difference(run.font.color.rgb, red_color) <= threshold:
                                        color_score += 1
    if total_consonant_words == 0:
        return 0.0
    final_bold = bold_score / total_consonant_words
    final_color = color_score / total_consonant_words
    return 0.5 * final_bold + 0.5 * final_color

