def check_docx_table_header__13eed80defa5785247e65a748bfcefa5(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if the table has the correct headers and sufficient data rows.

    Args:
        result: Dict with 'headers' (list) and 'rows' (list) from getter
        expected: Expected rules dict with 'headers' (list) and 'min_data_rows' (int)
        **options: Additional options

    Returns:
        1.0 if headers match and row count is sufficient, 0.0 otherwise
    """
    if not result or not isinstance(result, dict):
        logger.info('Result is empty or not a dict')
        return 0.0
    actual_headers = result.get('headers', [])
    actual_rows = result.get('rows', [])
    expected_headers = expected.get('headers', [])
    min_data_rows = expected.get('min_data_rows', 0)
    if len(actual_headers) != len(expected_headers):
        logger.info(f'Header count mismatch: expected {len(expected_headers)}, got {len(actual_headers)}')
        return 0.0
    for (i, (actual, expected_val)) in enumerate(zip(actual_headers, expected_headers)):
        if actual != expected_val:
            logger.info(f"Header mismatch at position {i}: expected '{expected_val}', got '{actual}'")
            return 0.0
    if len(actual_rows) < min_data_rows:
        logger.info(f'Insufficient data rows: expected at least {min_data_rows}, got {len(actual_rows)}')
        return 0.0
    logger.info(f'Table verification passed: headers match and {len(actual_rows)} data rows found (minimum {min_data_rows})')
    return 1.0

