def check_docx_table_gpt4__54b06cb187414c0c4afc1326d01127a0(result: Optional[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """
    Check if the Word document contains a table with headers and GPT-4 model data,
    and verify that the table is placed under the "Main Results" section.

    Args:
        result: Dictionary containing:
            - 'tables': List of tables from the document (each table is a list of rows)
            - 'structure': List of document elements in order
        expected: Dictionary with expected table structure rules
            - table_index: Which table to check (default 0, first table)
            - num_columns: Expected number of columns
            - header_row: Expected header row values
            - model_name: Expected model name (default 'Gpt-4')

    Returns:
        Score between 0.0 and 1.0 based on table correctness and placement:
        - 25% for table placement under "Main Results" section
        - 40% for correct header row
        - 35% for correct GPT-4 data row
    """
    if result is None or not isinstance(result, dict):
        return 0.0
    tables = result.get('tables', [])
    structure = result.get('structure', [])
    table_index = expected.get('table_index', 0)
    num_columns = expected.get('num_columns', 12)
    header_row = expected.get('header_row', [])
    model_name = expected.get('model_name', 'Gpt-4')
    if len(tables) <= table_index:
        return 0.0
    actual_table = tables[table_index]
    if len(actual_table) < 2:
        return 0.0
    score = 0.0
    main_results_found = False
    table_after_main_results = False
    for (i, element) in enumerate(structure):
        if element['type'] == 'paragraph':
            text = element.get('text', '').lower()
            if 'main results' in text:
                main_results_found = True
        elif element['type'] == 'table' and element.get('index') == table_index:
            if main_results_found:
                table_after_main_results = True
            break
    if table_after_main_results:
        score += 0.25
    first_row = actual_table[0]
    if len(first_row) == num_columns and first_row == header_row:
        score += 0.4
    for i in range(1, len(actual_table)):
        row = actual_table[i]
        if len(row) == num_columns and row[0] == model_name:
            score += 0.35
            break
    return score

