def check_docx_contains_both_titles__2e06628be7ef5b3dc45161c8ea091810(result: str, expected: Dict[str, Any], **options) -> float:
    """Check if DOCX content contains both expected paper titles.

    Args:
        result: Text content from the DOCX file
        expected: Dict with 'titles' key containing list of expected paper titles
        **options: Additional options

    Returns:
        Score: 0.5 for each title found (1.0 if both found, 0.5 if one found, 0.0 if none)
    """
    if not result or not expected:
        return 0.0
    expected_titles = expected.get('titles', [])
    if not expected_titles:
        return 0.0
    score = 0.0
    points_per_title = 1.0 / len(expected_titles)
    for title in expected_titles:
        if 'BERT' in title and 'BERT' in result:
            score += points_per_title
        elif 'Deep Contextualized' in title and 'Deep Contextualized' in result:
            score += points_per_title
        elif title.lower() in result.lower():
            score += points_per_title
    return min(score, 1.0)

