def check_writer_autosave__4ba38c11b278f22021b60b6cccfa645c(result, expected, **options):
    """Check if the LibreOffice Writer auto-save settings match the expected values.

    Args:
        result: The actual auto-save settings (dict or None)
        expected: Dict with expected 'enabled' (bool) and optionally 'interval' (int)
        **options: Additional options (not used)

    Returns:
        float: 1.0 if all settings match, 0.5 if only enabled matches, 0.0 if none match
    """
    if result is None:
        logger.error('Result is None - auto-save settings not found')
        return 0.0
    if not isinstance(result, dict) or not isinstance(expected, dict):
        logger.error('Invalid result or expected format')
        return 0.0
    score = 0.0
    checks = 0
    matches = 0
    if 'enabled' in expected:
        checks += 1
        expected_enabled = expected['enabled']
        actual_enabled = result.get('enabled', False)
        if actual_enabled == expected_enabled:
            matches += 1
            logger.info(f'AutoSave enabled matches: {actual_enabled} == {expected_enabled}')
        else:
            logger.info(f'AutoSave enabled mismatch: {actual_enabled} != {expected_enabled}')
    if 'interval' in expected and 'interval' in result:
        checks += 1
        expected_interval = expected['interval']
        actual_interval = result['interval']
        if actual_interval == expected_interval:
            matches += 1
            logger.info(f'AutoSave interval matches: {actual_interval} == {expected_interval}')
        else:
            logger.info(f'AutoSave interval mismatch: {actual_interval} != {expected_interval}')
    if checks == 0:
        logger.warning('No settings to check')
        return 0.0
    score = matches / checks
    logger.info(f'AutoSave check score: {matches}/{checks} = {score}')
    return score

