def check_odt_file_exists__82a08649fb4593676b95bae1dea8263f(result, expected, **options):
    """
    Check if ODT file exists AND original DOCX file is preserved.
    This verifies that the 'Export' operation (not 'Save As') was performed.

    Args:
        result: Dict from getter with 'odt_exists' and 'docx_exists' keys
        expected: Dict with expected values (from rules)
        **options: Additional options

    Returns:
        float: 1.0 if both files exist, 0.0 otherwise
    """
    if not isinstance(result, dict):
        logger.error(f'Invalid result type: {type(result)}')
        return 0.0
    odt_exists = result.get('odt_exists', False)
    docx_exists = result.get('docx_exists', False)
    odt_path = result.get('odt_path', 'unknown')
    docx_path = result.get('docx_path', 'unknown')
    if odt_exists and docx_exists:
        logger.info(f'✅ ODT file exists at {odt_path} and original DOCX file preserved at {docx_path}')
        return 1.0
    elif odt_exists and (not docx_exists):
        logger.warning(f"❌ ODT file exists at {odt_path} but original DOCX file missing at {docx_path} - this is 'Save As' not 'Export'")
        return 0.0
    elif not odt_exists and docx_exists:
        logger.warning(f'❌ Original DOCX file exists at {docx_path} but ODT file not found at {odt_path}')
        return 0.0
    else:
        logger.warning(f'❌ Neither ODT file nor DOCX file found')
        return 0.0

