def check_references_alphabetical__30fea77e(result, expected, **options):
    """Check if references are sorted alphabetically.

    Args:
        result: List of reference strings from getter
        expected: Dictionary with 'sorted' key (bool)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        logger.error('No references found')
        return 0.0
    should_be_sorted = expected.get('sorted', True)
    first_authors = []
    for ref in result:
        parts = ref.split(',')
        if parts:
            first_author = parts[0].strip()
            first_authors.append(first_author)
        else:
            first_authors.append(ref[:20])
    sorted_authors = sorted(first_authors, key=str.lower)
    is_sorted = first_authors == sorted_authors
    logger.info(f'References sorted: {is_sorted}')
    logger.info(f'First few authors: {first_authors[:5]}')
    if is_sorted == should_be_sorted:
        logger.info(f'✓ Reference order check passed')
        return 1.0
    else:
        correct_positions = sum((1 for (i, (a, b)) in enumerate(zip(first_authors, sorted_authors)) if a == b))
        partial_score = correct_positions / len(first_authors)
        logger.warning(f'✗ Reference order check: {correct_positions}/{len(first_authors)} in correct position')
        return partial_score

