def check_paragraph_spacing__1b73ca66(result, expected, **options):
    """
    Compare paragraph spacing (before/after) in a docx file against expected values.

    Args:
        result: Path to the result docx file
        expected: Dictionary with paragraph_spacing mapping
                 Each entry: paragraph_index -> {"before": pt, "after": pt}
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not expected:
        return 0.0
    paragraph_spacing = expected.get('paragraph_spacing', {})
    if not paragraph_spacing:
        return 0.0
    try:
        doc = Document(result)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    score = 0.0
    total_checks = len(paragraph_spacing)
    for (para_idx_str, spacing_rules) in paragraph_spacing.items():
        para_idx = int(para_idx_str)
        if para_idx >= len(doc.paragraphs):
            continue
        para = doc.paragraphs[para_idx]
        expected_before = spacing_rules.get('before')
        expected_after = spacing_rules.get('after')
        actual_before = para.paragraph_format.space_before
        actual_after = para.paragraph_format.space_after
        tolerance = Pt(2)
        before_match = True
        after_match = True
        if expected_before is not None:
            expected_before_emu = Pt(expected_before)
            if actual_before is not None:
                before_match = abs(actual_before - expected_before_emu) <= tolerance
            else:
                before_match = expected_before == 0
        if expected_after is not None:
            expected_after_emu = Pt(expected_after)
            if actual_after is not None:
                after_match = abs(actual_after - expected_after_emu) <= tolerance
            else:
                after_match = expected_after == 0
        if before_match and after_match:
            score += 1.0 / total_checks
    return score

