def check_paragraph_text_colors__0d529e25(result, expected, **options):
    """
    Compare paragraph text colors in a docx file against expected RGB values.

    Args:
        result: Path to the result docx file
        expected: Dictionary with paragraph_colors mapping
                 Each entry: paragraph_index -> {"r": int, "g": int, "b": int}
        **options: Additional options (color_tolerance for RGB tolerance)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not expected:
        return 0.0
    paragraph_colors = expected.get('paragraph_colors', {})
    if not paragraph_colors:
        return 0.0
    color_tolerance = options.get('color_tolerance', 10)
    try:
        doc = Document(result)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    score = 0.0
    total_checks = len(paragraph_colors)
    for (para_idx_str, expected_rgb) in paragraph_colors.items():
        para_idx = int(para_idx_str)
        if para_idx >= len(doc.paragraphs):
            continue
        para = doc.paragraphs[para_idx]
        if not para.runs or not any((run.text.strip() for run in para.runs)):
            continue
        expected_r = expected_rgb.get('r', 0)
        expected_g = expected_rgb.get('g', 0)
        expected_b = expected_rgb.get('b', 0)
        matching_runs = 0
        total_text_runs = 0
        for run in para.runs:
            if run.text.strip():
                total_text_runs += 1
                actual_color = run.font.color.rgb
                if actual_color:
                    r_match = abs(actual_color[0] - expected_r) <= color_tolerance
                    g_match = abs(actual_color[1] - expected_g) <= color_tolerance
                    b_match = abs(actual_color[2] - expected_b) <= color_tolerance
                    if r_match and g_match and b_match:
                        matching_runs += 1
                elif expected_r == 0 and expected_g == 0 and (expected_b == 0):
                    matching_runs += 1
        if total_text_runs > 0 and matching_runs / total_text_runs >= 0.8:
            score += 1.0 / total_checks
    return score

