def check_docx_content_keywords__8a7f3b1e(result, expected, **options):
    """Check if a .docx file contains required keywords and meets length requirements.

    Args:
        result: Path to the .docx file
        expected: Dict with 'required_keywords' list and 'min_length' int
        **options: Additional options like 'case_insensitive'

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        doc = Document(result)
        full_text = '\n'.join([para.text for para in doc.paragraphs])
        required_keywords = expected.get('required_keywords', [])
        min_length = expected.get('min_length', 0)
        case_insensitive = options.get('case_insensitive', False)
        score = 0.0
        if len(full_text) >= min_length:
            score += 0.3
        if required_keywords:
            text_to_check = full_text.lower() if case_insensitive else full_text
            keywords_to_check = [k.lower() for k in required_keywords] if case_insensitive else required_keywords
            found_count = sum((1 for keyword in keywords_to_check if keyword in text_to_check))
            score += 0.7 * (found_count / len(required_keywords))
        return score
    except Exception as e:
        print(f'Error checking docx content: {e}')
        return 0.0

