def check_docx_paragraph_structure__5b3e8d2c(result, expected, **options):
    """Check if a .docx file has required paragraph structure.

    Args:
        result: Path to the .docx file
        expected: Dict with min_non_empty_paragraphs and min_total_chars
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        doc = Document(result)
        non_empty_paras = [para.text for para in doc.paragraphs if para.text.strip()]
        total_chars = sum((len(p) for p in non_empty_paras))
        min_paragraphs = expected.get('min_non_empty_paragraphs', 0)
        min_chars = expected.get('min_total_chars', 0)
        score = 0.0
        if len(non_empty_paras) >= min_paragraphs:
            score += 0.4
        if total_chars >= min_chars:
            score += 0.6
        return score
    except Exception as e:
        print(f'Error checking paragraph structure: {e}')
        return 0.0

