def check_docx_locations__2925098e3714cd43fc90cbdf936ba654(result_file_path, expected, **options):
    """
    Check if the Word document contains at least 5 locations from the expected list.
    Uses fuzzy matching to handle minor variations in location names.

    Args:
        result_file_path: Path to the .docx file
        expected: Dict with 'locations' key containing list of expected location names
        **options: Additional options (e.g., threshold for fuzzy matching)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result_file_path is None:
        return 0.0
    expected_locations = expected.get('locations', [])
    min_count = expected.get('min_count', 5)
    fuzzy_threshold = options.get('fuzzy_threshold', 80)
    if not expected_locations:
        return 0.0
    try:
        doc = Document(result_file_path)
    except Exception:
        return 0.0
    doc_text = []
    for para in doc.paragraphs:
        if para.text.strip():
            doc_text.append(para.text.strip())
    found_count = 0
    for location in expected_locations:
        found = False
        for para_text in doc_text:
            score = fuzz.partial_ratio(location, para_text)
            if score >= fuzzy_threshold:
                found = True
                break
        if found:
            found_count += 1
    if found_count >= min_count:
        return 1.0
    else:
        return found_count / min_count

def check_docx_para_size_align__b8944de3a7b358883a1de96cd4e0f7f5(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if paragraph has the expected font size and alignment.

    Args:
        result: Dict from getter with keys 'font_size', 'alignment', 'error'
        expected: Dict with keys 'font_size' (float), 'alignment' (str)
        **options: Additional options

    Returns:
        float: 1.0 if both font size and alignment match, 0.5 if only one matches, 0.0 otherwise
    """
    if result.get('error'):
        return 0.0
    expected_size = expected.get('font_size', 12.0)
    expected_alignment = expected.get('alignment', 'LEFT')
    result_size = result.get('font_size', 0.0)
    result_alignment = result.get('alignment', 'LEFT')
    size_match = False
    if result_size and abs(result_size - expected_size) < 0.5:
        size_match = True
    alignment_match = result_alignment == expected_alignment
    if size_match and alignment_match:
        return 1.0
    elif size_match or alignment_match:
        return 0.5
    else:
        return 0.0

def check_hyperparams__526d49269c794c02e875c3ff44cdccae(result, expected, **options):
    """Check if key hyperparameters were extracted.

    Args:
        result: Extracted hyperparameter lines from result file
        expected: Required hyperparameters to find
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        return 0.0

    def extract_param_names(text):
        """Extract parameter names from assignment lines."""
        params = set()
        for line in text.splitlines():
            stripped = line.strip()
            if '=' in stripped:
                param_name = stripped.split('=')[0].strip()
                params.add(param_name)
        return params
    result_params = extract_param_names(result)
    required_params = expected.get('required_params', [])
    if not required_params:
        min_params = expected.get('min_params', 5)
        if len(result_params) >= min_params:
            return 1.0
        else:
            return len(result_params) / min_params
    found_count = 0
    for param in required_params:
        if param in result_params:
            found_count += 1
    recall = found_count / len(required_params)
    extra_params = len(result_params) - len(required_params)
    if extra_params > 5:
        penalty = (extra_params - 5) * 0.05
        return max(0.0, recall - penalty)
    return recall

