def check_docx_sentence_case__2664e86f(result_file, expected, **options):
    """
    Check if text is in sentence case (only first letter of first word capitalized per sentence).

    Args:
        result_file: Path to the result .docx file
        expected: Not used (rule-based check)
        **options: Additional options

    Returns:
        float: 1.0 if all text follows sentence case, 0.0 otherwise
    """
    if not result_file:
        return 0.0
    try:
        doc = Document(result_file)
        paragraphs = [p.text for p in doc.paragraphs if p.text.strip()]
        if not paragraphs:
            return 0.0
        for para_text in paragraphs:
            sentences = para_text.split('. ')
            for sentence in sentences:
                sentence = sentence.strip()
                if not sentence:
                    continue
                if sentence[0].isalpha() and (not sentence[0].isupper()):
                    return 0.0
                words = sentence.split()
                for word in words[1:]:
                    if word.isupper() and len(word) > 1:
                        return 0.0
        return 1.0
    except Exception as e:
        logger.error(f'Error checking sentence case: {e}')
        return 0.0

