def check_top_marks_highlighted__fc682cf1(result: List[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """
    Check if the top N marks have yellow highlighting applied.

    Args:
        result: List of cell info from getter [{"cell": "C2", "value": 9.0, "has_fill": True, "fill_color": "FFFF00"}, ...]
        expected: Dict with "top_n" and "top_values" keys
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    top_n = expected.get('top_n', 5)
    expected_top_values = expected.get('top_values', [])
    yellow_colors = ['FFFF00', 'FFFFFF00', 'FFFF99', 'FFFFCC', 'FFFFE0']
    sorted_cells = sorted(result, key=lambda x: x['value'], reverse=True)
    top_cells = sorted_cells[:top_n]
    correctly_highlighted = 0
    for cell in top_cells:
        if cell.get('has_fill') and cell.get('fill_color'):
            fill_color = cell['fill_color'].upper()
            is_yellow = fill_color in yellow_colors or fill_color[2:] in yellow_colors if len(fill_color) == 8 else False
            if is_yellow and cell['value'] in expected_top_values:
                correctly_highlighted += 1
    incorrectly_highlighted = 0
    for cell in sorted_cells[top_n:]:
        if cell.get('has_fill'):
            incorrectly_highlighted += 1
    if top_n == 0:
        return 0.0
    score = correctly_highlighted / top_n
    if incorrectly_highlighted > 0:
        penalty = min(0.5, incorrectly_highlighted * 0.1)
        score = max(0.0, score - penalty)
    return score

