def check_docx_title_word_count__7d271099(result, expected, **options):
    """
    Check if the title contains a word count in parentheses at the end,
    and verify the count matches the actual word count of the essay body.

    Args:
        result: Path to the DOCX file
        expected: Dict with keys:
            - title_para_index: int - which paragraph is the title
            - contains_number: bool - whether a number should be present
            - expected_count_range: list - [min, max] range for the count
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        doc = Document(result)
        title_idx = expected.get('title_para_index', 0)
        count_range = expected.get('expected_count_range', [1080, 1095])
        if title_idx >= len(doc.paragraphs):
            return 0.0
        title_text = doc.paragraphs[title_idx].text.strip()
        match = re.search('\\((\\d+)\\)\\s*$', title_text)
        if not match:
            return 0.0
        count_in_title = int(match.group(1))
        if not count_range[0] <= count_in_title <= count_range[1]:
            return 0.0
        actual_word_count = 0
        in_references = False
        for (i, para) in enumerate(doc.paragraphs):
            para_text = para.text.strip()
            if i == title_idx:
                continue
            if not para_text:
                continue
            if re.match('^(References?|Bibliography|Works?\\s+Cited)', para_text, re.IGNORECASE):
                in_references = True
                continue
            if in_references:
                continue
            if i == title_idx + 1 and len(para_text.split()) < 10:
                continue
            if re.match('^(Word\\s+count|Total\\s+words?)\\s*:', para_text, re.IGNORECASE):
                continue
            words = para_text.split()
            actual_word_count += len(words)
        tolerance = 15
        if abs(actual_word_count - count_in_title) <= tolerance:
            return 1.0
        return 0.7
    except Exception as e:
        print(f'Error checking word count in title: {e}')
        return 0.0

