def check_odt_conversion__08cbb5897c6dab86f1d325a3d103c585(result, expected, **options):
    """
    Check if .docx files were correctly converted to .odt format.

    Args:
        result: Tuple of (command_output, archive_bytes) from getter
        expected: Dict with command_match rule (expected IS the rules dict, not {'type': 'rule', 'rules': {...}})
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, tuple) or len(result) != 2:
        return 0.0
    (command_output, archive_bytes) = result
    if not isinstance(expected, dict):
        return 0.0
    expected_command = expected.get('command_match', 'catch the desired command')
    score = 0.0
    if isinstance(command_output, str) and expected_command in command_output:
        score += 0.5
    if archive_bytes and len(archive_bytes) > 0:
        try:
            tar_buffer = io.BytesIO(archive_bytes)
            with tarfile.open(fileobj=tar_buffer, mode='r:gz') as tar:
                members = tar.getmembers()
                odt_files = [m.name for m in members if m.name.endswith('.odt') and m.isfile()]
                expected_odt_files = {'1cfc37e1-344f-52ef-be9f-69bc1855316d.odt', 'adfddc91-944f-572e-8439-c67b67f4c5f7.odt', 'd119ec81-bc60-5b76-8679-5f942b191c70.odt'}
                if len(odt_files) == 3:
                    odt_files_set = set(odt_files)
                    if odt_files_set == expected_odt_files:
                        all_valid = True
                        for member in members:
                            if member.name in expected_odt_files and member.size == 0:
                                all_valid = False
                                break
                        if all_valid:
                            score += 0.5
        except Exception:
            pass
    return score

