def check_italic_font_color_blue__f8e0f928a1126a62a1afb54fc42eb26e(result, expected, **options):
    """
    Check if all italic text in the document has blue color.

    Args:
        result: Path to the docx file to check
        expected: Dictionary containing reference file URL (when type='rule')
        **options: Additional options (color_tolerance for fuzzy matching)

    Returns:
        float: 1.0 if all italic text is blue, 0.0 otherwise
    """
    if not result:
        return 0.0
    expected_file_path = None
    if isinstance(expected, dict):
        reference_url = expected.get('reference_file')
        if not reference_url:
            logger.error("Expected dict does not contain 'reference_file' key")
            return 0.0
        try:
            response = requests.get(reference_url, timeout=30)
            response.raise_for_status()
            with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp_file:
                tmp_file.write(response.content)
                expected_file_path = tmp_file.name
        except Exception as e:
            logger.error(f'Error downloading reference file from {reference_url}: {e}')
            return 0.0
    else:
        expected_file_path = expected
    try:
        doc_result = Document(result)
        doc_expected = Document(expected_file_path)
    except Exception as e:
        logger.error(f'Error opening documents: {e}')
        if isinstance(expected, dict) and expected_file_path and os.path.exists(expected_file_path):
            os.unlink(expected_file_path)
        return 0.0
    result_paragraphs = [p.text for p in doc_result.paragraphs]
    expected_paragraphs = [p.text for p in doc_expected.paragraphs]
    if len(result_paragraphs) != len(expected_paragraphs):
        if isinstance(expected, dict) and expected_file_path and os.path.exists(expected_file_path):
            os.unlink(expected_file_path)
        return 0.0
    for (p1, p2) in zip(result_paragraphs, expected_paragraphs):
        if p1.strip() != p2.strip():
            if isinstance(expected, dict) and expected_file_path and os.path.exists(expected_file_path):
                os.unlink(expected_file_path)
            return 0.0
    color_tolerance = options.get('color_tolerance', 30)
    target_blue = RGBColor(0, 0, 255)
    for paragraph in doc_result.paragraphs:
        for run in paragraph.runs:
            if run.italic:
                if run.font.color and run.font.color.rgb:
                    color = run.font.color.rgb
                    r_diff = abs(color[0] - target_blue[0])
                    g_diff = abs(color[1] - target_blue[1])
                    b_diff = abs(color[2] - target_blue[2])
                    max_diff = max(r_diff, g_diff, b_diff)
                    if max_diff > color_tolerance:
                        logger.info(f'Found italic text with color RGB({color[0]}, {color[1]}, {color[2]}), expected blue')
                        if isinstance(expected, dict) and expected_file_path and os.path.exists(expected_file_path):
                            os.unlink(expected_file_path)
                        return 0.0
                else:
                    logger.info(f'Found italic text without blue color')
                    if isinstance(expected, dict) and expected_file_path and os.path.exists(expected_file_path):
                        os.unlink(expected_file_path)
                    return 0.0
    if isinstance(expected, dict) and expected_file_path and os.path.exists(expected_file_path):
        os.unlink(expected_file_path)
    return 1.0

