def check_min_font_size__904067aa(font_data, rule):
    """Check if Chrome minimum font size matches expected value.

    Args:
        font_data: Dict with 'minimum_font_size' key from getter
        rule: Dict with comparison rules

    Returns:
        float: 1.0 if matches, 0.0 otherwise
    """
    actual_min_size = font_data.get('minimum_font_size', 0)
    if rule['type'] == 'value':
        expected = rule['value']
        return 1.0 if actual_min_size == expected else 0.0
    elif rule['type'] == 'range':
        min_val = rule['min']
        max_val = rule['max']
        return 1.0 if min_val <= actual_min_size <= max_val else 0.0
    else:
        logger.error(f"Unknown rule type: {rule['type']}")
        return 0.0

