def check_docx_ends_with__d3067cd7(result: Dict[str, Any], expected: Any, **options) -> float:
    """
    Comprehensive check for DOCX content extracted from PowerPoint slides.
    Validates that ALL text from ALL slides was extracted correctly.

    Checks performed:
    1. Last line contains expected text (verifies last slide content)
    2. Minimum paragraph count (ensures multiple slides were processed)
    3. Presence of key text snippets from different slides

    Args:
        result: Dict from getter with 'all_text', 'paragraphs', 'paragraph_count', 'first_line', 'last_line'
        expected: Dict with 'text' key (expected last line content)
        **options: Additional options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if not isinstance(result, dict):
        logger.error(f'Result should be a dict, got {type(result)}')
        return 0.0
    if not isinstance(expected, dict):
        logger.error(f'Expected should be a dict, got {type(expected)}')
        return 0.0
    expected_text = expected.get('text', '')
    all_text = result.get('all_text', '')
    paragraphs = result.get('paragraphs', [])
    paragraph_count = result.get('paragraph_count', 0)
    last_line = result.get('last_line', '')
    first_line = result.get('first_line', '')
    if not expected_text:
        logger.warning('No expected text provided')
        return 0.0
    if expected_text.lower() not in last_line.lower():
        logger.warning(f"Last line does not contain '{expected_text}'. Got: {last_line[:200]}")
        return 0.0
    logger.info(f"✓ Last line contains expected text: '{expected_text}'")
    MIN_PARAGRAPHS = 10
    if paragraph_count < MIN_PARAGRAPHS:
        logger.warning(f'Insufficient paragraphs: {paragraph_count} < {MIN_PARAGRAPHS} (likely incomplete extraction)')
        return 0.0
    logger.info(f'✓ Paragraph count sufficient: {paragraph_count} >= {MIN_PARAGRAPHS}')
    key_snippets = ['Unlocking the Power of ChatGPT', 'ChatGPT', 'language model', 'Share your screen']
    missing_snippets = []
    for snippet in key_snippets:
        if snippet.lower() not in all_text.lower():
            missing_snippets.append(snippet)
    if missing_snippets:
        logger.warning(f'Missing key content from slides: {missing_snippets}')
        logger.warning('This suggests incomplete text extraction from all slides')
        return 0.0
    logger.info(f'✓ All key text snippets found in document')
    if not first_line:
        logger.warning('First line is empty - document may be malformed')
        return 0.0
    logger.info(f'✓ First line present: {first_line[:100]}')
    logger.info('✓ All verification checks passed - complete text extraction confirmed')
    return 1.0

