def check_italic_highlight_yellow__2e9e191e(result_file, expected):
    """Check that all italic text has yellow-ish highlight color.

    Args:
        result_file: Path to the result .docx file
        expected: Expected configuration (unused)

    Returns:
        float: Proportion of italic runs with yellow highlight (0.0-1.0)
    """
    if not result_file:
        return 0.0
    try:
        doc = Document(result_file)
    except Exception as e:
        logger.error(f'Error opening document: {e}')
        return 0.0
    italic_count = 0
    yellow_italic_count = 0
    for paragraph in doc.paragraphs:
        for run in paragraph.runs:
            if run.italic:
                italic_count += 1
                if run.font.highlight_color == WD_COLOR_INDEX.YELLOW:
                    yellow_italic_count += 1
                elif run.font.highlight_color == 7:
                    yellow_italic_count += 1
                elif hasattr(run.font, 'fill') and run.font.fill and hasattr(run.font.fill, 'fore_color'):
                    try:
                        rgb = run.font.fill.fore_color.rgb
                        if rgb:
                            (r, g, b) = (rgb[0], rgb[1], rgb[2])
                            if r > 200 and g > 200 and (b < 100):
                                yellow_italic_count += 1
                    except:
                        pass
    if italic_count == 0:
        return 0.0
    return yellow_italic_count / italic_count

