def check_writer_default_font__81732a3ee2a8cc5edff40ff6b5cb9337(config_file_path, rules):
    """Check the default font setting in LibreOffice Writer for a specific property.

    This function reads the registrymodifications.xcu file and checks if the
    specified property in the DefaultFont configuration matches the expected value.

    Args:
        config_file_path: Path to the registrymodifications.xcu file
        rules: Dictionary containing:
            - config_path: XML path to the configuration section
            - prop_name: Name of the property to check
            - font_name: Expected font name value

    Returns:
        1 if the font matches the expected value, 0 otherwise
    """
    if not config_file_path:
        return 0
    config_path = rules.get('config_path', '/org.openoffice.Office.Writer/DefaultFont')
    prop_name = rules.get('prop_name', 'List')
    expected_font = rules.get('font_name')
    if not expected_font:
        logger.error('No expected font_name provided in rules')
        return 0
    actual_font = None
    try:
        tree = ET.parse(config_file_path)
        root = tree.getroot()
        namespace = {'oor': 'http://openoffice.org/2001/registry'}
        xpath = f'.//item[@oor:path="{config_path}"]'
        for elem in root.findall(xpath, namespace):
            prop_xpath = f'.//prop[@oor:name="{prop_name}"]'
            for prop in elem.findall(prop_xpath, namespace):
                for value in prop.findall('value', namespace):
                    actual_font = value.text
                    break
            if actual_font:
                break
    except Exception as e:
        logger.error(f'Error parsing config file: {e}')
        return 0
    return 1 if actual_font == expected_font else 0

def check_docx_font_color__c2775672(result_file, expected, **options):
    """
    Check if the first paragraph has blue font color.

    Args:
        result_file: Path to the result .docx file
        expected: Dict with paragraph_index and target RGB color
        **options: Additional options (color_tolerance for fuzzy matching)

    Returns:
        float: 1.0 if font color matches, 0.0 otherwise
    """
    if not result_file:
        return 0.0
    try:
        doc = Document(result_file)
        para_idx = expected.get('paragraph_index', 0)
        target_r = expected.get('r', 0)
        target_g = expected.get('g', 0)
        target_b = expected.get('b', 255)
        tolerance = options.get('color_tolerance', 30)
        if para_idx >= len(doc.paragraphs):
            return 0.0
        paragraph = doc.paragraphs[para_idx]
        if not paragraph.runs:
            return 0.0
        for run in paragraph.runs:
            if run.text.strip():
                if run.font.color.rgb is None:
                    return 0.0
                rgb = run.font.color.rgb
                (r, g, b) = (rgb[0], rgb[1], rgb[2])
                if abs(r - target_r) > tolerance or abs(g - target_g) > tolerance or abs(b - target_b) > tolerance:
                    return 0.0
        return 1.0
    except Exception as e:
        logger.error(f'Error checking font color: {e}')
        return 0.0

