def check_docx_highlighted_word__96fe770b(result_file, expected, **options):
    """
    Check if a Word document contains specific text with highlighted words.
    Verifies that:
    1. All expected texts (GPT-4 responses) are present in the document
    2. Each response appears as a separate paragraph
    3. All occurrences of the specified word are highlighted

    Args:
        result_file: Path to the result .docx file
        expected: Dictionary with 'texts' (list of expected texts) and 'highlighted_word'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result_file or not result_file.endswith('.docx'):
        return 0.0
    try:
        doc = Document(result_file)
    except Exception as e:
        print(f'Error reading document: {e}')
        return 0.0
    expected_texts = expected.get('texts', [])
    highlighted_word = expected.get('highlighted_word', '')
    if not expected_texts or not highlighted_word:
        return 0.0
    all_paragraphs = [p.text.strip() for p in doc.paragraphs if p.text.strip()]
    if not all_paragraphs:
        return 0.0

    def normalize_text(text):
        return re.sub('\\s+', ' ', text).strip()
    doc_text_normalized = ' '.join((normalize_text(p) for p in all_paragraphs))
    content_score = 0.0
    texts_found = 0
    for expected_text in expected_texts:
        expected_normalized = normalize_text(expected_text)
        if expected_normalized in doc_text_normalized:
            texts_found += 1
    if texts_found == len(expected_texts):
        content_score = 0.5
    elif texts_found > 0:
        content_score = 0.5 * (texts_found / len(expected_texts))
    highlight_score = 0.0
    highlighted_count = 0
    total_word_count = 0
    full_doc_text = ' '.join(all_paragraphs)
    total_word_count = len(re.findall('\\b' + re.escape(highlighted_word) + '\\b', full_doc_text, re.IGNORECASE))
    if total_word_count > 0:
        for paragraph in doc.paragraphs:
            for run in paragraph.runs:
                if highlighted_word.lower() in run.text.lower():
                    if run.font.highlight_color is not None:
                        highlighted_count += len(re.findall('\\b' + re.escape(highlighted_word) + '\\b', run.text, re.IGNORECASE))
        if highlighted_count >= total_word_count:
            highlight_score = 0.5
        elif highlighted_count > 0:
            highlight_score = 0.5 * (highlighted_count / total_word_count)
    return content_score + highlight_score

def check_docx_underline__4a559506(result, expected, **options):
    """Check if all uppercase text is underlined.

    Args:
        result: Path to docx file (from vm_file getter)
        expected: Expected rules dict (not used in dynamic logic)
        **options: Additional options

    Returns:
        float: Score based on how many uppercase paragraphs are correctly underlined
    """
    try:
        doc = Document(result)
        uppercase_paragraphs = []
        for (idx, para) in enumerate(doc.paragraphs):
            if not para.text.strip():
                continue
            text = para.text.strip()
            if text and text.isupper():
                uppercase_paragraphs.append(idx)
        if not uppercase_paragraphs:
            logger.info('No uppercase paragraphs found in document')
            return 0.0
        logger.info(f'Found {len(uppercase_paragraphs)} uppercase paragraphs at indices: {uppercase_paragraphs}')
        correctly_underlined = 0
        for idx in uppercase_paragraphs:
            para = doc.paragraphs[idx]
            all_underlined = True
            has_text_runs = False
            for run in para.runs:
                if run.text.strip():
                    has_text_runs = True
                    if not run.underline:
                        all_underlined = False
                        break
            if has_text_runs and all_underlined:
                correctly_underlined += 1
                logger.info(f'Paragraph {idx} correctly underlined')
            else:
                logger.info(f'Paragraph {idx} NOT properly underlined (all_underlined={all_underlined}, has_text_runs={has_text_runs})')
        score = correctly_underlined / len(uppercase_paragraphs)
        logger.info(f'Underline score: {score} ({correctly_underlined}/{len(uppercase_paragraphs)} uppercase paragraphs correctly underlined)')
        return score
    except Exception as e:
        logger.error(f'Error checking underline: {e}')
        return 0.0

