def check_docx_highlighted_text__a8445a3b(result, expected, **options):
    """Check if specific text is highlighted in document.

    Args:
        result: List of highlighted text strings from getter
        expected: Expected text that should be highlighted (string)
        **options: Additional options (case_sensitive, partial_match)

    Returns:
        float: 1.0 if text is highlighted, 0.0 otherwise
    """
    case_sensitive = options.get('case_sensitive', False)
    partial_match = options.get('partial_match', False)
    if not isinstance(result, list):
        return 0.0
    expected_text = expected if case_sensitive else expected.lower()
    for highlighted_text in result:
        check_text = highlighted_text if case_sensitive else highlighted_text.lower()
        if partial_match:
            if expected_text in check_text:
                return 1.0
        elif expected_text == check_text:
            return 1.0
    return 0.0

def check_docx_text_formatting__9ed81cf3da559e332b87361ccd7e4ff2(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if text content matches expected responses and formatting is correct.

    Verifies:
    1. Correct number of non-empty paragraphs (responses)
    2. Blank lines between responses (empty paragraphs)
    3. All occurrences of target word are italicized
    4. Correct total count of target word

    Args:
        result: Dictionary from getter with paragraphs data
        expected: Expected rules (num_responses, target_word, target_word_count)
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    paragraphs = result.get('paragraphs', [])
    expected_num_responses = expected.get('num_responses', 6)
    target_word = expected.get('target_word', 'poem')
    expected_target_word_count = expected.get('target_word_count', 8)
    non_empty_paragraphs = []
    non_empty_indices = []
    for (idx, p) in enumerate(paragraphs):
        if p.get('text', '').strip():
            non_empty_paragraphs.append(p)
            non_empty_indices.append(idx)
    if len(non_empty_paragraphs) != expected_num_responses:
        return 0.0
    if len(non_empty_indices) > 1:
        for i in range(len(non_empty_indices) - 1):
            current_idx = non_empty_indices[i]
            next_idx = non_empty_indices[i + 1]
            if next_idx - current_idx < 2:
                return 0.0
    total_target_words = 0
    correctly_formatted = 0
    for para in non_empty_paragraphs:
        runs = para.get('runs', [])
        for run_info in runs:
            run_text = run_info.get('text', '')
            if target_word in run_text:
                target_count_in_run = run_text.count(target_word)
                total_target_words += target_count_in_run
                if run_info.get('italic', False):
                    correctly_formatted += target_count_in_run
    if total_target_words != expected_target_word_count:
        return 0.0
    if total_target_words == 0:
        return 0.0
    if correctly_formatted != total_target_words:
        return 0.0
    return 1.0

