def check_docx_table_structure__256ba3c478aefa1c15edcf46f5e2019b(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if the table structure matches expected configuration with partial credit.

    Verifies:
    1. Table exists
    2. Table has correct dimensions (rows/cols)
    3. Key cells contain expected content

    Args:
        result: Dict from getter with 'exists', 'row_count', 'col_count', 'cells'
        expected: Dict with 'min_rows', 'min_cols', 'required_cells' (dict of position: expected_text)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 with partial credit
    """
    score = 0.0
    total_checks = 0
    if result.get('exists', False):
        score += 0.3
    else:
        return 0.0
    min_rows = expected.get('min_rows', 0)
    min_cols = expected.get('min_cols', 0)
    if result.get('row_count', 0) >= min_rows and result.get('col_count', 0) >= min_cols:
        score += 0.2
    required_cells = expected.get('required_cells', {})
    if required_cells:
        cell_score = 0.0
        result_cells = result.get('cells', {})
        for (cell_key, expected_text) in required_cells.items():
            actual_text = result_cells.get(cell_key, '')
            if actual_text.strip() == expected_text.strip():
                cell_score += 1.0
        cell_score = cell_score / len(required_cells) * 0.5
        score += cell_score
    return score

def check_chapter_page_counts__85787ccf9f02e58e021cd6df8fdfe874(result: Dict[str, int], expected: Dict[str, Any], **options) -> float:
    """
    Check if chapter PDFs have reasonable page counts.

    Args:
        result: Dict mapping chapter filename to page count from getter
        expected: Dict with 'min_pages_per_chapter' (minimum pages per chapter)

    Returns:
        Score between 0.0 and 1.0 based on how many chapters meet page count requirement
    """
    min_pages = expected.get('min_pages_per_chapter', 5)
    expected_chapters = expected.get('chapters', [])
    if not result:
        logger.warning('No chapter page counts received')
        return 0.0
    if not expected_chapters:
        logger.warning('No expected chapters specified')
        return 0.0
    score = 0.0
    total_chapters = len(expected_chapters)
    for chapter in expected_chapters:
        page_count = result.get(chapter, -1)
        if page_count == -1:
            logger.warning(f"Chapter '{chapter}' not found or unreadable")
            continue
        if page_count >= min_pages:
            score += 1.0 / total_chapters
            logger.info(f"Chapter '{chapter}' has valid page count: {page_count}")
        else:
            logger.warning(f"Chapter '{chapter}' has insufficient pages: {page_count} (min: {min_pages})")
    logger.info(f'Chapter page counts check score: {score:.2f} ({int(score * total_chapters)}/{total_chapters} chapters valid)')
    return score

