def check_docx_highlight__4fd57e51(result, expected, **options):
    """Check if uppercase text has yellow highlighting applied.

    Args:
        result: Path to docx file (from vm_file getter)
        expected: Expected rules dict with 'uppercase_paragraphs' indices
        **options: Additional options

    Returns:
        float: Score based on how many uppercase paragraphs are highlighted with yellow
    """
    try:
        doc = Document(result)
        uppercase_indices = expected.get('uppercase_paragraphs', [])
        if not uppercase_indices:
            for (idx, para) in enumerate(doc.paragraphs):
                text = para.text.strip()
                if text and text.isupper():
                    uppercase_indices.append(idx)
        if not uppercase_indices:
            logger.warning('No uppercase paragraphs found')
            return 0.0
        score = 0.0
        total = len(uppercase_indices)
        for idx in uppercase_indices:
            if idx >= len(doc.paragraphs):
                continue
            para = doc.paragraphs[idx]
            uppercase_runs = []
            for run in para.runs:
                text = run.text.strip()
                if text and text.isupper():
                    uppercase_runs.append(run)
            if not uppercase_runs and para.text.strip().isupper():
                uppercase_runs = [run for run in para.runs if run.text.strip()]
            if not uppercase_runs:
                continue
            all_highlighted_yellow = True
            for run in uppercase_runs:
                highlight_color = run.font.highlight_color
                is_yellow = False
                if highlight_color is not None:
                    if highlight_color == WD_COLOR_INDEX.YELLOW or highlight_color == 7:
                        is_yellow = True
                if not is_yellow:
                    all_highlighted_yellow = False
                    break
            if all_highlighted_yellow:
                score += 1.0 / total
        logger.info(f'Yellow highlighting score: {score} ({score * total}/{total} uppercase paragraphs highlighted with yellow)')
        return score
    except Exception as e:
        logger.error(f'Error checking highlighting: {e}')
        return 0.0

def check_row_highlighting__8d8ae0e8(result, expected, **options):
    """Check if specified rows have highlighting.

    Args:
        result: Dict of row colors from getter
        expected: Dict of expected row numbers (from rules)
        **options: Additional options (color_tolerance, strict_color_match)

    Returns:
        float: Score between 0.0 and 1.0
    """
    target_rows = expected.get('rows', [])
    if not target_rows:
        return 0.0
    highlighted_count = 0
    for row in target_rows:
        if row in result and result[row] is not None:
            highlighted_count += 1
    score = highlighted_count / len(target_rows)
    return score

def check_docx_blank_lines__98894ee1(result, expected, **options):
    """Check if blank lines exist after specific paragraphs.

    Args:
        result: List of paragraph indices with blank lines after
        expected: Dict with 'blank_after_paragraphs' key

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_blank = expected.get('blank_after_paragraphs', [])
    if not expected_blank:
        return 0.0
    matches = sum((1 for idx in expected_blank if idx in result))
    score = matches / len(expected_blank)
    return score

def check_pdf_page_count__434044232831686d814f3fab48f559ee(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if PDF has expected page count within range.

    Args:
        result: Dict from getter with page count
        expected: Dict with min/max page count (from rules)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result.get('exists', False):
        logger.warning(f"PDF file does not exist at {result.get('path')}")
        return 0.0
    if not result.get('valid_pdf', False):
        logger.warning('PDF file is invalid or corrupted')
        return 0.0
    page_count = result.get('page_count', 0)
    min_pages = expected.get('min_pages', 0)
    max_pages = expected.get('max_pages', float('inf'))
    if min_pages <= page_count <= max_pages:
        logger.info(f'Page count {page_count} is within expected range [{min_pages}, {max_pages}]')
        return 1.0
    else:
        logger.warning(f'Page count {page_count} is outside expected range [{min_pages}, {max_pages}]')
        return 0.0

def check_writer_filtered_rows__ff6673f3b77179ec900fd2f9ae4a2104(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if Writer document has expected filtered rows.

    Args:
        result: Dict from getter with table data
        expected: Dict with expected row count, header, and first column values
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if 'error' in result:
        return 0.0
    score = 0.0
    rows = result.get('rows', [])
    expected_count = expected.get('row_count', 0)
    actual_count = result.get('row_count', 0)
    if actual_count == expected_count:
        score += 0.25
    if expected.get('has_header', False) and len(rows) > 0:
        header_row = rows[0]
        expected_headers = expected.get('header_columns', [])
        if expected_headers:
            header_match = True
            for expected_header in expected_headers:
                found = any((str(cell).strip().lower() == expected_header.lower() for cell in header_row))
                if not found:
                    header_match = False
                    break
            if header_match:
                score += 0.25
        elif len(header_row) > 0:
            score += 0.25
    if 'first_column_values' in expected and len(rows) > 1:
        expected_vals = expected['first_column_values']
        actual_first_col = []
        for i in range(1, len(rows)):
            if len(rows[i]) > 0:
                actual_first_col.append(rows[i][0])
        if len(actual_first_col) == len(expected_vals):
            matches = all((str(actual) == str(expected) for (actual, expected) in zip(actual_first_col, expected_vals)))
            if matches:
                score += 0.25
    min_cols = expected.get('min_columns', 0)
    if min_cols > 0 and len(rows) > 0:
        all_rows_have_min_cols = all((len(row) >= min_cols for row in rows))
        if all_rows_have_min_cols:
            score += 0.25
    return score

def check_docx_image_count__74be0e09(result, expected, **options):
    """Check if the number of images in the document matches expected count.

    Args:
        result: Actual image count from getter
        expected: Expected image count (dict with 'count' key)
        **options: Additional options

    Returns:
        float: 1.0 if counts match, 0.0 otherwise
    """
