def check_docx_para_count__647a34f44ae6bb0086ca88f5ee821f1a(result, expected, **options):
    """Check if the Conclusion section was removed while preserving other sections.

    Verifies that:
    1. Section V (Conclusion) is NOT present in the document
    2. Earlier sections (I-IV) ARE still present
    3. Paragraph count is approximately correct (as a secondary check)

    Args:
        result: dict from getter with document structure info
        expected: dict with expected count
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        return 0.0
    sections = result.get('sections', {})
    headings = result.get('headings', [])
    result_count = result.get('count', 0)
    expected_count = expected.get('count', 0)
    if 'V' in sections:
        return 0.0
    for heading in headings:
        if heading.strip().lower() in ['conclusion', 'conclusions']:
            return 0.0
    required_sections = ['I', 'II', 'III', 'IV']
    missing_sections = [s for s in required_sections if s not in sections]
    if len(missing_sections) > 1:
        return 0.0
    tolerance = options.get('tolerance', 2)
    if abs(result_count - expected_count) > tolerance:
        return 0.0
    return 1.0

def check_docx_line_spacing__7eeaaa9132bab1b11296c7734630991c(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if document content matches expected text and has correct line spacing.

    Args:
        result: Dict with 'content' and 'line_spacing' from getter
        expected: Dict with 'expected_content' and 'expected_line_spacing'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    expected_content = expected.get('expected_content', '')
    expected_line_spacing = expected.get('expected_line_spacing', None)
    result_content = result.get('content', '')
    result_line_spacing = result.get('line_spacing', None)
    if result_content and expected_content:
        result_normalized = ' '.join(result_content.split())
        expected_normalized = ' '.join(expected_content.split())
        if result_normalized == expected_normalized:
            score += 0.5
        else:
            from rapidfuzz import fuzz
            similarity = fuzz.ratio(result_normalized, expected_normalized) / 100.0
            if similarity >= 0.95:
                score += 0.5
    if result_line_spacing is not None and expected_line_spacing is not None:
        tolerance = options.get('spacing_tolerance', 0.1)
        if abs(result_line_spacing - expected_line_spacing) <= tolerance:
            score += 0.5
    return score

