def check_docx_contains_keywords__d99037c6(result: str, expected: Any, **options) -> float:
    """
    Check if the document contains complete content from the presentation.

    This function performs comprehensive verification to ensure complete extraction:
    1. Checks for all required keywords (representing different slides/sections)
    2. Verifies minimum content volume (character and word count)
    3. Ensures content structure is preserved (not just isolated keywords)

    Args:
        result: Text content from getter
        expected: Dict with 'keywords' list and optional thresholds
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 based on completeness checks
    """
    if not isinstance(expected, dict):
        logger.error(f'Expected should be a dict, got {type(expected)}')
        return 0.0
    keywords = expected.get('keywords', [])
    if not keywords:
        logger.warning('No keywords provided')
        return 1.0
    result_text = result.strip()
    result_lower = result_text.lower()
    if not result_text:
        logger.error('Extracted content is empty')
        return 0.0
    keyword_matches = sum((1 for keyword in keywords if keyword.lower() in result_lower))
    keyword_score = keyword_matches / len(keywords)
    logger.info(f'Keyword coverage: {keyword_matches}/{len(keywords)} keywords found')
    char_count = len(result_text)
    word_count = len(result_text.split())
    min_chars = 500
    min_words = 80
    char_ratio = min(char_count / min_chars, 1.0)
    word_ratio = min(word_count / min_words, 1.0)
    volume_score = (char_ratio + word_ratio) / 2.0
    logger.info(f'Content volume: {char_count} chars (threshold: {min_chars}), {word_count} words (threshold: {min_words})')
    logger.info(f'Volume score: {volume_score:.2f}')
    contextual_keywords = 0
    for keyword in keywords:
        keyword_lower = keyword.lower()
        idx = result_lower.find(keyword_lower)
        if idx != -1:
            start = max(0, idx - 20)
            end = min(len(result_text), idx + len(keyword) + 20)
            context_window = result_text[start:end]
            context_words = context_window.split()
            if len(context_words) >= 4:
                contextual_keywords += 1
    structure_score = contextual_keywords / len(keywords) if keywords else 0.0
    logger.info(f'Content structure: {contextual_keywords}/{len(keywords)} keywords appear in context')
    final_score = keyword_score * 0.3 + volume_score * 0.4 + structure_score * 0.3
    logger.info(f'Final score breakdown - Keywords: {keyword_score:.2f} (30%), Volume: {volume_score:.2f} (40%), Structure: {structure_score:.2f} (30%)')
    logger.info(f'Final score: {final_score:.2f}')
    return final_score

def check_spacing_para_task__c7d445f7(docx_file, expected, **options):
    """Check line spacing for three paragraphs.

    This function verifies that each paragraph has the expected line spacing.
    Expected spacing values: para0=1.5, para1=1.5, para2=1.5

    Args:
        docx_file: Path to the docx file
        expected: Dict with para0, para1, para2 spacing values
        **options: Additional options (tolerance for floating point comparison)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    if len(doc.paragraphs) < 3:
        logger.error(f'Document has {len(doc.paragraphs)} paragraphs, expected at least 3')
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    expected_para0 = expected.get('para0', 1.5)
    expected_para1 = expected.get('para1', 1.5)
    expected_para2 = expected.get('para2', 1.5)
    spacing0 = doc.paragraphs[0].paragraph_format.line_spacing
    spacing1 = doc.paragraphs[1].paragraph_format.line_spacing
    spacing2 = doc.paragraphs[2].paragraph_format.line_spacing
    spacing0 = spacing0 if spacing0 is not None else 1.0
    spacing1 = spacing1 if spacing1 is not None else 1.0
    spacing2 = spacing2 if spacing2 is not None else 1.0
    logger.info(f'Paragraph 0 spacing: {spacing0} (expected: {expected_para0})')
    logger.info(f'Paragraph 1 spacing: {spacing1} (expected: {expected_para1})')
    logger.info(f'Paragraph 2 spacing: {spacing2} (expected: {expected_para2})')
    score = 0.0
    if abs(spacing0 - expected_para0) <= tolerance:
        score += 0.33
    if abs(spacing1 - expected_para1) <= tolerance:
        score += 0.34
    if abs(spacing2 - expected_para2) <= tolerance:
        score += 0.33
    return round(score, 2)

def check_header_contains_text__04b9a49cc6e250d3b0500ee9ab1220b4(result, expected, **options):
    """Check if header contains expected text in all sections.

    Args:
        result: Header text from getter (single string or pipe-separated sections)
        expected: Dictionary with 'text' key containing expected text

    Returns:
        float: 1.0 if ALL headers contain expected text, 0.0 otherwise
    """
    expected_text = expected.get('text', '')
    if not expected_text:
        logger.warning('No expected text provided')
        return 0.0
    if not result:
        logger.info('No header text found')
        return 0.0
    if ' | ' in result:
        headers = [h.strip() for h in result.split(' | ')]
        for header in headers:
            if expected_text.lower() not in header.lower():
                logger.info(f"Expected '{expected_text}' not found in section header: '{header}'")
                return 0.0
        return 1.0
    elif expected_text.lower() in result.lower():
        return 1.0
    else:
        logger.info(f"Expected '{expected_text}' not found in header: '{result}'")
        return 0.0

