def check_docx_content__888db799(result, expected, **options):
    """Compare docx file content against expected text.
    
    Args:
        result: Path to the docx file
        expected: Dict with 'expected_text' key containing the text to find
        **options: Additional comparison options
        
    Returns:
        float: 1.0 if expected text is found, 0.0 otherwise
    """
    ignore_case = options.get('ignore_case', True)
    fuzzy_match = options.get('fuzzy_match', True)
    if not result:
        return 0.0
    try:
        doc = Document(result)
        doc_text = '\n'.join([p.text for p in doc.paragraphs])
        expected_text = expected.get('expected_text', '')
        if not expected_text:
            return 0.0
        if ignore_case:
            doc_text_normalized = doc_text.lower()
            expected_normalized = expected_text.lower()
        else:
            doc_text_normalized = doc_text
            expected_normalized = expected_text
        doc_text_normalized = re.sub('\\s+', ' ', doc_text_normalized).strip()
        expected_normalized = re.sub('\\s+', ' ', expected_normalized).strip()
        if expected_normalized in doc_text_normalized:
            return 1.0
        if fuzzy_match:
            doc_alphanum = re.sub('[^a-z0-9]', '', doc_text_normalized)
            expected_alphanum = re.sub('[^a-z0-9]', '', expected_normalized)
            if expected_alphanum in doc_alphanum:
                return 1.0
        return 0.0
    except Exception as e:
        print(f'Error checking docx content: {e}')
        return 0.0

