def check_docx_font_size__5c683b3f(docx_file, rules: dict):
    """Check if all text in the document has the specified font size.

    Args:
        docx_file: Path to the DOCX file
        rules: Dictionary with 'font_size' key specifying the expected font size in pt

    Returns:
        float: 1.0 if all text has the expected font size, 0.0 otherwise
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error opening document: {e}')
        return 0.0
    expected_size = rules.get('font_size')
    if expected_size is None:
        logger.error('No font_size specified in rules')
        return 0.0
    for paragraph in doc.paragraphs:
        for run in paragraph.runs:
            if run.font.size is None:
                logger.info(f'Found run with no explicit font size (using default)')
                return 0.0
            actual_size_pt = run.font.size.pt
            if actual_size_pt != expected_size:
                logger.info(f'Expected font size {expected_size}pt, found {actual_size_pt}pt')
                return 0.0
    return 1.0

def check_highlighted_names__128ad09f(result: List[str], expected: Dict[str, Any], **options) -> float:
    """Check if the correct employees are highlighted.

    Args:
        result: List of highlighted employee names
        expected: Dict with 'names' (list of expected highlighted names)
        **options: Additional options

    Returns:
        float: 1.0 if all expected names are highlighted (allowing extras), partial score otherwise
    """
    if not result:
        return 0.0
    expected_names = expected.get('names', [])
    if not expected_names:
        return 0.0
    matched = 0
    for name in expected_names:
        if name in result:
            matched += 1
    score = matched / len(expected_names)
    return score

def check_sorted_and_highlighted__4d5ac959(result, expected, **options):
    """Check if data is sorted by marks (descending) and top 3 are highlighted.

    Args:
        result: Path to the result Excel file
        expected: Dict with 'sheet', 'sort_column', 'highlight_rows', 'highlight_color'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        wb = openpyxl.load_workbook(result, data_only=True)
        sheet_idx = expected.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        score = 0.0
        sort_col = expected.get('sort_column', 'C')
        marks = []
        for row_idx in range(2, 30):
            val = ws[f'{sort_col}{row_idx}'].value
            if isinstance(val, (int, float)):
                marks.append(val)
            else:
                marks.append(-999)
        is_sorted = all((marks[i] >= marks[i + 1] for i in range(len(marks) - 1)))
        if is_sorted:
            score += 0.5
            logger.info('Data is correctly sorted by marks (descending)')
        else:
            logger.warning('Data is NOT sorted correctly')
        highlight_rows = expected.get('highlight_rows', [2, 3, 4])
        highlighted_count = 0
        for row_idx in highlight_rows:
            cell = ws[f'B{row_idx}']
            fill = cell.fill
            if fill and fill.start_color and fill.start_color.rgb:
                color = fill.start_color.rgb
                if isinstance(color, str) and len(color) == 8:
                    (r, g, b) = (int(color[2:4], 16), int(color[4:6], 16), int(color[6:8], 16))
                    if r > 200 and g > 200 and (b < 100):
                        highlighted_count += 1
        if highlighted_count == len(highlight_rows):
            score += 0.5
            logger.info(f'All {len(highlight_rows)} top rows are highlighted')
        else:
            partial = 0.5 * (highlighted_count / len(highlight_rows))
            score += partial
            logger.warning(f'Only {highlighted_count}/{len(highlight_rows)} rows highlighted, partial score')
        return score
    except Exception as e:
        logger.error(f'Error checking sorted and highlighted: {e}')
        return 0.0

