def check_docx_formatted_words__6c41f61d(result_file, expected, **options):
    """
    Check if words matching the filter have the correct formatting.

    Args:
        result_file: Path to the result .docx file
        expected: Expected value with rules configuration
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 based on formatting correctness
    """
    if not result_file:
        return 0.0
    try:
        doc = Document(result_file)
    except Exception:
        return 0.0
    rules = expected if isinstance(expected, dict) else {}
    target_letters = rules.get('target_letters', ['b', 't', 'w'])
    format_type = rules.get('format_type', 'bold')
    expected_count = rules.get('expected_count', 18)
    target_letters = [letter.lower() for letter in target_letters]

    def should_format(word):
        """Check if a word should be formatted based on its first letter."""
        if not word:
            return False
        return word[0].lower() in target_letters

    def extract_words_with_formatting(text, run):
        """Extract individual words from run text and track their formatting."""
        words = re.findall('\\b\\w+\\b', text)
        return [(word, run.bold) for word in words]
    matching_words_formatted_correctly = 0
    matching_words_total = 0
    for paragraph in doc.paragraphs:
        for run in paragraph.runs:
            words_with_format = extract_words_with_formatting(run.text, run)
            for (word, is_bold) in words_with_format:
                if should_format(word):
                    matching_words_total += 1
                    if format_type == 'bold' and is_bold:
                        matching_words_formatted_correctly += 1
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    for run in paragraph.runs:
                        words_with_format = extract_words_with_formatting(run.text, run)
                        for (word, is_bold) in words_with_format:
                            if should_format(word):
                                matching_words_total += 1
                                if format_type == 'bold' and is_bold:
                                    matching_words_formatted_correctly += 1
    for section in doc.sections:
        header = section.header
        for paragraph in header.paragraphs:
            for run in paragraph.runs:
                words_with_format = extract_words_with_formatting(run.text, run)
                for (word, is_bold) in words_with_format:
                    if should_format(word):
                        matching_words_total += 1
                        if format_type == 'bold' and is_bold:
                            matching_words_formatted_correctly += 1
        footer = section.footer
        for paragraph in footer.paragraphs:
            for run in paragraph.runs:
                words_with_format = extract_words_with_formatting(run.text, run)
                for (word, is_bold) in words_with_format:
                    if should_format(word):
                        matching_words_total += 1
                        if format_type == 'bold' and is_bold:
                            matching_words_formatted_correctly += 1
    if matching_words_total == 0:
        return 0.0
    if matching_words_total != expected_count:
        if matching_words_formatted_correctly == matching_words_total:
            count_accuracy = min(matching_words_total, expected_count) / max(matching_words_total, expected_count)
            return count_accuracy * 0.8
    if matching_words_formatted_correctly == matching_words_total == expected_count:
        return 1.0
    formatting_accuracy = matching_words_formatted_correctly / matching_words_total
    return formatting_accuracy

def check_reference_count__65fd6a6a(result, expected, **options):
    """Check if reference count matches expected value.

    Args:
        result: Reference count from getter (int)
        expected: Expected count or range dict
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if isinstance(expected, dict):
        expected_count = expected.get('count')
        min_count = expected.get('min')
        max_count = expected.get('max')
        if expected_count is not None:
            if result == expected_count:
                logger.info(f'✓ Reference count matches: {result}')
                return 1.0
            else:
                logger.warning(f'✗ Reference count mismatch: expected {expected_count}, got {result}')
                return 0.0
        elif min_count is not None or max_count is not None:
            min_c = min_count if min_count is not None else 0
            max_c = max_count if max_count is not None else float('inf')
            if min_c <= result <= max_c:
                logger.info(f'✓ Reference count in range: {result} in [{min_c}, {max_c}]')
                return 1.0
            else:
                logger.warning(f'✗ Reference count out of range: {result} not in [{min_c}, {max_c}]')
                return 0.0
