def check_docx_content__a6b53d3d(result: Optional[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """Check if .docx file exists with correct filename and contains Tab Bars content.

    Args:
        result: Dict with 'filename', 'content', 'has_content' from getter
        expected: Rules dict with 'filename' and 'keywords' keys
        **options: Additional options

    Returns:
        1.0 if all checks pass, partial score otherwise
    """
    if result is None:
        return 0.0
    score = 0.0
    expected_filename = expected.get('filename', '')
    if result.get('filename') == expected_filename:
        score += 0.4
    if result.get('has_content', False):
        score += 0.2
    content = result.get('content', '').lower()
    keywords = expected.get('keywords', [])
    if not keywords:
        keywords = ['tab bar', 'navigation', 'tab', 'apple', 'ios']
    keyword_matches = 0
    for keyword in keywords:
        if keyword.lower() in content:
            keyword_matches += 1
    if len(keywords) > 0:
        if keyword_matches >= 2:
            keyword_score = min(1.0, keyword_matches / len(keywords))
            score += 0.4 * keyword_score
    return min(1.0, score)

