def check_docx_landscape_and_image__262d903a(result, expected, **options):
    """
    Check if ODT document has landscape orientation and contains an image.

    Args:
        result: Path to the ODT file
        expected: Dict with rules specifying has_image and orientation
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 (0.5 for orientation only, 1.0 for both)
    """
    if not result:
        logger.error('Result file path is None')
        return 0.0
    expected_has_image = expected.get('has_image', True)
    expected_orientation = expected.get('orientation', 'landscape')
    try:
        doc = load(result)
    except Exception as e:
        logger.error(f'Error loading ODT file: {e}')
        return 0.0
    score = 0.0
    frames = doc.getElementsByType(Frame)
    has_image = len(frames) > 0
    if has_image == expected_has_image:
        score += 0.5
        logger.info(f'Image presence check passed: {has_image}')
    else:
        logger.error(f'Image presence mismatch: expected {expected_has_image}, got {has_image}')
    page_orientation_found = False
    for style in doc.automaticstyles.childNodes:
        if hasattr(style, 'getAttribute'):
            for child in style.childNodes:
                if hasattr(child, 'getAttribute') and hasattr(child, 'qname'):
                    if 'page-layout-properties' in str(child.qname):
                        orientation = child.getAttribute('printorientation')
                        if orientation and orientation.lower() == expected_orientation.lower():
                            score += 0.5
                            page_orientation_found = True
                            logger.info(f'Page orientation check passed: {orientation}')
                            break
        if page_orientation_found:
            break
    if not page_orientation_found:
        logger.warning(f"Page orientation '{expected_orientation}' not found in document")
    logger.info(f'Final score: {score}')
    return score

def check_page_number_italic__f2dc9ee3(pptx_file, rules):
    """Check if slide page numbers in master slide are formatted as italic."""
