def check_page_number_colors__d1fb9f73(pptx_file, rules):
    """
    Check if the slide page numbers have been changed to the expected color.

    Args:
        pptx_file: Path to the PPTX file
        rules: Dict with 'color' key (e.g., 'blue', 'red', 'green', 'black')

    Returns:
        float: 1.0 if color matches, 0.0 otherwise
    """
    color = rules['color']

    def is_red(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[1:3], 16), int(rgb_str[3:5], 16), int(rgb_str[5:7], 16))
        return r > g + threshold and r > b + threshold

    def is_blue(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[1:3], 16), int(rgb_str[3:5], 16), int(rgb_str[5:7], 16))
        return b > g + threshold and b > r + threshold

    def is_green(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[1:3], 16), int(rgb_str[3:5], 16), int(rgb_str[5:7], 16))
        return g > r + threshold and g > b + threshold

    def is_black(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[1:3], 16), int(rgb_str[3:5], 16), int(rgb_str[5:7], 16))
        return r < threshold and g < threshold and (b < threshold)
    try:
        with zipfile.ZipFile(pptx_file, 'r') as zip_ref:
            slide_master_name = 'ppt/slideMasters/slideMaster1.xml'
            with zip_ref.open(slide_master_name) as slide_master_file:
                tree = ET.parse(slide_master_file)
                root = tree.getroot()
                namespaces = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main', 'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}
                slides_color_val = None
                for sp in root.findall('.//p:sp', namespaces):
                    ph = sp.find('.//p:ph[@type="sldNum"]', namespaces)
                    if ph is not None:
                        color_elem = sp.find('.//a:solidFill/a:srgbClr', namespaces)
                        if color_elem is not None:
                            slides_color_val = color_elem.get('val')
                            break
                if slides_color_val is None:
                    for sp in root.findall('.//p:sp', namespaces):
                        ph = sp.find('.//p:ph[@type="ftr"]', namespaces)
                        if ph is not None:
                            color_elem = sp.find('.//a:solidFill/a:srgbClr', namespaces)
                            if color_elem is not None:
                                slides_color_val = color_elem.get('val')
                                break
                if slides_color_val is None:
                    return 0.0
    except (KeyError, IndexError, ET.ParseError, zipfile.BadZipFile) as e:
        return 0.0
    if color == 'red' and (not is_red(slides_color_val)):
        return 0.0
    elif color == 'blue' and (not is_blue(slides_color_val)):
        return 0.0
    elif color == 'green' and (not is_green(slides_color_val)):
        return 0.0
    elif color == 'black' and (not is_black(slides_color_val)):
        return 0.0
    return 1.0

