def check_pdf_page_count__25fc85ee(result, expected, **options):
    """Check if PDF page count matches and content is valid.

    Args:
        result: Dict from getter containing 'page_count', 'word_count', 'text_content', 'file_size', 'metadata'
        expected: Expected values (dict with 'page_count' key)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 based on verification checks
    """
    if result is None:
        return 0.0
    expected_count = expected.get('page_count', 0)
    key_phrases = ['Recruitment', 'retention', 'health professional', 'Europe']
    score = 0.0
    total_checks = 5
    if abs(result.get('page_count', 0) - expected_count) <= 2:
        score += 0.3
    word_count = result.get('word_count', 0)
    if 7500 <= word_count <= 9500:
        score += 0.2
    file_size = result.get('file_size', 0)
