def check_text_italic__473ada19(result_file, expected, **options):
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        shape_idx = expected.get('shape_idx', 0)
        expected_italic = expected.get('is_italic', False)
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            return 0.0
        shape = slide.shapes[shape_idx]
        if not hasattr(shape, 'text_frame'):
            return 0.0
        for para in shape.text_frame.paragraphs:
            for run in para.runs:
                if expected_italic and run.font.italic is not True:
                    return 0.0
                elif not expected_italic and run.font.italic is True:
                    return 0.0
        return 1.0
    except:
        return 0.0

