def check_paragraph_alignment__ec37ce48c7fd59c111261bffeda136d2(docx_file, expected, **options):
    """Check if all paragraphs in the document have the expected alignment.

    Args:
        docx_file: BytesIO or path to the .docx file
        expected: Dict with 'alignment' key ('left', 'center', 'right', 'justify')
        **options: Additional options

    Returns:
        float: 1.0 if all paragraphs have the expected alignment, 0.0 otherwise
    """
    if not docx_file:
        logger.error('No docx file provided')
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    alignment_str = expected.get('alignment', 'center')
    alignment_map = {'left': WD_PARAGRAPH_ALIGNMENT.LEFT, 'center': WD_PARAGRAPH_ALIGNMENT.CENTER, 'right': WD_PARAGRAPH_ALIGNMENT.RIGHT, 'justify': WD_PARAGRAPH_ALIGNMENT.JUSTIFY}
    expected_alignment = alignment_map.get(alignment_str.lower())
    if expected_alignment is None:
        logger.error(f'Invalid alignment: {alignment_str}')
        return 0.0
    for paragraph in doc.paragraphs:
        if paragraph.text.strip():
            para_alignment = paragraph.alignment
            if para_alignment != expected_alignment:
                logger.debug(f'Found alignment {para_alignment}, expected {expected_alignment}')
                return 0.0
    return 1.0

