def check_paragraph_highlighted__de7ac11c(docx_file, expected, **options):
    """Check if a specific paragraph is highlighted with the expected color.

    Args:
        docx_file: Path to the DOCX file
        expected: Expected state (dict with 'paragraph_index' and optional 'highlight_color')
        **options: Additional options

    Returns:
        float: 1.0 if paragraph is highlighted as expected, 0.0 otherwise
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    para_index = expected.get('paragraph_index', 0)
    expected_color = expected.get('highlight_color', 'yellow')
    if para_index >= len(doc.paragraphs):
        logger.error(f'Paragraph index {para_index} out of range (document has {len(doc.paragraphs)} paragraphs)')
        return 0.0
    target_para = doc.paragraphs[para_index]
    if not target_para.runs:
        logger.error(f'Paragraph {para_index} has no runs')
        return 0.0
    namespaces = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
    has_highlight = False
    for run in target_para.runs:
        if not run.text.strip():
            continue
        highlight_elems = run.element.findall('.//w:highlight', namespaces)
        for highlight in highlight_elems:
            color = highlight.get('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}val')
            if color and color.lower() == expected_color.lower():
                has_highlight = True
                break
        if has_highlight:
            break
    if has_highlight:
        return 1.0
    else:
        logger.info(f'No {expected_color} highlight found in paragraph {para_index}')
        return 0.0

