def check_bold_long_words__519b2394782587cf0953c6f72e80b8a6(result, expected, **options):
    """
    Check if words with 3+ letters are bolded in tables.

    Since DOCX formatting is applied at the run level (not per word), this function
    categorizes runs based on their content:
    - Runs with ONLY long words (all >= min_length) should be bold
    - Runs with ONLY short words (all < min_length) should NOT be bold
    - Mixed runs (both long and short words) are checked based on character majority

    Args:
        result: File path to the DOCX file
        expected: Rules dict with 'min_length' key
        **options: Additional options

    Returns:
        float: 1.0 if all words >= min_length are bold, 0.0 otherwise
    """
    if not result:
        return 0.0
    min_length = expected.get('min_length', 3)
    try:
        document = Document(result)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    for table in document.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    for run in paragraph.runs:
                        words = [w.strip() for w in run.text.split() if w.strip()]
                        if not words:
                            continue
                        long_words = [w for w in words if len(w) >= min_length]
                        short_words = [w for w in words if len(w) < min_length]
                        if long_words and (not short_words):
                            if not run.font.bold:
                                logger.info(f'Run with only long words {long_words} should be bold but is not')
                                return 0.0
                        elif short_words and (not long_words):
                            if run.font.bold:
                                logger.info(f'Run with only short words {short_words} should not be bold but is')
                                return 0.0
                        else:
                            long_chars = sum((len(w) for w in long_words))
                            short_chars = sum((len(w) for w in short_words))
                            if long_chars > short_chars:
                                if not run.font.bold:
                                    logger.info(f'Run with majority long words {words} should be bold but is not')
                                    return 0.0
                            elif run.font.bold:
                                logger.info(f'Run with majority short words {words} should not be bold but is')
                                return 0.0
    return 1.0

def check_writer_default_font__198cadc92a7c0f92448049993b64b8f6(config_file_path, rules):
    """Check the default font setting in LibreOffice Writer for a specific property.

    This function reads the registrymodifications.xcu file and checks if the
    specified property in the DefaultFont configuration matches the expected value.

    Args:
        config_file_path: Path to the registrymodifications.xcu file
        rules: Dictionary containing:
            - config_path: XML path to the configuration section
            - prop_name: Name of the property to check
            - font_name: Expected font name value

    Returns:
        1 if the font matches the expected value, 0 otherwise
    """
    if not config_file_path:
        return 0
    config_path = rules.get('config_path', '/org.openoffice.Office.Writer/DefaultFont')
    prop_name = rules.get('prop_name', 'Caption')
    expected_font = rules.get('font_name')
    if not expected_font:
        logger.error('No expected font_name provided in rules')
        return 0
    actual_font = None
    try:
        tree = ET.parse(config_file_path)
        root = tree.getroot()
        namespace = {'oor': 'http://openoffice.org/2001/registry'}
        xpath = f'.//item[@oor:path="{config_path}"]'
        for elem in root.findall(xpath, namespace):
            prop_xpath = f'.//prop[@oor:name="{prop_name}"]'
            for prop in elem.findall(prop_xpath, namespace):
                for value in prop.findall('value', namespace):
                    actual_font = value.text
                    break
            if actual_font:
                break
    except Exception as e:
        logger.error(f'Error parsing config file: {e}')
        return 0
    return 1 if actual_font == expected_font else 0

def check_spacing_para_task__aa3c0097(docx_file, expected, **options):
    """Check line spacing for three paragraphs.

    This function verifies that each paragraph has the expected line spacing.
    Expected spacing values: para0=2.0, para1=2.0, para2=1.5

    Args:
        docx_file: Path to the docx file
        expected: Dict with para0, para1, para2 spacing values
        **options: Additional options (tolerance for floating point comparison)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    if len(doc.paragraphs) < 3:
        logger.error(f'Document has {len(doc.paragraphs)} paragraphs, expected at least 3')
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    expected_para0 = expected.get('para0', 2.0)
    expected_para1 = expected.get('para1', 2.0)
    expected_para2 = expected.get('para2', 1.5)
    spacing0 = doc.paragraphs[0].paragraph_format.line_spacing
    spacing1 = doc.paragraphs[1].paragraph_format.line_spacing
    spacing2 = doc.paragraphs[2].paragraph_format.line_spacing
    spacing0 = spacing0 if spacing0 is not None else 1.0
    spacing1 = spacing1 if spacing1 is not None else 1.0
    spacing2 = spacing2 if spacing2 is not None else 1.0
    logger.info(f'Paragraph 0 spacing: {spacing0} (expected: {expected_para0})')
    logger.info(f'Paragraph 1 spacing: {spacing1} (expected: {expected_para1})')
    logger.info(f'Paragraph 2 spacing: {spacing2} (expected: {expected_para2})')
    score = 0.0
    if abs(spacing0 - expected_para0) <= tolerance:
        score += 0.33
    if abs(spacing1 - expected_para1) <= tolerance:
        score += 0.34
    if abs(spacing2 - expected_para2) <= tolerance:
        score += 0.33
    return round(score, 2)

