def check_page_number_colors__ac9bb6cb(result_state, expected_state, **options):
    """
    Check if page number colors in PPTX match the specified color rule.

    This function searches for page number placeholders in slide masters by:
    1. Identifying slide number placeholders by type (not positional index)
    2. Extracting color from the actual page number placeholder
    3. Validating the color matches the expected rule

    Args:
        result_state: Path to the PPTX file (from vm_file getter)
        expected_state: Rules dict containing color specification (when expected.type="rule", the framework passes rules directly)
        **options: Additional options

    Returns:
        float: 1.0 if color matches, 0.0 otherwise
    """
    color = expected_state.get('color')
    if not color:
        logger.error('No color rule specified')
        return 0.0
    pptx_file = result_state

    def is_red(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[0:2], 16), int(rgb_str[2:4], 16), int(rgb_str[4:6], 16))
        return r > g + threshold and r > b + threshold

    def is_blue(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[0:2], 16), int(rgb_str[2:4], 16), int(rgb_str[4:6], 16))
        return b > g + threshold and b > r + threshold

    def is_green(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[0:2], 16), int(rgb_str[2:4], 16), int(rgb_str[4:6], 16))
        return g > r + threshold and g > b + threshold

    def is_black(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[0:2], 16), int(rgb_str[2:4], 16), int(rgb_str[4:6], 16))
        return r < threshold and g < threshold and (b < threshold)
    try:
        with zipfile.ZipFile(pptx_file, 'r') as zip_ref:
            namespaces = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main', 'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}
            slide_master_files = [f for f in zip_ref.namelist() if f.startswith('ppt/slideMasters/slideMaster') and f.endswith('.xml')]
            if not slide_master_files:
                logger.error('No slide master files found in PPTX')
                return 0.0
            slides_color_val = None
            for slide_master_name in slide_master_files:
                try:
                    with zip_ref.open(slide_master_name) as slide_master_file:
                        tree = ET.parse(slide_master_file)
                        root = tree.getroot()
                        for sp in root.findall('.//p:sp', namespaces):
                            nv_sp_pr = sp.find('.//p:nvSpPr', namespaces)
                            if nv_sp_pr is None:
                                continue
                            ph = nv_sp_pr.find('.//p:ph', namespaces)
                            if ph is None:
                                continue
                            ph_type = ph.get('type')
                            if ph_type == 'sldNum':
                                solid_fill = sp.find('.//a:solidFill', namespaces)
                                if solid_fill is not None:
                                    srgb_clr = solid_fill.find('.//a:srgbClr', namespaces)
                                    if srgb_clr is not None:
                                        slides_color_val = srgb_clr.get('val')
                                        logger.info(f'Found page number color in {slide_master_name}: {slides_color_val}')
                                        break
                        if slides_color_val is not None:
                            break
                except ET.ParseError as e:
                    logger.warning(f'Failed to parse {slide_master_name}: {e}')
                    continue
                except Exception as e:
                    logger.warning(f'Error processing {slide_master_name}: {e}')
                    continue
            if slides_color_val is None:
                logger.warning('Slide number placeholder not found by type, trying fallback approach')
                for slide_master_name in slide_master_files:
                    try:
                        with zip_ref.open(slide_master_name) as slide_master_file:
                            tree = ET.parse(slide_master_file)
                            root = tree.getroot()
                            color_elems = root.findall('.//a:solidFill//a:srgbClr', namespaces)
                            for color_elem in color_elems:
                                parent = color_elem
                                for _ in range(10):
                                    parent = parent.find('..')
                                    if parent is None:
                                        break
                                    text_elems = parent.findall('.//a:t', namespaces)
                                    for text_elem in text_elems:
                                        text = text_elem.text or ''
                                        if any((pattern in text.lower() for pattern in ['<number>', '<#>', 'number', '#'])):
                                            slides_color_val = color_elem.get('val')
                                            logger.info(f'Found potential page number color via text pattern: {slides_color_val}')
                                            break
                                    if slides_color_val is not None:
                                        break
                                if slides_color_val is not None:
                                    break
                        if slides_color_val is not None:
                            break
                    except Exception as e:
                        logger.warning(f'Fallback failed for {slide_master_name}: {e}')
                        continue
    except zipfile.BadZipFile:
        logger.error(f'Invalid PPTX file: {pptx_file}')
        return 0.0
    except FileNotFoundError:
        logger.error(f'PPTX file not found: {pptx_file}')
        return 0.0
    except Exception as e:
        logger.error(f'Unexpected error processing PPTX: {e}')
        return 0.0
    if slides_color_val is None:
        logger.error('Could not find page number color in any slide master')
        return 0.0
    if slides_color_val.startswith('#'):
        slides_color_val = slides_color_val[1:]
    if len(slides_color_val) != 6:
        logger.error(f'Invalid color format: {slides_color_val}')
        return 0.0
    try:
        if color == 'red' and (not is_red(slides_color_val)):
            return 0.0
        elif color == 'blue' and (not is_blue(slides_color_val)):
            return 0.0
        elif color == 'green' and (not is_green(slides_color_val)):
            return 0.0
        elif color == 'black' and (not is_black(slides_color_val)):
            return 0.0
    except ValueError as e:
        logger.error(f'Error parsing color value {slides_color_val}: {e}')
        return 0.0
    return 1.0

def check_docx_reverse_order__d62b618c18b762984a0245cb92f201ef(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if document content is in reverse order and has correct font size.

    Args:
        result: Dict with 'content' and 'font_size' from getter
        expected: Dict with list of 'expected_segments' (in reverse order) and 'expected_font_size'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    expected_segments = expected.get('expected_segments', [])
    expected_font_size = expected.get('expected_font_size', None)
    result_content = result.get('content', '')
    result_font_size = result.get('font_size', None)
    if result_content and expected_segments:
        result_normalized = ' '.join(result_content.split())
        segment_positions = []
        all_found = True
        for segment in expected_segments:
            segment_normalized = ' '.join(segment.split())
            position = result_normalized.find(segment_normalized)
            if position == -1:
                all_found = False
                break
            segment_positions.append(position)
        if all_found and len(segment_positions) == len(expected_segments):
            in_correct_order = all((segment_positions[i] < segment_positions[i + 1] for i in range(len(segment_positions) - 1)))
            if in_correct_order:
                score += 0.5
    if result_font_size is not None and expected_font_size is not None:
        tolerance = options.get('font_tolerance', 0.5)
        if abs(result_font_size - expected_font_size) <= tolerance:
            score += 0.5
    return score

