def check_docx_formatted_words__25742f44(result_file, expected, **options):
    """
    Check if words matching the filter have the correct formatting.
    Words starting with consonants should be bold.
    Words starting with vowels should NOT be bold.

    Args:
        result_file: Path to the result .docx file
        expected: Expected value (not used, filter is in code)
        **options: Additional options

    Returns:
        float: 1.0 if all matching words have correct formatting, 0.0 otherwise
    """
    if not result_file:
        return 0.0
    try:
        doc = Document(result_file)
    except Exception:
        return 0.0

    def starts_with_consonant(word):
        """Check if word starts with a consonant (not a vowel)."""
        if not word:
            return False
        first_char = word.lstrip('!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~').lower()
        if not first_char:
            return False
        return first_char[0] not in 'aeiou' and first_char[0].isalpha()

    def check_run_words(run):
        """
        Check if all words in a run have correct formatting.
        Split run.text into individual words and verify each one.

        Returns:
            bool: True if all words are correctly formatted, False otherwise
        """
        text = run.text
        if not text.strip():
            return True
        words = re.findall('\\S+', text)
        for word in words:
            clean_word = word.strip('!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~')
            if not clean_word or not any((c.isalpha() for c in clean_word)):
                continue
            if starts_with_consonant(word):
                if not run.bold:
                    return False
            elif run.bold:
                return False
        return True
    for paragraph in doc.paragraphs:
        for run in paragraph.runs:
            if not check_run_words(run):
                return 0.0
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    for run in paragraph.runs:
                        if not check_run_words(run):
                            return 0.0
    return 1.0

