def check_docx_min_locations__4613f264(result_file_path, expected, **options):
    """
    Check if document contains minimum number of library location entries in Chinese.
    Verifies that entries contain:
    - Chinese characters
    - Library-related keywords (图书馆)
    - Location keywords (福田/福田区/深圳)
    - Address-like patterns (路/街/区/号)

    Args:
        result_file_path: Path to the result DOCX file
        expected: Dict with 'min_count' - minimum required locations
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result_file_path is None:
        return 0.0
    min_count = expected.get('min_count', 3)
    try:
        doc = Document(result_file_path)
        valid_locations = []
        for para in doc.paragraphs:
            text = para.text.strip()
            if not text or len(text) <= 5:
                continue
            if not re.search('[\\u4e00-\\u9fff]', text):
                continue
            has_library_keyword = '图书馆' in text
            has_location_keyword = '福田' in text or '福田区' in text or '深圳' in text
            address_patterns = ['路', '街', '区', '号', '道', '巷', '里', '村', '镇', '市']
            has_address_pattern = any((pattern in text for pattern in address_patterns))
            if has_library_keyword and has_location_keyword:
                valid_locations.append(text)
            elif has_library_keyword and has_address_pattern:
                if has_location_keyword or len(text) > 15:
                    valid_locations.append(text)
        actual_count = len(valid_locations)
        if actual_count >= min_count:
            return 1.0
        elif actual_count > 0:
            return actual_count / min_count
        else:
            return 0.0
    except Exception as e:
        print(f'Error reading document: {e}')
        return 0.0

def check_docx_table_rows__d5cdfdb611de0d2892eeaddda9638ac9(result, expected, **options):
    """Check if DOCX table has the expected number of rows, columns, and cell values.

    Args:
        result: Table data as list of lists from getter
        expected: Dict with 'min_rows', 'max_rows', 'min_cols', 'check_first_col_values', and optional 'check_cell_values'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not isinstance(result, list):
        return 0.0
    min_rows = expected.get('min_rows', 0)
    max_rows = expected.get('max_rows', float('inf'))
    min_cols = expected.get('min_cols', 0)
    check_first_col = expected.get('check_first_col_values', [])
    check_cells = expected.get('check_cell_values', {})
    num_rows = len(result)
    if num_rows < min_rows or num_rows > max_rows:
        return 0.0
    if min_cols > 0:
        for row in result:
            if len(row) < min_cols:
                return 0.0
    score = 0.0
    checks_passed = 0
    total_checks = 0
    if check_first_col:
        total_checks += 1
        if num_rows != len(check_first_col):
            return 0.3
        matches = 0
        for (i, expected_val) in enumerate(check_first_col):
            if i < len(result) and len(result[i]) > 0:
                actual_val = result[i][0]
                try:
                    if isinstance(expected_val, (int, float)):
                        actual_val = float(actual_val) if '.' in str(actual_val) else int(actual_val)
                    if actual_val == expected_val:
                        matches += 1
                except (ValueError, TypeError):
                    pass
        if matches == len(check_first_col):
            checks_passed += 1
        elif matches >= len(check_first_col) * 0.8:
            checks_passed += 0.8
        else:
            checks_passed += 0.3
    if check_cells:
        total_checks += 1
        cell_matches = 0
        cell_total = 0
        for (cell_key, expected_val) in check_cells.items():
            try:
                (row_idx, col_idx) = map(int, cell_key.split('_'))
                cell_total += 1
                if row_idx < len(result) and col_idx < len(result[row_idx]):
                    actual_val = result[row_idx][col_idx]
                    try:
                        if isinstance(expected_val, (int, float)):
                            actual_val = float(actual_val) if '.' in str(actual_val) else int(actual_val)
                        if actual_val == expected_val:
                            cell_matches += 1
                    except (ValueError, TypeError):
                        if str(actual_val) == str(expected_val):
                            cell_matches += 1
            except (ValueError, IndexError):
                pass
        if cell_total > 0:
            cell_score = cell_matches / cell_total
            checks_passed += cell_score
    if total_checks == 0:
        return 1.0
    score = checks_passed / total_checks
    return score

