def check_googledoc_content__94b5cf43cb76d4d8e4ba44509051fb44(result: str, expected: Dict[str, Any], **options) -> float:
    """
    Check if Google Doc contains expected content with partial credit scoring.

    This metric validates document content by checking for required keywords/phrases
    and minimum length requirements.

    Args:
        result: Text content extracted from the Google Doc
        expected: Rules dict with:
            - required_keywords: List of keywords that must appear (case-insensitive)
            - min_length: Minimum character count (optional)
            - title_keywords: Keywords that should appear near the start (optional)
        **options: Additional options (not used currently)

    Returns:
        float: Score from 0.0 to 1.0:
            - 0.4: Document exists and has content
            - +0.3: Contains all required keywords
            - +0.2: Meets minimum length requirement (if specified)
            - +0.1: Title keywords appear in first 500 chars (if specified)
    """
    if not result or len(result.strip()) == 0:
        return 0.0
    score = 0.0
    result_lower = result.lower()
    score += 0.4
    required_keywords = expected.get('required_keywords', [])
    if required_keywords:
        keywords_found = sum((1 for kw in required_keywords if kw.lower() in result_lower))
        keyword_ratio = keywords_found / len(required_keywords)
        score += 0.3 * keyword_ratio
    else:
        score += 0.3
    min_length = expected.get('min_length', 0)
    if min_length > 0:
        if len(result) >= min_length:
            score += 0.2
    else:
        score += 0.2
    title_keywords = expected.get('title_keywords', [])
    if title_keywords:
        first_section = result_lower[:500]
        title_found = sum((1 for kw in title_keywords if kw.lower() in first_section))
        title_ratio = title_found / len(title_keywords)
        score += 0.1 * title_ratio
    else:
        score += 0.1
    return min(score, 1.0)

def check_docx_locations__25fcf78bbfb733a8542c085e50029d87(result_file_path, expected, **options):
    """
    Check if the Word document contains at least 5 locations from the expected list.
    Uses fuzzy matching to handle minor variations in location names.

    Args:
        result_file_path: Path to the .docx file
        expected: Dict with 'locations' key containing list of expected location names
        **options: Additional options (e.g., threshold for fuzzy matching)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result_file_path is None:
        return 0.0
    expected_locations = expected.get('locations', [])
    min_count = expected.get('min_count', 5)
    fuzzy_threshold = options.get('fuzzy_threshold', 80)
    if not expected_locations:
        return 0.0
    try:
        doc = Document(result_file_path)
    except Exception:
        return 0.0
    doc_text = []
    for para in doc.paragraphs:
        if para.text.strip():
            doc_text.append(para.text.strip())
    found_count = 0
    for location in expected_locations:
        found = False
        for para_text in doc_text:
            score = fuzz.partial_ratio(location, para_text)
            if score >= fuzzy_threshold:
                found = True
                break
        if found:
            found_count += 1
    if found_count >= min_count:
        return 1.0
    else:
        return found_count / min_count

