def check_docx_title_case__375fb1715f410e32af34093a0207c904(result, expected, **options):
    """Check if specific paragraphs are in title case.

    Args:
        result: List of paragraph texts from getter
        expected: Dict with 'paragraph_indices' list and 'should_be_title_case' bool
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not isinstance(result, list):
        return 0.0
    paragraph_indices = expected.get('paragraph_indices', [])
    should_be_title_case = expected.get('should_be_title_case', True)
    if not paragraph_indices:
        return 0.0
    total_checks = 0
    correct_count = 0
    for idx in paragraph_indices:
        if idx >= len(result):
            continue
        text = result[idx]
        if not text or not text.strip():
            continue
        total_checks += 1
        is_title_case = text == text.title()
        if should_be_title_case and is_title_case:
            correct_count += 1
        elif not should_be_title_case and (not is_title_case):
            correct_count += 1
    if total_checks == 0:
        return 0.0
    return correct_count / total_checks

