def check_font_size__aa5a09c1(result, expected, **options):
    """Check if all text runs have the specified font size.

    Args:
        result: Path to the docx file
        expected: Expected rules (font_size in points)
        **options: Additional options

    Returns:
        float: 1.0 if all text runs have the specified font size, 0.0 otherwise
    """
    if not result:
        return 0.0
    try:
        doc = Document(result)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    expected_size = expected.get('font_size', 14)
    for para in doc.paragraphs:
        for run in para.runs:
            if run.text.strip():
                if run.font.size is None:
                    logger.info(f"Run has no font size set: '{run.text[:30]}...'")
                    return 0.0
                actual_size = run.font.size.pt
                if abs(actual_size - expected_size) > 0.1:
                    logger.info(f"Run has wrong font size {actual_size}pt (expected {expected_size}pt): '{run.text[:30]}...'")
                    return 0.0
    return 1.0

def check_text_underline__4267f9ef(pptx_file, rules):
    """
    Check if text in a specific shape has underline formatting applied.

    Args:
        pptx_file: Path to the PPTX file
        rules: Dict with 'slide_idx' (0-indexed), 'shape_idx' (0-indexed), and 'underline' (True/False)

    Returns:
        float: 1.0 if underline formatting matches, 0.0 otherwise
    """
    try:
        prs = Presentation(pptx_file)
        slide_idx = rules.get('slide_idx', 0)
        shape_idx = rules.get('shape_idx', 0)
        expected_underline = rules.get('underline', True)
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            return 0.0
        shape = slide.shapes[shape_idx]
        if not hasattr(shape, 'text_frame'):
            return 0.0
        if len(shape.text_frame.paragraphs) == 0:
            return 0.0
        all_underline = True
        has_runs = False
        for para in shape.text_frame.paragraphs:
            for run in para.runs:
                has_runs = True
                is_underlined = run.font.underline is True
                if expected_underline and (not is_underlined):
                    all_underline = False
                    break
                elif not expected_underline and is_underlined:
                    all_underline = False
                    break
            if not all_underline:
                break
        if not has_runs:
            return 0.0
        if all_underline:
            return 1.0
        else:
            return 0.0
    except Exception as e:
        return 0.0

def check_paragraph_font_size__ed684a43(docx_file, expected, **options):
    """Check if a specific paragraph has the expected font size.

    Args:
        docx_file: Path to the DOCX file
        expected: Expected state (dict with 'paragraph_index' and 'font_size_pt')
        **options: Additional options

    Returns:
        float: 1.0 if paragraph has expected font size, 0.0 otherwise
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    para_index = expected.get('paragraph_index', 0)
    expected_size = expected.get('font_size_pt', 12)
    if para_index >= len(doc.paragraphs):
        logger.error(f'Paragraph index {para_index} out of range (document has {len(doc.paragraphs)} paragraphs)')
        return 0.0
    target_para = doc.paragraphs[para_index]
    if not target_para.runs:
        logger.error(f'Paragraph {para_index} has no runs')
        return 0.0
    for run in target_para.runs:
        if not run.text.strip():
            continue
        if run.font.size is None:
            logger.info(f'Run has no font size set (using default)')
            return 0.0
        actual_size = run.font.size.pt
        if abs(actual_size - expected_size) > 0.5:
            logger.info(f'Font size mismatch: expected {expected_size}pt, got {actual_size}pt')
            return 0.0
    return 1.0

