def check_docx_starts_with__58218903(result: Dict[str, Any], expected: Any, **options) -> float:
    """
    Check if DOCX contains all expected text content from slides.

    Args:
        result: Dict from getter with all_text, paragraphs, paragraph_count, first_line
        expected: Dict with required content keys:
            - title: Expected title (first line)
            - key_phrases: List of key phrases that must be present (from multiple slides)
            - min_paragraphs: Minimum expected paragraph count
        **options: Additional options

    Returns:
        float: Score from 0.0 to 1.0 based on content verification
    """
    if not isinstance(result, dict):
        logger.error(f'Result should be a dict, got {type(result)}')
        return 0.0
    if not isinstance(expected, dict):
        logger.error(f'Expected should be a dict, got {type(expected)}')
        return 0.0
    all_text = result.get('all_text', '').lower()
    first_line = result.get('first_line', '').lower()
    paragraph_count = result.get('paragraph_count', 0)
    score = 0.0
    max_points = 0.0
    expected_title = expected.get('title', '')
    if expected_title:
        max_points += 0.3
        if expected_title.lower() in first_line:
            score += 0.3
            logger.info(f'✓ Title found in first line')
        else:
            logger.warning(f"✗ Title '{expected_title}' not found in first line: {first_line[:100]}")
    key_phrases = expected.get('key_phrases', [])
    if key_phrases:
        max_points += 0.5
        phrases_found = 0
        for phrase in key_phrases:
            if phrase.lower() in all_text:
                phrases_found += 1
                logger.info(f'✓ Key phrase found: {phrase}')
            else:
                logger.warning(f'✗ Key phrase not found: {phrase}')
        if len(key_phrases) > 0:
            phrase_score = phrases_found / len(key_phrases) * 0.5
            score += phrase_score
    min_paragraphs = expected.get('min_paragraphs', 0)
    if min_paragraphs > 0:
        max_points += 0.2
        if paragraph_count >= min_paragraphs:
            score += 0.2
            logger.info(f'✓ Paragraph count sufficient: {paragraph_count} >= {min_paragraphs}')
        else:
            logger.warning(f'✗ Insufficient paragraphs: {paragraph_count} < {min_paragraphs}')
    if max_points > 0:
        final_score = score / max_points
    else:
        final_score = 1.0 if expected_title.lower() in first_line else 0.0
    logger.info(f'Final score: {final_score:.2f} (points: {score:.2f}/{max_points:.2f})')
    return final_score

def check_page_number_color_yellow__f4a29c21(pptx_file, rules):
    """Check if slide numbers are colored yellow.

    Args:
        pptx_file: Path to the PPTX file
        rules: Dictionary with 'color' key (expected: 'yellow')

    Returns:
        1.0 if slide numbers are yellow, 0.0 otherwise
    """
    color = rules['color']

    def is_yellow(rgb_str, threshold=50):
        (r, g, b) = (int(rgb_str[1:3], 16), int(rgb_str[3:5], 16), int(rgb_str[5:7], 16))
        return r > 200 and g > 200 and (b < 100)
    with zipfile.ZipFile(pptx_file, 'r') as zip_ref:
        slide_master_name = 'ppt/slideMasters/slideMaster1.xml'
        with zip_ref.open(slide_master_name) as slide_master_file:
            tree = ET.parse(slide_master_file)
            root = tree.getroot()
            namespaces = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main', 'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}
            color_elems = root.findall('.//a:solidFill//a:srgbClr', namespaces)
            for color_elem in color_elems:
                rgb_val = color_elem.get('val')
                if rgb_val and is_yellow(rgb_val):
                    return 1.0
    return 0.0

