def check_default_paragraph_font__74864ed1840d0adbce3a5793ada3d47f(config_file_path, rules):
    """Check the default paragraph font in LibreOffice Writer configuration.

    Args:
        config_file_path: Path to registrymodifications.xcu file
        rules: Dictionary with font_name (str) key

    Returns:
        float: 1.0 if default paragraph font matches expected, 0.0 otherwise
    """
    default_font = None
    expected_font = rules['font_name']
    if not config_file_path:
        return 0.0
    try:
        tree = ET.parse(config_file_path)
        root = tree.getroot()
        namespace = {'oor': 'http://openoffice.org/2001/registry'}
        for elem in root.findall('.//item[@oor:path="/org.openoffice.Office.Writer/DefaultFont"]', namespace):
            for prop in elem.findall('.//prop[@oor:name="Standard"]', namespace):
                for value in prop.findall('value', namespace):
                    default_font = value.text
    except Exception as e:
        logger.error(f'Error parsing config file: {e}')
        return 0.0
    return 1.0 if default_font == expected_font else 0.0

def check_docx_keywords__fdea30d2(result_file_path, rules):
    """
    Check if a DOCX file contains required keywords.
    
    Args:
        result_file_path: Path to the DOCX file to check
        rules: Dict with 'keywords' (list of required keywords) and 'min_matches' (minimum number of keywords to find)
        
    Returns:
        float: 1.0 if min_matches keywords are found, 0.0 otherwise
    """
    if result_file_path is None:
        return 0.0
    keywords = rules.get('keywords', [])
    min_matches = rules.get('min_matches', len(keywords))
    doc = Document(result_file_path)
    full_text = []
    for para in doc.paragraphs:
        full_text.append(para.text)
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                full_text.append(cell.text)
    document_text = ' '.join(full_text)
    matches = 0
    for keyword in keywords:
        if keyword in document_text:
            matches += 1
    if matches >= min_matches:
        return 1.0
    else:
        return 0.0

def check_paragraph_center_alignment__5a1822be(docx_file, expected):
    """
    Check if a specific paragraph with given text is center-aligned.

    Args:
        docx_file: Path to the DOCX file
        expected: Dict with 'target_text' key containing the text to find

    Returns:
        float: 1.0 if paragraph with target text is centered, 0.0 otherwise
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error opening document: {e}')
        return 0.0
    target_text = expected.get('target_text', '')
    if not target_text:
        logger.error('No target_text specified in expected')
        return 0.0
    for para in doc.paragraphs:
        if target_text in para.text:
            if para.paragraph_format.alignment == WD_PARAGRAPH_ALIGNMENT.CENTER:
                return 1.0
            else:
                logger.info(f"Found paragraph with '{target_text}' but not centered (alignment: {para.paragraph_format.alignment})")
