def check_default_font_size__d0ed15c8(config_file_path, rules):
    """Check the default font size in LibreOffice Writer (variation 7: 11pt)."""
    default_size = None
    expected_size = str(rules['font_size'])
    if not config_file_path:
        return 0
    try:
        tree = ET.parse(config_file_path)
        root = tree.getroot()
        namespace = {'oor': 'http://openoffice.org/2001/registry'}
        for elem in root.findall('.//item[@oor:path="/org.openoffice.Office.Writer/DefaultFont"]', namespace):
            for prop in elem.findall('.//prop[@oor:name="StandardHeight"]', namespace):
                for value in prop.findall('value', namespace):
                    default_size = value.text
    except Exception as e:
        logger.error(f'Error: {e}')
    return 1 if default_size == expected_size else 0

def check_para_underline__b0815a9a(result, expected, **options):
    """Check if all text in a specific paragraph is underlined.

    Args:
        result: Path to the docx file
        expected: Dict with 'para_index' and 'must_be_underlined'
        **options: Additional options

    Returns:
        float: 1.0 if all text is underlined, 0.0 otherwise
    """
    if not result:
        return 0.0
    try:
        doc = Document(result)
    except Exception as e:
        logger.error(f'Error opening document: {e}')
        return 0.0
    para_index = expected.get('para_index', 6)
    must_be_underlined = expected.get('must_be_underlined', True)
    if para_index >= len(doc.paragraphs):
        logger.error(f'Paragraph index {para_index} out of range')
        return 0.0
    para = doc.paragraphs[para_index]
    if not para.runs:
        logger.error(f'Paragraph {para_index} has no runs')
        return 0.0
    for run in para.runs:
        if run.text.strip():
            if must_be_underlined and (not run.underline):
                logger.info(f"Found non-underlined text in paragraph {para_index}: '{run.text}'")
                return 0.0
            elif not must_be_underlined and run.underline:
                logger.info(f"Found underlined text in paragraph {para_index}: '{run.text}'")
                return 0.0
    logger.info(f'Paragraph {para_index} underline check passed')
    return 1.0

def check_docx_title_format__19c013d2(result, expected, **options):
    """Check if the docx has the required title formatting and content.

    Args:
        result: Dict with 'title' and 'content' keys from getter
        expected: Dict with validation requirements
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        logger.error('Result is None')
        return 0.0
    score = 0.0
    title = result.get('title', {})
    content = result.get('content', {})
    title_text = title.get('text', '').lower()
    title_keywords = expected.get('title_keywords', ['python', 'programming language'])
    if all((keyword.lower() in title_text for keyword in title_keywords)):
        score += 0.25
        logger.info(f'✓ Title contains required keywords {title_keywords} (+0.25)')
    else:
        logger.info(f"✗ Title missing keywords. Expected {title_keywords}, got: '{title.get('text', '')}'")
    if expected.get('must_be_centered', True):
        if title.get('is_centered'):
            score += 0.25
            logger.info('✓ Title is centered (+0.25)')
        else:
            logger.info('✗ Title is not centered')
    if expected.get('must_be_bold', True):
        if title.get('is_bold'):
            score += 0.25
            logger.info('✓ Title is bold (+0.25)')
        else:
            logger.info('✗ Title is not bold')
    min_content_words = expected.get('min_content_words', 50)
    content_word_count = content.get('word_count', 0)
    if content_word_count >= min_content_words:
        score += 0.25
        logger.info(f'✓ Content has {content_word_count} words (>= {min_content_words}) (+0.25)')
    else:
        logger.info(f'✗ Content has only {content_word_count} words (expected >= {min_content_words})')
    logger.info(f'Final score: {score:.2f}')
    return score

def check_docx_has_headings__ca69839e(result, expected, **options):
    """Check if document has heading styles, content, and Chrome history was visited.

    Args:
        result: Dict with 'has_headings', 'heading_count', 'content_char_count', 'chrome_history_visited' from getter
        expected: Dict with requirements
        **options: Additional options

    Returns:
        float: Score 1.0 if all checks pass, 0.0 otherwise
    """
    if not result:
        logger.error('No result data from getter')
        return 0.0
    requires_headings = expected.get('requires_headings', True)
    min_headings = expected.get('min_headings', 1)
    if requires_headings and result.get('heading_count', 0) < min_headings:
        logger.error(f"Document missing required headings. Found {result.get('heading_count', 0)}, expected at least {min_headings}")
        return 0.0
    logger.info(f"✓ Document has {result.get('heading_count', 0)} headings (required: {min_headings})")
    min_content_chars = expected.get('min_content_chars', 50)
    actual_content_chars = result.get('content_char_count', 0)
    if actual_content_chars < min_content_chars:
        logger.error(f'Document has insufficient content. Found {actual_content_chars} characters, expected at least {min_content_chars}')
        return 0.0
    logger.info(f'✓ Document has {actual_content_chars} characters of content (required: {min_content_chars})')
    chrome_history_url = expected.get('chrome_history_url', None)
    if chrome_history_url:
        chrome_visited = result.get('chrome_history_visited', False)
        if not chrome_visited:
            logger.error(f'Chrome history check failed. Expected to find {chrome_history_url} in browsing history')
            return 0.0
        logger.info(f'✓ Chrome history shows {chrome_history_url} was visited')
    logger.info('✓ All checks passed')
    return 1.0

