def check_docx_italic_text__55470d71(result, expected, **options):
    """
    Check if a specific paragraph has italic formatting.

    Args:
        result: File bytes from vm_file getter
        expected: Dict with 'rules' containing:
            - paragraph_contains: Text that identifies the target paragraph
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        paragraph_contains = expected.get('paragraph_contains', '')
        doc = Document(io.BytesIO(result))
        for para in doc.paragraphs:
            if paragraph_contains in para.text:
                total_chars = 0
                italic_chars = 0
                for run in para.runs:
                    run_length = len(run.text)
                    total_chars += run_length
                    if run.italic:
                        italic_chars += run_length
                if total_chars == 0:
                    return 0.0
                ratio = italic_chars / total_chars
                if ratio >= 0.8:
                    return 1.0
                else:
                    return ratio / 0.8
        return 0.0
    except Exception as e:
        print(f'Error in check_docx_italic_text__55470d71: {e}')
        return 0.0

