def check_docx_underlined_text__f997bf9f(result, expected, **options):
    """
    Check if a specific text is underlined in the document title.

    Args:
        result: Path to the docx file
        expected: Expected rules dict with 'target_text' key
        **options: Additional options

    Returns:
        float: 1.0 if text is underlined in the title, 0.0 otherwise
    """
    if not result:
        return 0.0
    try:
        doc = Document(result)
        target_text = expected.get('target_text', '')
        if not target_text:
            return 0.0
        title_paragraph = None
        if doc.paragraphs and doc.paragraphs[0].text.strip():
            title_paragraph = doc.paragraphs[0]
        if title_paragraph is None:
            return 0.0
        para = title_paragraph
        for run in para.runs:
            text = run.text
            if target_text in text and run.underline:
                return 1.0
        para_text = ''
        underlined_segments = []
        current_segment = ''
        for run in para.runs:
            if run.underline:
                current_segment += run.text
            elif current_segment:
                underlined_segments.append(current_segment)
                current_segment = ''
        if current_segment:
            underlined_segments.append(current_segment)
        for segment in underlined_segments:
            if target_text in segment:
                return 1.0
        return 0.0
    except Exception as e:
        logger.error(f'Error checking document: {e}')
        return 0.0

def check_content_font_size__69e2c85e(result_file, expected, **options):
    """
    Check if the content font size matches the expected size.

    Args:
        result_file: Path to the PPTX file
        expected: Expected values with 'slide_idx', 'shape_idx', 'expected_size_pt'
        **options: Additional options

    Returns:
        float: 1.0 if font size matches expected, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        shape_idx = expected.get('shape_idx', 1)
        expected_size_pt = expected.get('expected_size_pt', 20)
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            return 0.0
        shape = slide.shapes[shape_idx]
        if not hasattr(shape, 'text_frame'):
            return 0.0
        for paragraph in shape.text_frame.paragraphs:
            for run in paragraph.runs:
                if run.font.size is not None:
                    actual_size_pt = run.font.size.pt
                    if abs(actual_size_pt - expected_size_pt) < 0.5:
                        return 1.0
        return 0.0
    except Exception as e:
        return 0.0

def check_font_size__d996a712(result, expected, **options):
    """
    Check if Chrome's default font size is at least the expected minimum.
    This metric checks for a minimum font size of 21px.
    
    Args:
        result: Font size data from getter (dict with 'default_font_size' key)
        expected: Expected font size range (dict with 'min' and 'max' keys)
        **options: Additional options (not used)
    
    Returns:
        float: 1.0 if font size is within range, 0.0 otherwise
    """
    if not result:
        logger.error('No font size data provided')
        return 0.0
    if not isinstance(result, dict):
        logger.error(f'Invalid result format: {type(result)}, expected dict')
        return 0.0
    default_font_size = result.get('default_font_size', 16)
    min_value = expected.get('min', 21)
    max_value = expected.get('max', 99999)
    logger.info(f'Expected font size range: [{min_value}, {max_value}]px')
    logger.info(f'Actual font size: {default_font_size}px')
    if min_value <= default_font_size <= max_value:
        logger.info('Font size is within expected range')
        return 1.0
    else:
        logger.info(f'Font size out of range: expected [{min_value}, {max_value}], got {default_font_size}')
        return 0.0
